// Єремії — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Слова Єремії, сина Хелкіїного, зі священиків у Анафофі, у землі Веніаміновій,","до якого було слово Господнє у дні Іосії, сина Амонового, царя Юдейського, у тринадцятий рік царювання його,","і також у дні Іоакима, сина Іосіїного, царя Юдейського, до кінця одинадцятого року Седекії, сина Іосіїного, царя Юдейського, до переселення Єрусалима у п’ятому місяці.","І було до мене слово Господнє:","перше ніж Я утворив тебе в утробі, Я пізнав тебе, і перше ніж ти вийшов з утроби, Я освятив тебе: пророком для народів поставив тебе.","А я сказав: о, Господи Боже! я не вмію говорити, бо я ще молодий.","Але Господь сказав мені: не говори: «я молодий»; бо до всіх, до кого пошлю тебе, підеш, і все, що повелю тобі, скажеш.","Не бійся їх; бо Я з тобою, щоб спасати тебе, сказав Господь.","І простяг Господь руку Свою, і торкнувся вуст моїх, і сказав мені Господь: ось, Я вклав слова Мої у вуста твої.","Дивися, Я поставив тебе у цей день над народами і царствами, щоб викорінювати і розоряти, губити і руйнувати, творити і насаджувати.","І було слово Господнє до мене: що бачиш ти, Єреміє? Я сказав: бачу жезл мигдалевого дерева.","Господь сказав мені: ти правильно бачиш; Я пильную над словом Моїм, щоб воно скоро сповнилося.","І було слово Господнє до мене іншого разу: що бачиш ти? Я сказав: бачу киплячий казан, який піддувається вітром, і лице його з боку півночі.","І сказав мені Господь: від півночі відкриється біда на усіх жителів цієї землі.","Бо ось, Я прикличу усі племена царств північних, — говорить Господь, — і прийдуть вони, і поставлять кожен престіл свій біля входу у ворота Єрусалима, і навколо усіх стін його, і у всіх містах юдейських.","І вчиню над ними суди Мої за усі беззаконня їхні, за те, що вони залишили Мене, і курили фіміам чужоземним богам і поклонялися ділам рук своїх.","А ти опояши стегна твої, і встань, і скажи їм усе, що Я повелю тобі; не будь слабкодухим перед ними, щоб Я не уразив тебе в очах їхніх.","І ось, Я поставив тебе нині укріпленим містом і залізним стовпом і мідною стіною на усій цій землі, проти царів Іуди, проти князів його, проти священиків його і проти народу землі цієї.","Вони будуть воювати проти тебе, але не переможуть тебе; тому що Я з тобою, — говорить Господь, — щоб спасати тебе."],"x":{"1":"12.6.60","2":"11.21.26","3":"11.23.34","5":"65.1.15","6":"1.4.10","8":"4.31.6:8|36.3.9|5.11.6","9":"31.6.7|32.5.14","10":"30.49.9|32.18.7","12":"37.9.14|57.2.3","14":"32.4.6|32.10.22|32.13.20","15":"32.5.15","17":"52.12.35|56.1.13","18":"32.15.20|36.3.8"}},{"v":["І було слово Господнє до мене:","йди і проголоси у вуха дочки Єрусалима: так говорить Господь: Я згадую про дружбу юности твоєї, про любов твою, коли ти була нареченою, коли пішла за Мною у пустелю, у землю незасіяну.","Ізраїль був святинею Господа, початком плодів Його; усі, хто поїдав його, були засуджувані, біди осягали їх, — говорить Господь.","Вислухайте слово Господнє, доме Якова і всі роди дому Ізраїлевого!","Так говорить Господь: яку неправду знайшли у Мені батьки ваші, що віддалилися від Мене і пішли за суєтою, й осуєтились,","і не сказали: «де Господь, Який вивів нас із землі Єгипетської, вів нас пустелею, землею порожньою і ненаселеною, землею сухою, землею тіні смертної, по якій ніхто не ходив і де не жила людина?»","І Я ввів вас у землю плодючу, щоб ви годувалися плодами її і добром її; а ви увійшли й осквернили землю Мою, і надбання Моє зробили мерзотою.","Священики не говорили: «де Господь?», і вчителі закону не знали Мене, і пастирі відпали від Мене, і пророки пророкували в ім’я Ваала і ходили слідом тих, які не допомагають.","Тому Я ще буду судитися з вами, — говорить Господь, — і з синами синів ваших буду судитися.","Бо підіть на острови хиттимські і подивіться, і пошліть у Кидар і розвідайте старанно, і розгляньте: чи було там що-небудь подібне до цього?","чи перемінив який народ богів своїх; хоч вони і не боги? а Мій народ проміняв славу свою на те, що не допомагає.","Подивуйтеся цьому, небеса, і здригніться, і жахніться, — говорить Господь.","Бо два зла зробив народ Мій: Мене, джерело води живої, залишили, і висікли собі водойми розбиті, які не можуть тримати води.","Хіба Ізраїль раб? або він домочадець? чому він зробився здобиччю?","Зарикали на нього молоді леви, подали голос свій і зробили землю його пустелею; міста його спалені, без жителів.","І сини Мемфиса і Тафни об’їли тім’я твоє.","Чи не заподіяв ти собі це тим, що залишив Господа Бога твого у той час, коли Він вів тебе у дорозі?","І нині для чого тобі путь у Єгипет, щоб пити воду з Нілу? і для чого тобі путь в Ассирію, щоб пити воду з ріки її?","Покарає тебе нечестя твоє, і відступництво твоє викриє тебе; отже, пізнай і розміркуй, як погано і гірко те, що ти залишив Господа Бога твого і страху Мого немає у тобі, — говорить Господь Бог Саваоф.","Бо здавна Я скрушив ярмо твоє, розірвав кайдани твої, і ти говорив: «не буду служити ідолам», а між тим на усякому високому пагорбі і під усяким гіллястим деревом ти блудодіяв.","Я насадив тебе як благородну лозу, — найчистіше насіння; як же ти перетворилася у Мене на дикий паросток чужої лози?","Тому, хоч би ти умився милом і багато ужив на себе лугу, нечестя твоє відзначене переді Мною, — говорить Господь Бог.","Як можеш ти сказати: «я не осквернив себе, я не ходив слідом Ваала?» Подивися на поведінку твою у долині, пізнай, що робила ти, жвава верблюдиця, яка гасає по шляхах твоїх?","Звиклу до пустелі дику ослицю, яка у пристрасті душі своєї ковтає повітря, хто може утримати? Усі, хто шукає її, не стомляться: у її місяці вони знайдуть її.","Не давай ногам твоїм стоптувати взуття, і гортані твоїй — знемагати від спраги. Але ти сказав: «не надійся, ні! бо люблю чужих і буду ходити слідом за ними».","Як злодій, коли впіймають його, буває осоромлений, так осоромив себе дім Ізраїлів: вони, царі їх, князі їх, і священики їх, і пророки їх, —","говорячи дереву: «ти мій батько», і каменю: «ти народив мене»; бо вони повернули до Мене спину, а не лице; а під час біди своєї будуть говорити: «встань і спаси нас!»","Де ж боги твої, яких ти зробив собі? — нехай вони встануть, якщо можуть спасти тебе у час біди твоєї; бо скільки в тебе міст, стільки і богів у тебе, Іудо.","Для чого вам змагатися зі Мною? — усі ви [нечестиво чинили і] грішили проти Мене, — говорить Господь.","Даремно вражав Я дітей ваших: вони не прийняли напоумлення; пророків ваших пожирав меч ваш, як лев, який винищує [, і ви не убоялись].","О, роде! слухайте ви слово Господнє: чи був Я пустелею для Ізраїля? чи був Я країною мороку? Навіщо ж народ Мій говорить: «ми самі собі господарі; ми вже не прийдемо до Тебе»?","Чи забуває дівчина прикрасу свою і наречена — вбрання своє? а народ Мій забув Мене, — немає числа дням.","Як майстерно направляєш ти шляхи твої, щоб здобути любов! і для того навіть до злочинів пристосовувала ти шляхи твої.","Навіть на полах одягу твого знаходиться кров людей бідних, невинних, яких ти не застала при зламі, і, незважаючи на все це,","говориш: «оскільки я невинна, то, напевне, гнів Його відвернеться від мене». Ось, Я буду судитися з тобою за те, що говориш: «я не згрішила».","Навіщо ти так багато бродиш, змінюючи путь твою? Ти так само будеш посоромлена і Єгиптом, як була посоромлена Ассирією;","і від нього ти вийдеш, поклавши руки на голову, тому що відкинув Господь надії твої, і не будеш мати з ними успіху."],"x":{"2":"36.16.8|38.9.10","3":"1.19.6|25.113.2","5":"43.6.3-4","6":"4.8.15","7":"4.8.1|2.25.23","8":"62.2.20-21","10":"32.18.13","11":"62.1.23","13":"25.35.10|62.1.25|57.2.17","15":"25.53.5|31.5.29|32.4.7","16":"31.19.13|31.30.4","17":"4.29.25|10.9.8-9","18":"31.30.2|38.5.13","19":"31.3.9|38.5.5","20":"25.2.3|31.57.5|32.3.6","21":"1.15.17|31.5.1-2|50.21.33|51.12.1","22":"24.9.30","23":"32.7.32|32.32.35","25":"32.18.12","26":"32.48.27|36.28.17|37.9.8","27":"32.3.9|38.4.12|10.14.9","28":"32.11.13","29":"25.52.4","30":"31.1.5|32.5.3","32":"32.3.21|32.18.14|36.23.35","35":"31.1.18|36.17.20|39.3.2","36":"13.28.21|32.2.18","37":"9.13.19|32.32.5"}},{"v":["Говорять: «якщо чоловік відпустить дружину свою, і вона відійде від нього і зробиться дружиною іншого чоловіка, то чи може вона повернутися до нього? Чи не осквернилася б цим країна та?» А ти з багатьма коханцями блудодіяла, — і однак же повернися до Мене, — говорить Господь.","Зведи очі твої на висоти і подивися, де не блудодіяли з тобою? Біля дороги сиділа ти для них, як аравитянин у пустелі, й осквернила землю блудом твоїм і лукавством твоїм.","За те були утримані дощі, і не було дощу пізнього; але у тебе було чоло блудниці, ти відкинула сором.","Чи не будеш ти відтепер волати до Мене: «Отче мій! Ти був путівником юности моєї!","Невже завжди буде Він у гніві? і невже вічно буде утримувати його у Собі?» Ось, що говориш ти, а робиш зло і досягаєш успіхів у ньому.","Господь сказав мені у дні Іосії царя: чи бачив ти, що робила відступниця, дочка Ізраїля? Вона ходила на всяку високу гору і під усяке гіллясте дерево і там блудодіяла.","І після того, як вона усе це робила, Я говорив: «повернися до Мене»; але вона не повернулася; і бачила це віроломна сестра її Юдея.","І Я бачив, що, коли за усі перелюбні дії відступниці, дочки Ізраїля, Я відпустив її і дав їй розвідний лист, віроломна сестра її Юдея не убоялась, а пішла і сама блудодіяла.","І неприхованим блудодійством вона осквернила землю, і перелюбствувала з каменем і деревом.","Але при усьому цьому віроломна сестра її Юдея не навернулася до Мене усім серцем своїм, а тільки удавано, — говорить Господь.","І сказав мені Господь: відступниця, дочка Ізраїлева, виявилася правішою, ніж віроломна Юдея.","Йди і проголоси слова ці на північ, і скажи: навернися, відступнице, дочко Ізраїлева, — говорить Господь. Я не виллю на вас гніву Мого; бо Я милостивий, — говорить Господь, — не вічно буду обурюватися.","Визнай тільки провину твою: бо ти відступила від Господа Бога твого і блудодіяла з чужими під усяким гіллястим деревом, а голосу Мого ви не слухали, — говорить Господь.","Поверніться, діти-відступники, — говорить Господь, — тому що Я поєднався з вами, і візьму вас по одному з міста, по двоє із племені, і приведу вас на Сион.","І дам вам пастирів за серцем Моїм, які будуть пасти вас зі знанням і розсудливістю.","І буде, коли ви розмножитеся і зробитеся багатоплідними на землі, у ті дні, — говорить Господь, — не будуть говорити більше: «ковчег завіту Господнього»; він і на думку не спаде, і не згадають про нього, і не будуть приходити до нього, і його вже не буде.","У той час назвуть Єрусалим престолом Господа; і всі народи заради імені Господа зберуться в Єрусалим і не будуть більше чинити за впертістю злого серця свого.","У ті дні прийде дім Іудин до дому Ізраїлевого, і підуть разом із землі північної у землю, яку Я дав у спадщину батькам вашим.","І говорив Я: як поставлю тебе у число дітей і дам тобі жадану землю, найпрекраснішу спадщину багатьох народів? І сказав: ти будеш називати Мене отцем твоїм і не відступиш від Мене.","Але воістину, як дружина віроломно зраджує друга свого, так віроломно вчинили зі Мною ви, дім Ізраїлів, — говорить Господь.","Голос чутно на висотах, жалібний плач синів Ізраїля за те, що вони спотворили шлях свій, забули Господа Бога свого.","Поверніться, бунтівливі діти: Я зцілю вашу непокору. — Ось, ми йдемо до Тебе, бо Ти — Господь Бог наш.","Воістину, марно надіялися ми на пагорби і на безліч гір; воістину, у Господі Бозі нашому спасіння Ізраїлеве!","Від юности нашої ця мерзота пожирала труди батьків наших, овець їхніх і волів їхніх, синів їхніх і дочок їхніх.","Ми лежимо у соромі своєму, і сором наш покриває нас, тому що ми грішили перед Господом Богом нашим, — ми і батьки наші, від юности нашої і до цього дня, і не слухалися голосу Господа Бога нашого."],"x":{"1":"4.24.4","2":"36.16.24","4":"50.6.9|36.16.43","6":"32.2.20","7":"36.16.46|36.23.2","8":"36.23.11","9":"32.2.27","11":"36.16.52","12":"31.31.6|1.34.6|39.2.13|48.1.3","13":"31.57.5","14":"31.31.6","15":"32.23.4","17":"31.2.2","18":"38.1.11|32.31.8","19":"25.86.4|31.60.4","20":"32.2.8","22":"38.3.5","23":"25.120.1","24":"38.4.19","25":"32.14.7"}},{"v":["Якщо хочеш навернутися, Ізраїлю, — говорить Господь, — до Мене навернися; і якщо видалиш мерзоти твої від лиця Мого, то не будеш блукати.","І будеш клястися: «живий Господь!» в істині, суді і правді; і народи будуть Ним благословлятися і Ним хвалитися.","Бо так говорить Господь до мужів Іуди та Єрусалима: розоріть собі нові ниви і не сійте між терням.","Обріжте себе для Господа, і зніміть крайню плоть із серця вашого, мужі Іуди і жителі Єрусалима, щоб гнів Мій не відкрився, як вогонь, і не запалав невгасимо через вашу схильність до зла.","Оголосіть в Юдеї і розголосіть у Єрусалимі, і говоріть, і сурміть трубою по землі; волайте голосно і говоріть: «зберіться, і підемо в укріплені міста».","Виставте знамено до Сиону, біжіть, не зупиняйтеся, бо Я приведу від півночі біду і велику загибель.","Виходить лев зі своїх хащів, і виступає винищувач народів: він виходить зі свого місця, щоб землю твою зробити пустелею; міста твої будуть розорені, залишаться без жителів.","Тому опояшіться веретищем, плачте і ридайте, бо лють гніву Господнього не відвернеться від нас.","І буде у той день, — говорить Господь, — завмре серце в царя і серце в князів; і жахнуться священики, і здивуються пророки.","І сказав я: о, Господи Боже! Невже Ти зваблював тільки народ цей і Єрусалим, говорячи: «мир буде у вас»; а тим часом меч доходить до душі?","У той час сказано буде народу цьому і Єрусалиму: пекучий вітер несеться з висот пустельних на шлях дочки народу Мого, не для віяння і не для очищення;","і прийде до Мене звідти вітер сильніший за цей, і Я сотворю суд над ними.","Ось, піднімається він подібно до хмар, і колісниці його — як вихор, коні його швидші за орлів; горе нам! бо ми будемо розорені.","Змий зле із серця твого, Єрусалиме, щоб спастися тобі: доки будуть гніздитися у тобі злочесні думки?","Бо уже несеться голос від Дана і згубна звістка з гори Єфремової:","оголосіть народам, сповістіть Єрусалим, що йдуть з далекої країни ті, що беруть в облогу, і криками своїми наповнюють міста Юдеї.","Як вартові полів, вони обступають його навкруги, бо він збурився проти Мене, — говорить Господь.","Шляхи твої і діяння твої заподіяли тобі це; від твого нечестя тобі так гірко, що доходить до серця твого.","Утроба моя! утроба моя! тужу в глибині серця мого, хвилюється у мені серце моє, не можу мовчати; бо ти чуєш, душе моя, звук труби, тривогу битви.","Біда за бідою: уся земля спустошується, раптово розорені шатри мої, миттєво — намети мої.","Чи довго бачити мені знамено, слухати звук труби?","Це від того, що народ Мій нерозумний, не знає Мене: нерозумні вони діти, і немає у них глузду; вони розумні на зло, але добра робити не вміють.","Дивлюся на землю, і ось, вона розорена і порожня, — на небеса, і немає від них світла.","Дивлюся на гори, і ось, вони тремтять, і всі пагорби коливаються.","Дивлюсь, і ось, немає людини, і всі птахи небесні розлетілися.","Дивлюсь, і ось, Кармил — пустеля, і всі міста його зруйновані від лиця Господа, від люті гніву Його.","Бо так сказав Господь: уся земля буде спустошена, але остаточного знищення не зроблю.","Заплаче про це земля, і небеса затьмаряться угорі, тому що Я сказав, Я визначив, і не розкаюся у тім, і не відступлю від того.","Від шуму вершників і стрільців розбіжаться всі міста: вони підуть у густі ліси і вилізуть на скелі; всі міста будуть залишені, і не буде у них жодного жителя.","А ти, спустошена, що будеш робити? Хоч ти вдягаєшся в пурпур, хоч прикрашаєш себе золотим убранням, обмальовуєш очі твої фарбами, але марно прикрашаєш себе: знехтували тебе коханці, вони шукають душі твоєї.","Бо Я чую голос ніби жінки у пологах, стогін ніби тієї, що народжує вперше, голос дочки Сиону; вона стогне, простягаючи руки свої: «о, горе мені! душа моя знемагає перед убивцями»."],"x":{"2":"4.6.13|4.10.20|31.45.25","3":"38.10.12","4":"4.10.16|32.21.12","5":"32.8.14","6":"32.1.14","7":"31.5.29|31.34.5|32.2.15","8":"32.6.26","9":"36.32.10","10":"32.6.14","11":"32.18.17|32.51.1","12":"32.1.16","13":"45.1.8","14":"31.1.16","15":"32.8.16","16":"32.2.15","18":"29.1.8","19":"31.22.4|32.9.1","22":"52.16.4","23":"31.5.30","25":"32.9.10|32.50.3","26":"32.2.7","27":"36.12.20|36.14.22|32.5.10","28":"32.18.8","29":"32.4.25","31":"33.1.20|32.6.24|32.13.21"}},{"v":["Походіть по вулицях Єрусалима, і подивіться, і розвідайте, і пошукайте на площах його, чи не знайдете людину, чи немає того, хто дотримується правди, хто шукає істину? Я пощадив би Єрусалим.","Хоч і говорять вони: «живий Господь!», але клянуться неправдиво.","О, Господи! очі Твої чи не до істини звернені? Ти вражаєш їх, а вони не відчувають болю; Ти знищуєш їх, а вони не хочуть прийняти напоумлення; лиця свої вони зробили міцнішими за камінь, не хочуть навернутися.","І сказав я сам у собі: це, можливо, бідняки; вони дурні, тому що не знають шляхів Господніх, закону Бога свого;","піду я до знатних і поговорю з ними, бо вони знають путь Господню, закон Бога свого. Але і вони усі розбили ярмо, розірвали кайдани.","За те вразить їх лев з лісу, вовк пустельний спустошить їх, барс буде підстерігати біля міст їхніх: хто вийде з них, буде розтерзаний; бо примножилися злочини їхні, посилилися відступництва їхні.","Як же Мені простити тебе за це? Сини твої залишили Мене і клянуться тими, які не боги. Я насичував їх, а вони перелюбствували і натовпами ходили у доми блудниць.","Це відгодовані коні: кожен з них ірже на дружину іншого.","Невже Я не покараю за це? — говорить Господь; і чи не помститься душа Моя такому народові, як цей?","Виходьте на стіни його і руйнуйте, але не до кінця; знищіть зубці їх, тому що вони не Господні;","бо дім Ізраїлів і дім Іудин вчинили зі Мною дуже віроломно, — говорить Господь:","вони сказали неправду на Господа і сказали: «немає Його, і біда не прийде на нас, і ми не побачимо ні меча, ні голоду.","І пророки стануть вітром, і сло́ва [Господнього] немає у них; над ними самими нехай це буде».","Тому так говорить Господь Бог Саваоф: за те, що ви говорите такі слова, ось, Я зроблю слова Мої у вустах твоїх вогнем, а цей народ — дровами, і цей вогонь пожере їх.","Ось, Я приведу на вас, дім Ізраїлів, народ здалеку, — говорить Господь, — народ сильний, народ древній, народ, якого мови ти не знаєш, і не будеш розуміти, що він говорить.","Сагайдак його — як відкритий гріб; усі вони люди хоробрі.","І з’їдять вони жниво твоє і хліб твій, з’їдять синів твоїх і дочок твоїх, з’їдять овець твоїх і волів твоїх, з’їдять виноград твій і смокви твої; зруйнують мечем укріплені міста твої, на які ти надієшся.","Але й у ті дні, — говорить Господь, — не знищу вас до кінця.","І якщо ви скажете: «за що Господь, Бог наш, робить нам усе це?», то відповідай: оскільки ви залишили Мене і служили чужим богам у землі своїй, то будете служити чужим у землі не вашій.","Оголосіть це у домі Якова і сповістіть у Юдеї, говорячи:","вислухай це, народе дурний і нерозумний, в якого є очі, а не бачить, у якого є вуха, а не чує:","чи Мене ви не боїтеся, — говорить Господь, — чи переді Мною не тремтите? Я поклав пісок межею морю, вічною межею, яку не перейде; і хоч хвилі його намагаються, але перемогти не можуть; хоч вони бушують, але переступити його не можуть.","А у народу цього серце буйне і бунтівне; вони відступили і пішли;","і не сказали у серці своєму: «убоїмся Господа Бога нашого, Який дає нам дощ ранній і пізній у свій час, зберігає для нас седмиці, призначені для жнив».","Беззаконня ваші відвернули це, і гріхи ваші віддалили від вас це добре.","Бо між народом Моїм знаходяться нечестиві: вартують, як птахолови, припадають до землі, ставлять пастки й уловлюють людей.","Як клітка, наповнена птахами, доми їхні повні обману; через це вони і піднеслися і розбагатіли,","зробилися повні, жирні, переступили навіть усяку міру у злі, не розбирають судових справ, справ сиріт; благоденствують, і справедливій справі убогих не дають суду.","Невже Я не покараю за це? — говорить Господь; і чи не помститься душа Моя такому народові, як цей?","Дивне і жахливе відбувається на цій землі:","пророки пророкують неправду, і священики панують за допомогою їх, і народ Мій любить це. Що ж ви будете робити після усього цього?"],"x":{"1":"0.18.24|25.13.2|32.6.6","3":"31.1.5|31.9.13","5":"25.2.3","6":"32.4.7|46.3.3|38.13.7","7":"4.32.21|38.13.6|32.23.10","8":"32.13.27|36.22.11","9":"32.9.9","10":"50.24.6|32.4.27","12":"31.28.15","13":"32.22.22","14":"32.1.9","15":"4.28.49|32.1.15","17":"2.26.17","18":"32.4.27","19":"32.13.22|32.16.10|4.28.36","21":"31.6.9|50.13.14|51.4.12|52.8.10|53.12.40|54.28.26|62.11.8","22":"24.38.8","23":"4.31.27","24":"4.11.14","26":"26.1.11","28":"4.32.15|31.1.23|48.7.10","29":"32.9.9","31":"32.23.25|36.13.6"}},{"v":["Біжіть, діти Веніамінові, із середовища Єрусалима, й у Фекої сурміть трубою і дайте знати вогнем у Бефкаремі, бо від півночі з’являється біда і велика загибель.","Розорю Я дочку Сиону, красиву і зніжену.","Пастухи зі своїми стадами прийдуть до неї, розкинуть намети навколо неї; кожен буде пасти свою ділянку.","Готуйте проти неї війну; вставайте і підемо опівдні. Горе нам! день уже схиляється, розпростираються вечірні тіні,","Вставайте, підемо і вночі, і зруйнуємо чертоги її!","Бо так говорить Господь Саваоф: рубайте дерева і робіть насип проти Єрусалима: це місто має бути покаране; у ньому всяке гноблення.","Як джерело вивергає із себе воду, так воно виточує із себе зло: у ньому чутно насильство і грабіжництво, перед лицем Моїм завжди обра́зи і рани.","Врозумися, Єрусалиме, щоб душа Моя не віддалилася від тебе, щоб Я не зробив тебе пустелею, землею ненаселеною.","Так говорить Господь Саваоф: до кінця обберуть залишок Ізраїля, як виноград; працюй рукою твоєю, як збирач винограду, наповнюючи кошики.","До кого мені говорити і кого напоумлювати, щоб слухали? Ось, вухо у них необрізане, і вони не можуть слухати; ось, слово Господнє в них у посміянні; воно неприємне їм.","Тому я переповнений люттю Господньою, не можу тримати її у собі; виллю її на дітей на вулиці і на зібрання юнаків; узяті будуть чоловік з дружиною, літній з тим, хто віджив літа́.","І доми їхні перейдуть до інших, також поля і дружини; тому що Я простягну руку Мою на жителів цієї землі, — говорить Господь.","Бо від малого до великого, кожен з них відданий користолюбству, і від пророка до священика — усі діють облудно;","лікують рани народу Мого легковажно, говорячи: «мир! мир!», а миру немає.","Чи соромляться вони, роблячи мерзоти? ні, ніскільки не соромляться і не червоніють. За те впадуть між убитими, і під час відвідування Мого будуть повалені, — говорить Господь.","Так говорить Господь: зупиніться на шляхах ваших і розгляньте, і розпитайте про путі древніх, де путь добра, і йдіть нею, і знайдете спокій душам вашим. Але вони сказали: «не підемо».","І поставив Я вартових над вами, сказавши: «слухайте звук труби». Але вони сказали: «не будемо слухати».","Отже, слухайте, народи, і знай, зібрання, що з ними буде.","Слухай, земле: ось, Я приведу на народ цей згубу, плід помислів їх; бо вони слів Моїх не слухали і закон Мій відкинули.","Для чого Мені ладан, який іде із Сави, і запашна тростина з далекої країни? Всепалення ваші неугодні, і жертви ваші неприємні Мені.","Тому так говорить Господь: ось, Я покладу перед народом цим спотикання, і спотикнуться об них батьки і діти разом, сусід і друг його, і загинуть.","Так говорить Господь: ось, іде народ від країни північної, і народ великий піднімається від країв землі;","тримають у руках лук і спис; вони жорстокі і немилосердні, голос їх шумить, як море, і несуться на конях, вишикувані, як одна людина, щоб воювати з тобою, дочко Сиону.","Ми почули звістку про них, і руки у нас опустилися, скорбота охопила нас, муки, як жінку при пологах.","Не виходьте в поле і не ходіть дорогою, бо меч ворогів, жах з усіх боків.","Дочко народу мого! опояши себе веретищем і посипай себе попелом; тужи, ніби про смерть єдиного сина, гірко плач; бо раптово прийде на нас згубник.","Вежею поставив Я тебе серед народу Мого, стовпом, щоб ти знав і стежив за шляхом їх.","Усі вони — вперті відступники, живуть наклепами; це мідь і залізо, — усі вони розбещувачі.","Роздувальний міх обгорів, свинець зотлів від вогню: плавильник плавив даремно, бо злі не відокремилися;","відкинутим сріблом назвуть їх, тому що Господь відкинув їх."],"x":{"1":"3.10.9|32.4.5","3":"32.12.10","4":"32.51.27","6":"31.5.7","7":"32.9.3","9":"32.8.13|32.17.6","10":"54.7.51-52","11":"32.7.20","12":"4.28.30","13":"31.56.11|32.8.10","14":"32.8.11|32.23.17","15":"32.18.11","16":"32.18.15|50.11.29","17":"31.62.6","19":"3.14.35|31.1.2","20":"31.1.11|40.5.21|43.6.7","22":"4.28.49|32.5.15|32.50.41","24":"32.4.31","25":"50.24.17","26":"32.4.8","27":"32.1.10","28":"36.22.18","30":"31.1.22"}},{"v":["Слово, яке було до Єремії від Господа:","стань у воротах дому Господнього і проголоси там слово це і скажи: слухайте слово Господнє, усі юдеї, що входять цими вратами на поклоніння Господу.","Так говорить Господь Саваоф, Бог Ізраїлів: виправте шляхи ваші і діяння ваші, і Я залишу вас жити на цьому місці.","Не надійтеся на оманливі слова: «тут храм Господній, храм Господній, храм Господній».","Але якщо зовсім виправите шляхи ваші і діяння ваші, якщо будете правильно чинити суд між людиною і суперником її,","не будете пригноблювати іноземця, сироти і вдови, і проливати невинної крови на місці цьому, і не підете слідом інших богів на біду собі, —","то Я залишу вас жити на місці цьому, на цій землі, яку дав батькам вашим у роди родів.","Ось, ви надієтеся на оманливі слова, які не принесуть вам користи.","Як! ви крадете, убиваєте і перелюбствуєте, і клянетеся у неправді і кадите Ваалу, і ходите слідом інших богів, яких ви не знаєте,","і потім приходите і стаєте перед лицем Моїм у домі цьому, над яким наречене ім’я Моє, і говорите: «ми спасені», щоб надалі чинити усі ці мерзоти.","Чи не зробився вертепом розбійників у очах ваших дім цей, над яким наречене ім’я Моє? Ось, Я бачив це, — говорить Господь.","Підіть же на місце Моє у Силом, де Я раніше призначив перебувати імені Моєму, і подивіться, що зробив Я з ним за нечестя народу Мого Ізраїля.","І нині, тому що ви робите усі ці діла, — говорить Господь, — і Я говорив вам з раннього ранку, а ви не слухали, і кликав вас, а ви не відповідали, —","то Я так само вчиню з домом цим, над яким наречене ім’я Моє, на який ви надієтесь, і з місцем, яке Я дав вам і батькам вашим, як учинив із Силомом.","І відкину вас від лиця Мого, як відкинув усіх братів ваших, усе сíм’я Єфремове.","Ти ж не проси за цей народ і не піднось за них молитви і прохання, і не заступайся переді Мною, бо Я не почую тебе.","Чи не бачиш, що вони роблять у містах Юдеї і на вулицях Єрусалима?","Діти збирають дрова, а батьки розводять вогонь, і жінки місять тісто, щоб робити пиріжки для богині неба і звершувати узливання іншим богам, щоб засмучувати Мене.","Але чи Мене засмучують вони? — говорить Господь; чи не себе самих на сором собі?","Тому так говорить Господь Бог: ось, проливається гнів Мій і лють Моя на місце це, на людей і на худобу, і на дерева польові і на плоди землі, і запалає і не згасне.","Так говорить Господь Саваоф, Бог Ізраїлів: всепалення ваші додавайте до жертв ваших і їжте м’ясо;","бо батькам вашим Я не говорив і не давав їм заповіді у той день, в який Я вивів їх із землі Єгипетської, про всепалення і жертву;","але таку заповідь дав їм: «слухайтеся гласу Мого, і Я буду вашим Богом, а ви будете Моїм народом, і ходіть усяким шляхом, який Я заповідаю вам, щоб вам було добре».","Але вони не послухали і не прихилили вуха свого, і жили за схильністю і впертістю злого серця свого, і стали до Мене спиною, а не лицем.","З того дня, як батьки ваші вийшли із землі Єгипетської, до цього дня Я посилав до вас усіх рабів Моїх — пророків, посилав усякий день з раннього ранку;","але вони не слухалися Мене і не прихилили вуха свого, а озлобили шию свою, чинили гірше за батьків своїх.","І коли ти будеш говорити їм усі ці слова, вони тебе не послухають; і коли будеш кликати їх, вони на дадуть тобі відповіді.","Тоді скажи їм: ось народ, який не слухає гласу Господа Бога свого і не приймає настановлення! Не стало у них істини, вона віднята від вуст їхніх.","Обстрижи волосся твоє і кинь, і здійми плач на горах, бо відкинув Господь і залишив рід, який накликав гнів Його.","Бо сини Іуди роблять зле перед очима Моїми, — говорить Господь; поставили мерзоти свої у домі, над яким наречене ім’я Моє, щоб осквернити його;","і влаштували висоти Тофета у долині синів Енномових, щоб спалювати синів своїх і дочок своїх у вогні, чого Я не повелівав і що Мені на серце не приходило.","За те ось, приходять дні, — говорить Господь, — коли не будуть більше називати місце це Тофетом і долиною синів Енномових, але долиною вбивства, і в Тофеті будуть ховати за нестачею місця.","І будуть трупи народу цього споживою птахам небесним і звірам земним, і не буде кому відганяти їх.","І припиню у містах Юдеї і на вулицях Єрусалима голос торжества і голос веселощів, голос нареченого і голос нареченої; тому що земля ця буде пустелею."],"x":{"2":"31.29.21","3":"11.17.13|32.26.13","4":"32.13.25","5":"32.5.28","6":"32.22.3","8":"31.59.4","9":"31.1.23|32.9.2","10":"31.1.12","11":"31.56.7|50.21.13|51.11.17|52.19.46","12":"5.18.1","13":"32.11.7-8|32.35.14|26.1.24|31.65.12|31.66.4","14":"8.4.12|25.77.60|32.26.6","15":"11.17.18","16":"1.32.10|32.11.14","18":"32.44.17:19","20":"32.4.4","21":"32.6.20","22":"31.1.12","23":"32.11.4","24":"32.11.8|32.16.12|32.17.23","25":"32.25.4","26":"32.6.10|1.32.8|1.33.5|4.9.13","28":"38.4.1","29":"4.32.19-20","30":"36.8.5","31":"2.18.21|11.23.10|32.19.6","32":"32.19.11","33":"32.16.4|32.34.20","34":"32.16.9|32.25.10|36.26.13"}},{"v":["У той час, — говорить Господь, — викинуть кістки царів Іуди, і кістки князів його, і кістки священиків, і кістки пророків, і кістки жителів Єрусалима із гробів їхніх;","і розкидають їх перед сонцем і місяцем і перед усім воїнством небесним*, яких вони любили і яким служили і слідом яких ходили, яких шукали і яким поклонялися; не приберуть їх і не поховають: вони будуть гноєм на землі.","І будуть смерті віддавати перевагу перед життям усі інші, які залишаться від цього злого племені в усіх місцях, куди Я вижену їх, — говорить Господь Саваоф.","І скажи їм: так говорить Господь: хіба, упавши, не встають і, збившись із дороги, не повертаються?","Для чого цей народ, Єрусалим, знаходиться у впертому відступництві? вони міцно тримаються омани і не хочуть навернутися.","Я спостерігав і слухав: не говорять вони правди, ніхто не кається у своєму нечесті, ніхто не говорить: «що я зробив?»; кожен повертається на свій шлях, як кінь, який кидається у бій.","І лелека під небом знає свої визначені часи, і горлиця, і ластівка, і журавель пильнують час, коли їм прилетіти; а народ Мій не знає визначення Господнього.","Як ви говорите: «ми мудрі, і закон Господній у нас»? А ось, неправдива тростина книжників і його перетворює на неправду.","Осоромилися мудреці, знітилися і заплутались у сіті: ось, вони відкинули слово Господнє; у чому ж мудрість їхня?","За те дружин їхніх віддам іншим, поля їхні — іншим володарям; тому що всі вони, від малого до великого, віддалися користолюбству; від пророка до священика — усі діють неправдиво.","І лікують рану дочки́ народу Мого легковажно, говорячи: «мир, мир!», а миру немає.","Чи соромляться вони, роблячи мерзоти? ні, вони ніскільки не соромляться і не червоніють. За те упадуть вони між упалими; під час відвідування їх будуть повалені, — говорить Господь.","До кінця обберу їх, — говорить Господь, — не залишиться жодної виноградини на лозі, ні смокви на смоковниці, і лист обпаде, і що Я дав їм, відійде від них.","«Чого ми сидимо? збирайтеся, підемо в укріплені міста, і там загинемо; бо Господь Бог наш призначив нас на загибель і дає нам пити воду з жовчю за те, що ми грішили перед Господом».","Чекаємо миру, а нічого доброго нема, — часу зцілення, і ось жахи.","Від Дана чутно хропіння коней його, від голосного іржання жеребців його тремтить уся земля; і прийдуть і знищать землю і все, що на ній, місто і тих, що живуть у ньому.","Бо ось, Я пошлю на вас зміїв, василисків, проти яких немає заговорювання, і вони будуть уражати вас, — говорить Господь.","Коли утішуся я у горі моєму! серце моє знемогло у мені.","Ось, чую волання дочки народу Мого з далекої країни: хіба немає Господа на Сионі? хіба немає Царя його на ньому? — Навіщо вони спонукали Мене на гнів своїми ідолами, чужоземними, нікчемними?","Минули жнива, скінчилося літо, а ми не спасені.","Про скрушення дочки народу мого я крушуся, ходжу похмурий, жах обійняв мене.","Хіба немає бальзаму в Галааді? хіба немає там лікаря? Чому ж немає зцілення дочки народу мого?"],"x":{"1":"33.2.20|11.23.16","2":"11.17.16|32.16.4","3":"76.9.6","5":"36.14.3","6":"38.4.16","7":"50.16.3|52.19.42","8":"72.3.5","9":"24.5.13","10":"31.13.16|31.56.11|32.6.13|32.23.11","11":"32.6.14","12":"32.6.15","13":"31.5.2|50.21.19|52.13.6","14":"32.4.5|32.9.15","15":"32.14.19","16":"32.4.15","17":"25.57.5","22":"32.46.11"},"n":{"2":["Перед зірками."]}},{"v":["О, хто дасть голові моїй воду й очам моїм — джерело сліз! я плакав би день і ніч про уражених дочки народу мого.","О, хто дав би мені у пустелі пристановище подорожніх! залишив би я народ мій і пішов би від них: бо усі вони перелюбники, збіговисько віроломних.","Як лук, напружують язик свій для неправди, підсилюються на землі неправдою; бо переходять від одного зла до іншого, і Мене не знають, — говорить Господь.","Стережіться кожен свого друга, і не довіряйте жодному зі своїх братів; тому що всякий брат ставить спотикання іншому, і всякий друг розносить наклепи.","Кожен обманює свого друга, і правди не говорять: привчили язик свій говорити неправду, лукавлять до втоми.","Ти живеш серед підступництва; з підступництва вони зрікаються знати Мене, — говорить Господь.","Тому так говорить Господь Саваоф: ось, Я розплавлю і випробую їх; бо як інакше Мені чинити з дочкою народу Мого?","Язик їх — убивча стріла, говорить підступно; вустами своїми говорять із ближнім своїм дружньо, а у серці своєму будують йому підступи.","Невже Я не покараю їх за це? — говорить Господь; чи не помститься душа Моя такому народові, як цей?","Про гори здійму плач і крик, і про степові пасовища — ридання, тому що вони випалені, так що ніхто там не проходить, і не чутно бекання стад: від птахів небесних до худоби — усі розсіялися, пішли.","І зроблю Єрусалим купою каміння, житлом шакалів, і міста Юдеї зроблю пустелею, без жителів.","Чи є такий мудрець, який зрозумів би це? І до кого говорять уста Господні — пояснив би, за що загинула країна і випалена, як пустеля, так що ніхто не проходить нею?","І сказав Господь: за те, що вони залишили закон Мій, який Я встановив для них, і не слухали гласу Мого і не чинили за ним;","а ходили за впертістю серця свого і слідом Ваала, як навчили їх батьки їхні.","Тому так говорить Господь Саваоф, Бог Ізраїлів: ось, Я нагодую їх, цей народ, полином, і напою їх водою з жовчю;","і розсію їх між народами, яких не знали ні вони, ні батьки їхні, і пошлю услід їм меч, доки не знищу їх.","Так говорить Господь Саваоф: подумайте, і покличте плакальниць, щоб вони прийшли; пошліть за майстринями у цій справі, щоб вони прийшли.","Нехай вони поспішать і здіймуть плач за нас, щоб з очей наших лилися сльози, і з вій наших текла вода.","Бо голос плачу чутно з Сиону: «як ми пограбовані! ми жорстоко посоромлені, бо залишаємо землю, тому що зруйнували житла наші».","Отже, слухайте, жінки, слово Господа, і нехай прислухається вухо ваше до слів уст Його; і вчіть дочок ваших плачу, і одна одну — жалібних пісень.","Бо смерть входить у наші вікна, вдирається у палаци наші, щоб знищити дітей на вулицях, юнаків на площах.","Скажи: так говорить Господь: і будуть повалені трупи людей, як гній на полі і як снопи позаду женця, і не буде кому зібрати їх.","Так говорить Господь: нехай не хвалиться мудрий мудрістю своєю, нехай не хвалиться сильний силою своєю, нехай не хвалиться багатий багатством своїм.","Але хто хвалиться, хвалися тим, що розумієш і знаєш Мене, що Я — Господь, Який творить милість, суд і правду на землі; бо тільки це благоугодно Мені, — говорить Господь.","Ось, приходять дні, — говорить Господь, — коли Я відвідаю усіх обрізаних і необрізаних:","Єгипет і Юдею, й Едома і синів Аммонових, і Моава і всіх, що стрижуть волосся на скронях, які живуть у пустелі; тому що усі ці народи необрізані, а увесь дім Ізраїлів з необрізаним серцем."],"x":{"1":"31.22.4|32.14.17","2":"32.7.9","3":"25.63.4|36.22.29|51.12.14","4":"43.7.5|50.10.36","5":"25.63.4","6":"38.4.1","7":"31.1.25|31.48.10","8":"25.27.3|25.54.22|26.30.14","9":"32.5.9","11":"25.78.1|43.3.12|36.12.20","12":"4.32.28|25.106.43|38.14.10","13":"4.29.25","14":"31.65.2|35.1.22","15":"32.8.14|32.23.15","16":"2.26.33","17":"40.5.16","18":"32.13.17","22":"32.7.33","23":"63.1.31","24":"53.17.3|32.22.16","26":"54.7.51|62.2.28"}},{"v":["Слухайте слово, яке Господь говорить вам, доме Ізраїлів.","Так говорить Господь: не вчіться шляхів язичників і не страшіться знамень небесних, яких язичники страшаться.","Бо устави народів — порожнеча: зрубують дерево у лісі, обробляють його руками теслі за допомогою сокири,","покривають сріблом і золотом, прикріплюють цвяхами і молотом, щоб не хиталося.","Вони — як обточений стовп, і не говорять; їх носять, тому що ходити не можуть. Не бійтеся їх, тому що вони не можуть заподіяти зла, але і добра робити не в силах.","Немає подібного до Тебе, Господи! Ти великий, і ім’я Твоє велике могутністю.","Хто не убоїться Тебе, Царю народів? бо Тобі єдиному належить це; тому що між усіма мудрецями народів і в усіх царствах їх немає подібного до Тебе.","Усі до одного вони безглузді і дурні; пусте вчення — це дерево.","Розбите на листи срібло привезене з Фарсиса, золото — з Уфаза, справа художника і рук плавильника; одяг на них — гіацинт і пурпур: усе це — справа людей майстерних.","А Господь Бог є істина; Він є Бог живий і Цар вічний. Від гніву Його тремтить земля, і народи не можуть витримати обурення Його.","Так говоріть їм: боги, які не створили неба і землі, зникнуть з землі і з-під небес.","Він створив землю силою Своєю, утвердив вселенну мудрістю Своєю і розумом Своїм розпростер небеса.","За гласом Його шумлять води на небесах, і Він піднімає хмари від країв землі, творить блискавки серед дощу і виводить вітер зі сховищ Своїх.","Безумствує усяка людина у своєму знанні, осоромлює себе всякий плавильник ідолом своїм, тому що виплавлене ним є неправда, і немає у ньому духу.","Це повна порожнеча, справа омани; під час відвідування їх вони зникнуть.","Не така, як їх, доля Якова; бо Бог його є Творець усього, й Ізраїль є жезл насліддя Його; ім’я Його — Господь Саваоф.","Забирай із землі майно твоє, ти, що маєш сидіти в облозі;","бо так говорить Господь: ось, Я викину жителів цієї землі цього разу і зажену їх у тісне місце, щоб схопили їх.","Горе мені у моєму скрушенні; болісна рана моя, але я говорю сам у собі: «справді, це моя скорбота, і я буду нести її;","намет мій спустошений, і всі мотузки мої порвані; діти мої пішли від мене, і немає їх: нема кому вже розкинути шатро моє і розвісити килими мої,","бо пастирі зробилися безглуздими і не шукали Господа, а тому вони і чинили нерозумно, і все стадо їх розсіяне».","Несеться чутка: ось вона йде, і великий шум від країни північної, щоб міста Юдеї зробити пустелею, житлом шакалів.","Знаю, Господи, що не у волі людини путь її, що не у владі того, хто йде, давати напрямок стопам своїм.","Карай мене, Господи, але за правдою, не у гніві Твоєму, щоб не принизити мене.","Вилий лють Твою на народи, які не знають Тебе, і на племена, які не прикликають імені Твого; бо вони з’їли Якова, пожерли його і знищили його, і житло його спустошили."],"x":{"2":"4.18.9","3":"31.44.13","4":"29.13.10|31.40.19","5":"25.113.12-13|31.46.7","6":"25.85.8","7":"76.15.4","8":"25.113.16|31.41.29|38.8.6","10":"25.9.37","11":"65.4.8|35.3.18","12":"25.135.6|32.51.15","13":"25.134.7|25.148.4","14":"32.51.17|62.1.22","16":"32.51.19","21":"32.50.6|38.9.7","22":"32.1.14","23":"25.36.23|26.20.24","24":"25.6.2|25.37.2","25":"25.78.6|30.36.2-3"}},{"v":["Слово, яке було до Єремії від Господа:","слухайте слова́ завіту цього і скажіть мужам Іуди і жителям Єрусалима;","і скажи їм: так говорить Господь, Бог Ізраїлів: проклята людина, яка не послухає слів завіту цього,","який Я заповів батькам вашим, коли вивів їх із землі Єгипетської, із залізної печі, сказавши: «слухайтеся гласу Мого і робіть усе, що Я заповідаю вам, — і будете Моїм народом, і Я буду вашим Богом,","щоб виконати клятву, якою Я клявся батькам вашим, — дати їм землю, яка тече молоком і медом, як це нині». І відповів я, сказавши: амінь, Господи!","І сказав мені Господь: проголоси усі ці слова у містах Іуди і на вулицях Єрусалима і скажи: слухайте слова́ завіту цього і виконуйте їх.","Бо батьків ваших Я умовляв постійно з того дня, як вивів їх із землі Єгипетської, до цього дня; напоумлював їх з раннього ранку, говорячи: «слухайтеся гласу Мого».","Але вони не слухалися і не прихиляли вуха свого, а ходили кожен за впертістю злого серця свого: тому Я навів на них усе сказане у завіті цьому, який Я заповів їм виконувати, а вони не виконували.","І сказав мені Господь: є змова між мужами Іуди і жителями Єрусалима:","вони знову повернулися до беззаконь праотців своїх, які зреклися слухатися слів Моїх і пішли слідом чужих богів, слугуючи їм. Дім Ізраїля і дім Іуди порушили завіт Мій, який Я уклав з батьками їх.","Тому так говорить Господь: ось, Я наведу на них біду, якої вони не можуть позбутися, і коли заволають до Мене, не почую їх.","Тоді міста́ Іуди і жителі Єрусалима підуть і волатимуть до богів, яким вони кадять; але вони ніскільки не допоможуть їм під час біди їхньої.","Бо скільки у тебе міст, стільки і богів у тебе, Іудо, і скільки вулиць в Єрусалимі, стільки ви наставили жертовників ганебному, жертовників для кадіння Ваалу.","Ти ж не проси за цей народ і не піднось за них молитви і прохання; бо Я не почую, коли вони будуть волати до Мене у біді своїй.","Що улюбленому Моєму в домі Моєму, коли в ньому звершується безліч непотребств? і священні м’яса* не допоможуть тобі, коли, роблячи зло, ти радієш.","Зеленою маслиною, що красується приємними плодами, найменував тебе Господь. А нині, при шумі сильного сум’яття, Він запалив вогонь навколо неї, і скрушилися гілки її.","Господь Саваоф, Який насадив тебе, вирік на тебе зле за зло дому Ізраїлевого і дому Іудиного, яке вони заподіяли собі тим, що викликали у Мені гнів кадінням Ваалу.","Господь відкрив мені, і я знаю; Ти показав мені діяння їх.","А я, як лагідний агнець, якого ведуть на заколення, і не знав, що вони складають задуми проти мене, говорячи: «покладемо отруйне дерево в їжу його й відірвемо його від землі живих, щоб і ім’я його більше не згадувалося».","Але, Господи Саваофе, Судде праведний, Який випробовує серця й утроби! дай побачити мені помсту Твою над ними, бо Тобі довірив я діло моє.","Тому так говорить Господь про мужів Анафофа, які шукають душі твоєї і говорять: «не пророкуй в ім’я Господа, щоб не померти тобі від рук наших»;","тому так говорить Господь Саваоф: ось, Я відвідаю їх: юнаки їхні помруть від меча; сини їхні і дочки їхні помруть від голоду.","І залишку не буде від них; тому що Я наведу біду на мужів Анафофа у рік відвідування їх."],"x":{"3":"4.27.26|65.3.10","4":"4.4.20|32.7.23","5":"4.7.12","7":"32.7.13","8":"32.7.24","10":"32.7.26","11":"26.1.28|31.1.15|32.14.12|36.8.18|43.3.4","12":"4.32.37-38","13":"32.2.28|38.8.11|38.10.1","14":"32.7.16|32.14.11","15":"31.1.16","16":"31.42.25|32.50.32|62.11.17","17":"32.32.29","19":"31.53.7|32.18.23","20":"8.16.7|12.28.9|25.7.10|25.25.2|32.17.10|32.20.12|76.2.23","22":"32.18.21"},"n":{"15":["Жертви."]}},{"v":["Праведний будеш Ти, Господи, якщо я стану судитися з Тобою; і однак же буду говорити з Тобою про правосуддя: чому шлях нечестивих благоуспішний, і всі віроломні благоденствують?","Ти насадив їх, і вони вкорінилися, виросли і приносять плід. У вустах їх Ти близький, але далекий від серця їх.","А мене, Господи, Ти знаєш, бачиш мене і випробовуєш серце моє, яке воно до Тебе. Відокрем їх, як овець на заколення, і приготуй їх на день забиття.","Чи довго буде ремствувати земля, і трава на усіх полях — сохнути? худоба і птахи гинуть за нечестя жителів її, бо вони говорять: «Він не побачить, що з нами буде».","Якщо ти з пішими біг, і вони втомили тебе, як же тобі змагатися з кіньми? і якщо у країні мирній ти був безпечний, то що будеш робити у повінь Йордану?","Бо і брати твої і дім батька твого, і вони віроломно вчиняють з тобою, і вони кричать услід тобі гучним голосом. Не вір їм, коли вони говорять тобі і добре.","Я залишив дім Мій; покинув наділ Мій; найлюб’язніше для душі Моєї віддав у руки ворогів його.","Наділ Мій зробився для Мене як лев у лісі; підняв на Мене голос свій: за те Я зненавидів його.","Наділ Мій став у Мене, як різнобарвний птах, на якого з усіх боків напали інші хижі птахи. Йдіть, збирайтеся, усі польові звірі: йдіть пожирати його.","Багато пастухів зіпсували Мій виноградник, потоптали ногами ділянку Мою; улюблену ділянку Мою зробили порожнім степом;","зробили його пустелею, і у запустінні він плаче переді Мною; вся земля спустошена, тому що жодна людина не бере цього до серця.","На всі гори в пустелі прийшли спустошувачі; бо меч Господа пожирає усе від одного краю землі до іншого: немає миру ні для якої плоті.","Вони сіяли пшеницю, а пожали терни; змучилися, і не одержали ніякої користи; посоромтеся ж таких прибутків ваших з причини полум’яного гніву Господа.","Так говорить Господь про усіх злих Моїх сусідів, які нападають на наділ, який Я дав у спадщину народу Моєму, Ізраїлю: ось, Я вивергну їх із землі їх, і дім Іудин вивергну із середовища їх.","Але після того, як Я вивергну їх, знову поверну і помилую їх, і приведу кожного у наділ його і кожного у землю його.","І якщо вони навчаться шляхів народу Мого, щоб клястися ім’ям Моїм: «живий Господь!», як вони навчили народ Мій клястися Ваалом, то оселяться серед народу Мого.","Якщо ж не послухаються, то Я викоріню і зовсім знищу такий народ, — говорить Господь."],"x":{"1":"24.21.7|25.72.3|45.1.13","3":"25.16.3","4":"32.4.25|32.14.6|32.23.10","6":"32.9.4|51.14.68","7":"50.23.38","8":"25.78.1","9":"33.3.52|76.9.17","10":"32.6.3","13":"2.26.16|43.6.15|47.1.6","14":"32.32.37","16":"4.6.13|4.10.20|32.4.2","17":"31.60.12"}},{"v":["Так сказав мені Господь: піди, купи собі лляний пояс і поклади його на стегна твої, але у воду не клади його.","І я купив пояс, за словом Господа, і поклав його на стегна мої.","І було до мене слово Господнє вдруге, і сказано:","візьми пояс, який ти купив, що на стегнах твоїх, і встань, піди до Євфрату і сховай його там у розщелині скелі.","Я пішов і сховав його біля Євфрату, як повелів мені Господь.","Коли ж минуло багато днів, сказав мені Господь: встань, піди до Євфрату і візьми звідти пояс, який Я звелів тобі сховати там.","І я прийшов до Євфрату, викопав і узяв пояс з того місця, де сховав його, і ось, пояс був зіпсований, ні до чого став не придатний.","І було до мене слово Господнє:","так говорить Господь: так скрушу Я гордість Іуди і велику гордість Єрусалима.","Цей негідний народ, який не хоче слухати слів Моїх, живе за впертістю серця свого і ходить слідом інших богів, щоб служити їм і поклонятися їм, буде як цей пояс, який ні до чого не придатний.","Бо, як пояс близько лежить до стегон людини, так Я наблизив до Себе весь дім Ізраїлів і весь дім Іудин, — говорить Господь, — щоб вони були Моїм народом і Моєю славою, хвалою і прикрасою; але вони не послухалися.","Тому скажи їм слово це: так говорить Господь, Бог Ізраїлів: усякий для вина міх наповнюється вином. Вони скажуть тобі: «хіба ми не знаємо, що усякий для вина міх наповнюється вином?»","А ти скажи їм: так говорить Господь: ось, Я наповню вином до сп’яніння усіх жителів цієї землі і царів, які сидять на престолі Давида, і священиків, і пророків і всіх жителів Єрусалима,","і скрушу їх одне об одного, і батьків і синів разом, — говорить Господь; не пощаджу і не помилую, і не пожалкую знищити їх.","Слухайте і вслуховуйтеся: не будьте горді, бо Господь говорить.","Воздайте славу Господу Богу вашому, доки Він ще не навів темряви, і доки ще ноги ваші не спотикаються на горах мороку; тоді ви будете очікувати світла, а Він оберне його на тінь смерти і зробить темрявою.","Якщо ж ви не послухаєте цього, то душа моя у потаємних місцях буде оплакувати гордість вашу, буде плакати гірко, й очі мої будуть виливатися у сльозах; тому що стадо Господнє відведене буде в полон.","Скажи цареві і цариці: смиріться, сядьте нижче, бо упав з голови вашої вінець слави вашої.","Південні міста замкнені, і нема кому відчиняти їх; Іуда весь відводиться у полон, відводиться у полон геть увесь.","Підніміть очі ваші і подивіться на тих, що йдуть з півночі: де стадо, яке дано було тобі, прекрасне стадо твоє?","Що скажеш, дочко Сиону, коли Він відвідає тебе? Ти сама привчила їх начальствувати над тобою; чи не схоплять тебе болі, як жінку, яка народжує?","І якщо скажеш у серці твоєму: «за що осягло мене це?» — За безліч беззаконь твоїх відкритий поділ у тебе, оголені п’яти твої.","Чи може ефіоплянин перемінити шкіру свою і барс — плями свої? так і ви, чи можете робити добре, звикнувши робити зле?","Тому розвію їх, як порох, що розноситься вітром пустельним.","Ось жереб твій, відміряна тобі від Мене частина, — говорить Господь, — тому що ти забула Мене і сподівалася на неправду.","За те буде піднятий поділ твій на лице твоє, щоб відкрився сором твій.","Бачив Я перелюбство твоє і шалену похіть твою, твої непотребства і твої мерзоти на пагорбах у полі. Горе тобі, Єрусалиме! ти і після цього не очистишся. Доки ж?"],"x":{"1":"54.21.11","9":"11.24.2","10":"32.11.8|32.22.21|35.1.22","11":"4.26.19","14":"32.16.5","15":"55.1.21","16":"5.7.19|53.9.24|31.59.9","17":"33.1.2:16","18":"31.47.1|33.5.16","20":"32.1.14","21":"32.6.24","22":"32.5.19|32.30.15","27":"32.5.8"}},{"v":["Слово Господа, яке було до Єремії з нагоди бездощів’я.","Плаче Іуда, ворота його розпалися, почорніли на землі, і волання здіймається в Єрусалимі.","Вельможі посилають слуг своїх по воду; вони приходять до колодязів і не знаходять води; повертаються з порожніми посудинами; присоромлені і знічені, вони покривають свої голови.","Оскільки ґрунт розтріскався від того, що не було дощу на землю, то і хлібороби знічені й покривають свої голови.","Навіть і лань народжує на полі і залишає дітей, тому що немає трави.","І дикі осли стоять на підвищених місцях і ковтають, подібно до шакалів, повітря; очі їхні потьмяніли, тому що немає трави.","Хоча беззаконня наші свідчать проти нас, але Ти, Господи, твори з нами заради імені Твого; відступництво наше велике, згрішили ми перед Тобою.","Надія Ізраїля, Спаситель його під час скорботи! Для чого Ти — як чужий у цій землі, як перехожий, який зайшов переночувати?","Чому Ти — як чоловік здивований, як сильний, який не має сили спасти? І однак же Ти, Господи, посеред нас, і Твоє ім’я наречене над нами; не залишай нас.","Так говорить Господь народу цьому: за те, що вони люблять блукати, не стримують ніг своїх, за те Господь не благоволить до них, пригадує нині беззаконня їхні і карає гріхи їхні.","І сказав мені Господь: ти не молися за народ цей на благо йому.","Якщо вони будуть поститися, Я не почую волання їхнього; і якщо піднесуть всепалення і дари, не прийму їх; але мечем і голодом, і моровицею знищу їх.","Тоді сказав я: Господи Боже! ось, пророки говорять їм: «не побачите меча, і голоду не буде у вас, але постійний мир дам вам на цьому місці».","І сказав мені Господь: пророки пророкують неправду ім’ям Моїм; Я не посилав їх і не давав їм повеління, і не говорив їм; вони звіщають вам видіння неправдиві і ворожі, і пусте і мрії серця свого.","Тому так говорить Господь про пророків: вони пророкують ім’ям Моїм, а Я не посилав їх; вони говорять: «меча і голоду не буде на цій землі»: мечем і голодом будуть знищені ці пророки,","і народ, якому вони пророкують, розкиданий буде по вулицях Єрусалима від голоду і меча, і не буде кому ховати їх, — вони і дружини їхні, і сини їхні, і дочки їхні; і Я виллю на них зло їхнє.","І скажи їм слово це: нехай ллються з очей моїх сльози ніч і день, і нехай не перестають; бо великою поразкою вражена діва, дочка народу мого, тяжким ударом.","Виходжу я на поле, — і ось, убиті мечем; входжу в місто, — і ось ті, що вмирають від голоду; навіть і пророк і священик блукають по землі несвідомо.","Хіба Ти зовсім відкинув Іуду? Хіба душі Твоїй огиднув Сион? Для чого уразив нас так, що немає нам зцілення? Чекаємо миру, і нічого доброго немає; чекаємо часу зцілення, і ось жахи.","Усвідомлюємо, Господи, нечестя наше, беззаконня батьків наших; бо згрішили ми перед Тобою.","Не відкинь нас заради імені Твого; не принижуй престолу слави Твоєї: згадай, не руйнуй завіту Твого з нами.","Чи є між суєтними богами язичницькими такі, що посилають дощ? або чи може небо саме собою подавати зливу? чи не Ти це, Господи, Боже наш? На Тебе надіємося ми; бо Ти твориш усе це."],"x":{"2":"33.3.6","3":"4.28.24|9.13.30","4":"39.1.11","6":"32.12.4","7":"32.3.25","8":"32.17.13|32.50.7","9":"25.43.24|1.25.10:22","11":"32.11.14","12":"26.1.28|31.1.15|31.58.3","13":"32.5.12|32.6.13|32.8.10","14":"32.23.21:25|32.27.15|36.13.9","15":"32.5.13","16":"32.16.4","17":"32.9.1|33.1.16|33.2.18","19":"25.73.1|32.8.15","20":"14.9.15","21":"32.3.17|32.17.12","22":"48.10.1"}},{"v":["І сказав мені Господь: хоч би стали перед лице Моє Мойсей і Самуїл, душа Моя не прихилиться до народу цього; віджени їх від лиця Мого, нехай вони відійдуть.","Якщо ж скажуть тобі: «куди нам іти?», то скажи їм: так говорить Господь: хто приречений на смерть, іди на смерть; і хто під меч, — під меч; і хто на голод, — на голод; і хто у полон, — у полон.","І пошлю на них чотири роди страт, — говорить Господь: меч, щоб убивати, і псів, щоб терзати, і птахів небесних і звірів польових, щоб пожирати і знищувати;","і віддам їх на озлоблення усім царствам землі за Манассію, сина Єзекії, царя Юдейського, за те, що він зробив у Єрусалимі.","Бо хто пожаліє тебе, Єрусалиме? і хто виявить співчуття до тебе? і хто зайде до тебе запитати про твій добробут?","Ти залишив Мене, — говорить Господь, — відступив назад; тому Я простягну на тебе руку Мою і погублю тебе: Я втомився милувати.","Я розвіваю їх віялом за ворота землі; позбавляю їх дітей, гублю народ Мій; але вони не повертаються зі шляхів своїх.","Удів їх у Мене більше, ніж піску в морі; наведу на них, на матір юнаків, спустошувача опівдні; нападе на них раптово страх і жах.","Лежить у знемозі та, що народила сімох, спускає дихання своє; ще вдень закотилося сонце її, вона посоромлена й осоромлена. І залишок їх віддам мечу перед очима ворогів їхніх, — говорить Господь.","«Горе мені, мати моя, що ти народила мене людиною, яка сперечається і свариться з усією землею! нікому не давав я на ріст, і мені ніхто не давав на ріст, а усі проклинають мене».","Господь сказав: кінець твій буде добрий, і Я змушу ворога чинити з тобою добре під час біди і під час скорботи.","Чи може залізо скрушити залізо північне і мідь?","Майно твоє і скарби твої віддам на розкрадання, без оплати, за усі гріхи твої, у всіх межах твоїх;","і відправлю з ворогами твоїми у землю, якої ти не знаєш; тому що вогонь запалав у гніві Моєму, — буде палати на вас.","О, Господи! Ти знаєш усе; згадай про мене і відвідай мене, і помстися за мене гонителям моїм; не погуби мене з довготерпіння Твого; Ти знаєш, що заради Тебе несу я наругу.","Знайдені слова Твої, і я з’їв їх; і було слово Твоє мені на радість і на веселість серця мого; бо ім’я Твоє наречене на мені, Господи, Боже Саваофе.","Не сидів я на зібранні, яке сміється, і не веселився: під рукою Твоєю, що тяжить на мені, я сидів самотньо, бо Ти сповнив мене обуренням.","За що така уперта хвороба моя, і рана моя така незцілима, що відкидає лікування? Невже Ти будеш для мене ніби оманним джерелом, невірною водою?","На це так сказав Господь: якщо ти навернешся, то Я підніму тебе, і будеш стояти перед лицем Моїм; і якщо здобудеш дорогоцінне із нікчемного, то будеш як Мої вуста. Вони самі будуть навертатися до тебе, а не ти будеш навертатися до них.","І зроблю тебе для цього народу міцною мідною стіною; вони будуть ратувати проти тебе, але не здолають тебе, бо Я з тобою, щоб спасати і визволяти тебе, — говорить Господь.","І спасу тебе від руки злих і визволю тебе від руки гнобителів."],"x":{"1":"1.32.11|8.7.9","2":"32.43.11|48.11.9","3":"32.22.19","4":"4.28.25|32.24.9|32.29.18|11.21.11","9":"40.8.9","10":"32.20.14","13":"32.17.3|32.20.5","14":"4.28.36|4.32.22|32.17.4|62.10.19","15":"32.17.18","16":"25.18.8","17":"25.1.1","18":"32.30.15","19":"55.4.8","20":"32.1.18-19"}},{"v":["І було до мене слово Господнє:","не бери собі дружини, і нехай не буде у тебе ні синів, ні дочок на місці цьому.","Бо так говорить Господь про синів і дочок, які народяться на місці цьому, і про матерів їхніх, які народять їх, і про батьків їхніх, які породять їх на цій землі:","тяжкою смертю помруть вони і не будуть ні оплакані, ні поховані; будуть гноєм на поверхні землі; мечем і голодом будуть знищені, і трупи їхні будуть споживою птахам небесним і звірам земним.","Бо так говорить Господь: не входь у дім тих, що ремствують, і не ходи плакати і тужити з ними; бо Я відняв від цього народу, — говорить Господь, — мир Мій і милість і жаль.","І помруть великі і малі на землі цій; і не будуть поховані, і не будуть оплакувати їх, ні терзати себе, ні стригтися заради них.","І не будуть переломлювати для них хліб у сумі, для утішення за померлим; і не подадуть їм чаші втіхи, щоб пити по батькові їх і матері їх.","Не ходи також і у дім бенкету, щоб сидіти з ними, їсти і пити;","бо так говорить Господь Саваоф, Бог Ізраїлів: ось, Я припиню у місці цьому в очах ваших і у дні ваші голос радости і голос веселощів, голос нареченого і голос нареченої.","Коли ти перекажеш народу цьому всі ці слова, і вони скажуть тобі: «за що вирік на нас Господь усю цю велику біду, й у чому наша неправда, і який наш гріх, яким згрішили ми перед Господом Богом нашим?» —","тоді скажи їм: за те, що батьки ваші залишили Мене, — говорить Господь, — і пішли слідом інших богів, і служили їм, і поклонялися їм, а Мене залишили, і закону Мого не зберігали.","А ви робите ще гірше за батьків ваших і живете кожен за впертістю злого серця свого, щоб не слухати Мене.","За це викину вас із землі цієї у землю, якої не знали ні ви, ні батьки ваші, і там будете служити іншим богам день і ніч; бо Я не виявлю до вас милосердя.","Тому ось, приходять дні, — говорить Господь, — коли не будуть уже говорити: «живий Господь, Який вивів синів Ізраїлевих із землі Єгипетської»;","але: «живий Господь, Який вивів синів Ізраїлевих із землі північної і з усіх земель, в які вигнав їх»: бо поверну їх у землю їхню, яку Я дав батькам їхнім.","Ось, Я пошлю багато рибалок, — говорить Господь, — і будуть ловити їх; а потім пошлю багато мисливців, і вони проженуть їх з усякої гори, і з усякого пагорба, і з ущелин скель.","Бо очі Мої на усіх шляхах їхніх; вони не приховані від лиця Мого, і неправда їхня не прихована від очей Моїх.","І воздам їм насамперед за неправду їхню і за подвійний гріх їхній, тому що осквернили землю Мою, трупами гидких своїх і мерзотами своїми наповнили насліддя Моє.","Господи, сила моя і кріпкість моя і притулок мій у день скорботи! до Тебе прийдуть народи від країв землі і скажуть: «тільки неправду успадкували наші батьки, пустоту і те, у чому немає ніякої користи».","Чи може людина зробити собі богів, які, втім, не є боги?","Тому, ось Я покажу їм нині, покажу їм руку Мою і могутність Мою, і пізнають, що ім’я Моє — Господь."],"x":{"2":"63.7.26","4":"32.7.33|32.8.2|32.25.33","5":"32.13.14","6":"2.19.27-28","7":"4.26.14","8":"36.24.22","9":"31.24.8|32.7.34|36.26.13","10":"32.5.19","11":"31.65.7|32.3.25|36.21.7","12":"32.7.26","13":"4.4.27-28","14":"32.23.7","16":"50.4.19|50.13.47|40.4.2","17":"24.34.21|26.5.21","18":"31.40.2","19":"31.25.4|32.17.17|62.1.25","20":"31.40.19|32.10.3|29.13.11"}},{"v":["Гріх Іуди написаний залізним різцем, алмазним вістрям накреслений на скрижалі серця їх і на рогах жертовників їх.","Як про синів своїх, згадують вони про жертовники свої і діброви свої біля зелених дерев, на високих пагорбах.","Гору Мою у полі, майно твоє і всі скарби твої віддам на розграбування, і всі висоти твої — за гріхи в усіх межах твоїх.","І ти через себе позбавишся спадщини твоєї, яку Я дав тобі, і віддам тебе у рабство ворогам твоїм, у землю, якої ти не знаєш, тому що ви розпалили вогонь гніву Мого; він буде горіти повіки.","Так говорить Господь: проклята людина, яка надіється на людину і плоть робить своєю опорою, і серце якої відходить від Господа.","Вона буде як вереск у пустелі і не побачить, коли прийде добре, й оселиться у місцях спекотних у степу, на землі неплідній, ненаселеній.","Благословенна людина, яка надіється на Господа, і уповання якої — Господь.","Бо вона буде як дерево, посаджене біля вод, яке пускає коріння своє біля потоку; не знає воно, коли приходить спека; лист його зелений, і в час засухи воно не боїться і не перестає приносити плід.","Лукаве серце людське найбільше і вкрай зіпсоване; хто пізнає його?","Я, Господь, проникаю у серце і випробовую нутрощі, щоб воздати кожному за путями його і за плодами діл його.","Куріпка сідає на яйця, яких не несла; таким є той, хто здобуває багатство неправдою: він залишить його у половині днів своїх, і нерозумним залишиться при кінці своєму.","Престіл слави, піднесений від початку, є місце освячення нашого.","Ти, Господи, надія Ізраїлева; усі, що залишають Тебе, осоромляться. «Ті, що відступають від Мене, будуть написані на поросі, тому що залишили Господа, джерело води живої».","Зціли мене, Господи, і зціленим буду; спаси мене, і спасеним буду; бо Ти хвала моя.","Ось, вони говорять мені: «де слово Господнє? нехай воно прийде!»","Я не поспішав бути пастирем у Тебе і не бажав дня бідування, Ти це знаєш; що вийшло з уст моїх, відкрите перед лицем Твоїм.","Не будь страшним для мене, Ти — надія моя у день біди.","Нехай посоромляться гонителі мої, а я не буду посоромлений; нехай вони затремтять, а я буду безтрепетним; наведи на них день бідування і скруши їх подвійним знищенням.","Так сказав мені Господь: піди і стань у воротах синів народу, якими входять царі юдейські і якими вони виходять, і біля усіх воріт єрусалимських,","і говори їм: слухайте слово Господнє, царі юдейські, і вся Юдея, і всі жителі Єрусалима, які входять цими воротами.","Так говорить Господь: бережіть душі свої і не носіть тягарів у день суботній і не вносьте їх воротами єрусалимськими,","і не виносьте тягарів з домів ваших у день суботній, і не займайтеся жодною працею, але святіть день суботній так, як Я заповів батькам вашим,","які, втім, не послухалися і не прихилили вуха свого, але зробилися жорстокосердими, щоб не слухати і не приймати настановлення.","І якщо ви послухаєте Мене у тому, — говорить Господь, — щоб не носити тягарів воротами цього міста у день суботній і щоб святити суботу, не займаючись у цей день жодною працею,","то воротами цього міста будуть входити царі і князі, які сидять на престолі Давида, які їздять на колісницях і на конях, вони і князі їхні, юдеї і жителі Єрусалима, і місто це буде населеним вічно.","І будуть приходити з міст юдейських, і з околиць Єрусалима, і з землі Веніамінової, і з рівнини і з гір і з півдня, і приносити всепалення і жертву, і хлібне приношення, і ливан, і подячні жертви у дім Господній.","А якщо не послухаєте Мене у тому, щоб святити день суботній і не носити тягарів, входячи у ворота Єрусалима в день суботній, то запалю вогонь у воротах його, і він пожере палаци Єрусалима і не погасне."],"x":{"1":"31.65.6","2":"32.11.13","3":"32.15.13","4":"32.15.14","5":"25.117.8|26.29.25|31.31.1","6":"31.1.30|32.48.6","7":"25.2.12|26.16.20|31.30.18","8":"25.1.3","9":"25.63.7","10":"8.16.7|12.28.9|25.7.10|26.17.3|32.11.20|32.20.12|76.2.23","12":"32.14.21","13":"32.2.13|32.14.8|53.4.14|53.8.6","15":"31.5.19","16":"24.32.21|63.4.3","17":"32.16.19","18":"32.20.11","19":"31.29.21","21":"17.13.19|53.5.9","22":"1.20.8|36.20.12","23":"32.7.24","24":"31.56.2|31.58.13","25":"32.22.4","26":"32.32.44","27":"31.1.31|40.5.6|32.21.14"}},{"v":["Слово, яке було до Єремії від Господа:","встань і зійди у дім гончара, і там Я сповіщу тобі слова Мої.","І зійшов я у дім гончара, і ось, він виконував свою работу на кружалі.","І посудина, яку гончар виробляв із глини, розвалилася у руці його; і він знову зробив з неї іншу посудину, яку гончар здумав зробити.","І було слово Господнє до мене:","чи не можу Я вчинити з вами, доме Ізраїлів, подібно до гончара цього? — говорить Господь. Ось, що глина в руці гончара, те ви у Моїй руці; доме Ізраїлів.","Іноді Я скажу про який-небудь народ і царство, що викоріню, знищу і погублю його;","але якщо народ цей, на який Я це вирік, навернеться від своїх злих діл, Я відкладаю те зло, яке помислив зробити йому.","А іноді скажу про який-небудь народ і царство, що впорядкую і утверджу його;","але якщо він буде робити лихе перед очима Моїми і не буде слухатися голосу Мого, Я відміню те добро, яким хотів облагодіяти його.","Отже, скажи мужам Іуди і жителям Єрусалима: так говорить Господь: ось, Я готую вам зло і замишляю проти вас; отже, наверніться кожен від злого шляху свого і виправте путі ваші і вчинки ваші.","Але вони говорять: «не надійся; ми будемо жити за своїми помислами і будемо чинити кожен за впертістю злого свого серця».","Тому так говорить Господь: запитайте між народами, чи чув хто подібне до цього? украй мерзотні діла вчинила діва Ізраїлева.","Чи залишає сніг ливанський скелю гори? і чи висихають холодні води, що течуть з інших місць?","А народ Мій залишив Мене; вони кадять суєтним, спіткнулися на шляхах своїх, залишили шляхи давні, щоб ходити по стежках шляху непрокладеного,","щоб зробити землю свою жахом, постійним посміховиськом, так що кожен, хто проходить нею, здивується і похитає головою своєю.","Як східним вітром розвію їх перед лицем ворога; спиною, а не лицем повернуся до них у день біди їх.","А вони сказали: «прийдіть, учинимо задум проти Єремії; тому що не зник же закон у священика і рада у мудрого, і слово у пророка; прийдіть, уразимо його язиком і не будемо слухати слів його».","Вислухай мене, Господи, і почуй голос моїх супротивників.","Чи слід відплачувати злом за добро? а вони риють яму душі моїй. Згадай, що я стою перед лицем Твоїм, щоб говорити за них добре, щоб відвернути від них гнів Твій.","Отже, віддай синів їх голоду і піддай їх мечу; нехай будуть дружини їхні бездітними і вдовами, і чоловіки їхні нехай будуть уражені смертю, і юнаки їхні умертвлені мечем на війні.","Нехай буде чутно волання з домів їхніх, коли приведеш на них полки раптово; бо вони риють яму, щоб упіймати мене, і таємно розставили сіті для ніг моїх.","Але Ти, Господи, знаєш усі задуми їхні проти мене, щоб умертвити мене; не прости неправди їх і гріха їх не загладь перед лицем Твоїм; нехай будуть вони поваленими перед Тобою; вчини з ними під час гніву Твого."],"x":{"6":"29.15.7|31.45.9|62.9.20","7":"32.1.10","8":"36.18.21","11":"32.7.3|32.25.5|32.35.15|53.3.8","12":"32.2.25","13":"32.2.10","15":"32.6.16","16":"32.19.8|32.49.13|32.50.13","17":"26.1.26","18":"49.2.7","19":"32.20.12","20":"0.44.4|25.7.16|50.22.15","21":"25.108.9-10","22":"25.34.7|52.20.20","23":"32.11.19|25.108.14"}},{"v":["Так сказав Господь: піди і купи глиняний глечик у гончара; і візьми з собою найстарших з народу і зі старійшин священичих,","і вийди у долину синів Енномових, що біля воріт Харшиф, і виголоси там слова, які скажу тобі,","і скажи: слухайте слово Господнє, царі юдейські і жителі Єрусалима! так говорить Господь Саваоф, Бог Ізраїлів: ось, Я наведу біду на місце це, — про яке хто почує, у того задзвенить у вухах,","за те, що вони залишили Мене і чужим зробили місце це і кадять на ньому іншим богам, яких не знали ні вони, ні батьки їхні, ні царі юдейські; наповнили місце це кров’ю невинних","і влаштували висоти Ваалу, щоб спалювати синів своїх вогнем у всепалення Ваалу, чого Я не повелівав і не говорив, і що на думку не спадало Мені;","за те ось, приходять дні, — говорить Господь, — коли місце це не буде більше називатися Тофетом або долиною синів Енномових, але долиною вбивства.","І знищу раду Іуди та Єрусалима на місці цьому й уб’ю їх мечем перед лицем ворогів їхніх і рукою тих, що шукають душі їхні, і віддам трупи їхні в їжу птахам небесним і звірам земним.","І зроблю місто це жахом і посміянням; кожен, хто пройде через нього, здивується і посвистить, дивлячись на усі виразки його.","І нагодую їх плоттю синів їхніх і плоттю дочок їхніх; і буде кожен їсти плоть свого ближнього, знаходячись в облозі і тісноті, коли стиснуть їх вороги їхні й ті, що шукають душі їхні.","І розбий глечик перед очима тих мужів, які прийдуть з тобою,","і скажи їм: так говорить Господь Саваоф: так знищу Я народ цей і місто це, як розбита посудина гончара, яка уже не може бути відновлена, і будуть ховати їх у Тофеті, через нестачу місця для поховання.","Так зроблю з місцем цим, — говорить Господь, — і з жителями його; і місто це зроблю подібним до Тофета.","І доми Єрусалима і доми царів юдейських будуть, як місце Тофет, нечистими, тому що на покрівлях усіх домів кадять усьому воїнству небесному і роблять узливання богам чужим.","І прийшов Єремія з Тофета, куди Господь посилав його пророкувати, і став у дворі дому Господнього і сказав усьому народові:","так говорить Господь Саваоф, Бог Ізраїлів: ось, Я наведу на місто це і на усі міста його усі ті біди, які прорік на нього, тому що вони жорстокосерді і не слухають слів Моїх."],"x":{"2":"32.7.31","3":"8.3.11","4":"32.2.13|32.15.6","5":"32.7.18|32.16.18|11.16.3","6":"32.7.32","7":"32.7.33","8":"32.18.16|32.50.13","9":"4.28.53|33.4.10","11":"32.7.32","13":"11.23.12","15":"1.32.9|17.9.17|32.7.26"}},{"v":["Коли Пасхор, син Еммерів, священик, він же і наглядач у домі Господньому, почув, що Єремія як пророк промовив слова ці,","то вдарив Пасхор Єремію пророка і посадив його у колоду, яка була біля верхніх воріт Веніамінових при домі Господньому.","Але на другий день Пасхор випустив Єремію з колоди, і Єремія сказав йому: не «Пасхор»* нарік Господь ім’я тобі, але «Магор Миссавив»*.","Тому що так говорить Господь: ось, Я зроблю тебе жахом для тебе самого і для усіх друзів твоїх, і впадуть вони від меча ворогів своїх, і твої очі побачать це. І всього Іуду віддам до рук царя Вавилонського, і відведе їх у Вавилон і уразить їх мечем.","І віддам усе багатство цього міста і усе надбання його, й усі коштовності його; і всі скарби царів юдейських віддам до рук ворогів їхніх, і пограбують їх і візьмуть, і відправлять їх у Вавилон.","І ти, Пасхоре, й усі, хто живе у домі твоєму, підете в полон; і прийдеш у Вавилон, і там помреш, і там будеш похований, ти і усі друзі твої, яким ти пророкував неправдиво.","Ти вів мене, Господи, — і я захоплений; Ти сильніший за мене — і переміг, і я щодня у посміянні, усякий знущається з мене.","Бо лиш тільки почну говорити я, — кричу про насильство, волаю про руйнування, тому що слово Господнє обернулося на ганьбу для мене і на повсякденне посміяння.","І подумав я: «не буду я нагадувати про Нього і не буду більше говорити в ім’я Його»; але було у серці моєму, що ніби горить вогонь, який наповнює кістки мої, і я стомився, стримуючи його, і не міг.","Бо я чув слова багатьох: погрози навколо; «заявіть, говорили вони, і ми зробимо донос». Усі, що жили зі мною у мирі, стежать за мною, чи не спіткнуся я: «можливо, говорять, він попадеться, і ми здолаємо його й помстимося йому».","Але зі мною Господь, як сильний ратоборець; тому гонителі мої спіткнуться і не здолають; сильно осоромляться, тому що чинили нерозумно; посоромлення буде вічне, ніколи не забудеться.","Господи сил! Ти випробовуєш праведного і бачиш нутрощі і серце. Нехай побачу я помсту Твою над ними, бо Тобі довірив я діло моє.","Співайте Господу, хваліть Господа, бо Він спасає душу бідного від руки лиходіїв. —","Проклятий день, в який я народився! день, в який народила мене мати моя, нехай не буде благословенний!","Проклята людина, яка принесла звістку батькові моєму і сказала: «у тебе народився син», і тим дуже порадувала його.","І нехай буде з тією людиною, що з містами, які зруйнував Господь і не пожалів; нехай чує вона ранком волання й опівдні ридання","за те, що вона не убила мене у самій утробі — так, щоб мати моя була мені гробом, і утроба її залишалася вічно вагітною.","Для чого вийшов я з утроби, щоб бачити труди і скорботи, і щоб дні мої зникали у неславі?"],"x":{"1":"14.2.37|12.24.14","2":"32.37.15|75.11.36","4":"32.21.7","5":"32.15.13","7":"32.1.5:8|32.6.10","9":"24.32.18|52.24.32|63.9.16-17","11":"32.17.18|32.23.40","12":"32.11.20","14":"24.3.3","16":"0.19.24-25","18":"24.3.11"},"n":{"3":["Мир навколо.","Жах навколо."]}},{"v":["Слово, яке було до Єремії від Господа, коли цар Седекія послав до нього Пасхора, сина Молхіїного, і Софонію, сина Маасеї священика, сказати йому:","«запитай про нас Господа, бо Навуходоносор, цар Вавилонський, воює проти нас; можливо, Господь сотворить з нами що-небудь таке, як усі чудеса Його, щоб той відступив від нас».","І сказав їм Єремія: так скажіть Седекії:","так говорить Господь, Бог Ізраїлів: ось, Я поверну назад військове знаряддя, яке у руках ваших, яким ви воюєте з царем Вавилонським і з халдеями, які беруть вас в облогу поза стіною, і зберу їх посеред міста цього;","і Сам буду воювати проти вас рукою простягнутою і правицею кріпкою, у гніві й у люті й у великому обуренні;","і вражу тих, що живуть у цьому місті, — і людей і худобу; від великої моровиці помруть вони.","А після того, — говорить Господь, — Седекію, царя Юдейського, слуг його і народ, і тих, що залишилися у місті цьому після моровиці, меча і голоду, віддам до рук Навуходоносора, царя Вавилонського, і до рук ворогів їхніх і до рук тих, що шукають душі їхні; і він уразить їх вістрям меча і не пощадить їх, і не пожаліє і не помилує.","І народу цьому скажи: так говорить Господь: ось, Я пропоную вам путь життя і путь смерти:","хто залишиться у цьому місті, той помре від меча і голоду і моровиці; а хто вийде і віддасться халдеям, які обложили вас, той буде живий, і душа його буде йому замість здобичі;","бо Я повернув лице Моє проти міста цього, — говорить Господь, — на зло, а не на добро; воно буде віддане у руки царя Вавилонського, і той спалить його вогнем.","І дому царя Юдейського скажи: слухайте слово Господнє:","доме Давидів! так говорить Господь: з раннього ранку чиніть суд і рятуйте того, кого скривдять, від руки кривдника, щоб лють Моя не вийшла, як вогонь, і не розгорілася через злі діла ваші до того, що ніхто не погасить.","Ось, Я — проти тебе, жителько долини, скеле рівнини, — говорить Господь, — проти вас, які говорите: «хто виступить проти нас і хто ввійде у житла наші?»","Але Я відвідаю вас за плодами діл ваших, — говорить Господь, — і запалю вогонь у лісі вашому, і пожере усе навколо нього."],"x":{"1":"12.24.9","5":"1.6.6|4.5.15|32.32.21","7":"32.20.4|32.34.2|1.4.19","8":"30.15.17","9":"32.38.2|32.45.5","10":"2.17.10|32.32.29|32.34.2","12":"32.4.4|32.22.3","13":"32.49.4|36.11.15","14":"32.17.27|32.22.7"}},{"v":["Так сказав Господь: зійди у дім царя Юдейського і промов слово це","і скажи: вислухай слово Господнє, царю Юдейський, що сидиш на престолі Давидовому, ти, і слуги твої, і народ твій, які входите цими воротами.","Так говорить Господь: чиніть суд і правду і рятуйте скривдженого від руки гнобителя, не кривдьте і не утискуйте прибульця, сироту і вдову, і невинної крови не проливайте на місці цьому.","Бо якщо ви будете виконувати слово це, то будуть входити воротами дому цього царі, які сидять замість Давида на престолі його, які їздять на колісниці і на конях, самі й слуги їхні і народ їхній.","А якщо не послухаєте слів цих, то Мною клянуся, — говорить Господь, — що дім цей зробиться порожнім.","Бо так говорить Господь дому царя Юдейського: Галаад ти у Мене, вершина Ливану; але Я зроблю тебе пустелею і міста безлюдними","і приготую проти тебе винищувачів, кожного зі своїм знаряддям, і зрубають кращі кедри твої і кинуть у вогонь.","І багато народів будуть проходити через місто це і говорити одне одному: «за що Господь так учинив з цим великим містом?»","І скажуть у відповідь: «за те, що вони залишили завіт Господа Бога свого і поклонялися іншим богам і служили їм».","Не плачте за померлим і не жалійте за ним; але гірко плачте за тим, хто відходить у полон, бо він уже не повернеться і не побачить рідної країни своєї.","Бо так говорить Господь про Саллума, сина Іосії, царя Юдейського, який царював після батька свого, Іосії, і який вийшов з цього місця: він уже не повернеться сюди,","але помре у тому місці, куди відвели його полоненим, і більше не побачить землі цієї.","Горе тому, хто будує дім свій неправдою і світлиці свої беззаконням, хто примушує ближнього свого працювати задарма і не віддає йому платні його,","хто говорить: «побудую собі дім великий і світлиці просторі», — і прорубує собі вікна, й обшиває кедром, і фарбує червоною фарбою.","Чи думаєш ти бути царем, тому що обклав себе кедром? батько твій їв і пив, але чинив суд і правду, і тому йому було добре.","Він розбирав справу бідного й убогого, і тому йому добре було. Чи не це означає знати Мене? — говорить Господь.","Але твої очі і твоє серце звернені тільки до твоєї користи і до пролиття невинної крови, до того, щоб робити утиск і насильство.","Тому так говорить Господь про Іоакима, сина Іосії, царя Юдейського: не будуть оплакувати його: «горе, брат мій!» і: «горе, сестра!» Не будуть оплакувати його: «горе, государ!» і: «горе, його велич!»","Ослячим похованням буде він похований; витягнуть його і кинуть далеко за ворота Єрусалима.","Зійди на Ливан і кричи, і на Васані піднеси голос твій і кричи з Аварима, бо знищені усі друзі твої.","Я говорив тобі під час благоденства твого; але ти сказав: «не послухаю». Така була поведінка твоя від самої юности твоєї, що ти не слухав голосу Мого.","Усіх пастирів твоїх розвіє вітер, і друзі твої підуть у полон; і тоді ти будеш осоромлений і посоромлений за усі злодіяння твої.","Ти, що живеш на Ливані, гніздишся на кедрах! яким жалюгідним будеш ти, коли осягнуть тебе муки, як болі жінки при пологах!","Живу Я, — сказав Господь: якби Ієхонія, син Іоакима, цар Юдейський, був перснем на правій руці Моїй, то і звідси Я зірву тебе","і віддам тебе до рук тих, що шукають душі твоєї, і до рук тих, яких ти боїшся, до рук Навуходоносора, царя Вавилонського, і до рук халдеїв,","і викину тебе і твою матір, яка народила тебе, у чужу країну, де ви не народилися, і там помрете;","а в землю, куди душа їх буде бажати повернутися, туди не повернуться.","«Невже ця людина, Ієхонія, є створіння огидне, відкинуте? чи він — сосуд непотребний? за що вони викинуті — він і плем’я його, і кинуті у країну, якої не знали?»","О, земле, земле, земле! слухай слово Господнє.","Так говорить Господь: запишіть чоловіка цього позбавленим дітей, чоловіком злощасним у дні свої, тому що ніхто вже з племені його не буде сидіти на престолі Давидовім і володарювати в Юдеї."],"x":{"3":"32.21.12|1.22.21","4":"32.17.25","5":"50.23.38","7":"32.21.14|31.13.3|31.37.24","8":"4.29.24|10.9.8-9","11":"11.23.31","12":"11.23.34","13":"2.19.13","16":"32.9.24|58.2.4","17":"32.26.23","18":"32.16.6|10.13.30","19":"32.36.30","20":"32.14.18|32.30.14","21":"32.2.20|32.5.23|32.11.7-8","22":"38.12.1","23":"32.4.31|32.22.14|30.48.21","24":"11.24.6|28.8.6|47.2.23","26":"11.24.12","27":"32.44.14","28":"38.8.8|11.24.15"}},{"v":["Горе пастирям, які гублять і розганяють овець пастви Моєї! — говорить Господь.","Тому так говорить Господь, Бог Ізраїлів, до пастирів, які пасуть народ Мій: ви розсіяли овець Моїх, і розігнали їх, і не наглядали за ними; ось, Я покараю вас за злі діяння ваші, — говорить Господь.","І зберу залишок стада Мого з усіх країн, куди Я вигнав їх, і поверну їх у двори їхні; і будуть плодитися і розмножуватися.","І поставлю над ними пастирів, які будуть пасти їх, і вони вже не будуть боятися і лякатися, і не будуть губитися, — говорить Господь.","Ось, настають дні, — говорить Господь, — і восставлю Давиду Паросток праведний, і воцариться Цар, і буде чинити мудро, і буде робити суд і правду на землі.","У дні Його Іуда спасеться й Ізраїль буде жити безпечно; і ось ім’я Його, яким будуть називати Його: «Господь виправдання наше!»","Тому, ось настають дні, — говорить Господь, — коли вже не будуть говорити: «живий Господь, Який вивів синів Ізраїлевих із землі Єгипетської»,","але: «живий Господь, Який вивів і Який привів плем’я дому Ізраїлевого із землі північної і з усіх земель, куди Я вигнав їх», і будуть жити на землі своїй.","Про пророків. Серце моє у мені роздирається, усі кістки мої трясуться; я — як п’яний, як людина, яку здолало вино, заради Господа і заради святих слів Його,","тому що земля наповнена перелюбниками, тому що плаче земля від прокляття; засохли пасовища пустелі, і прагнення їх — зло, і сила їх — неправда,","бо і пророк і священик — лицеміри; навіть у домі Моєму Я знайшов нечестя їх, — говорить Господь.","За те шлях їх буде для них, як слизькі місця у темряві: їх штовхнуть, і вони впадуть там; бо Я наведу на них біду, в рік відвідання їх, — говорить Господь.","І у пророках Самарії Я бачив безумство; вони пророкували ім’ям Ваала, і ввели в оману народ Мій, Ізраїля.","Але у пророках Єрусалима бачу жахливе: вони перелюбствують і ходять у неправді, підтримують руки лиходіїв, щоб ніхто не навертався від свого нечестя; всі вони переді Мною — як Содом, і жителі його — як Гоморра.","Тому так говорить Господь Саваоф про пророків: ось, Я нагодую їх полином і напою їх водою з жовчю, бо від пророків єрусалимських нечестя поширилося на усю землю.","Так говорить Господь Саваоф: не слухайте слів пророків, які пророкують вам: вони обманюють вас, розповідають мрії серця свого, а не від уст Господніх.","Вони постійно говорять тим, які зневажають Мене: «Господь сказав: мир буде у вас». І всякому, хто чинить за впертістю свого серця, говорять: «не прийде на вас лихо».","Бо хто стояв у раді Господа і бачив і чув слово Його? Хто прислуховувався до слова Його і почув?","Ось, іде буря Господня з люттю, буря грізна, і впаде на голову нечестивих.","Гнів Господа не відвернеться, доки Він не звершить і доки не виконає намірів серця Свого; у наступні дні ви ясно зрозумієте це.","Я не посилав пророків цих, а вони самі побігли; Я не говорив їм, а вони пророкували.","Якби вони стояли у Моїй раді, то оголосили б народу Моєму слова Мої і відводили б їх від злої путі їхньої і від злих діл їхніх.","Хіба Я — Бог тільки поблизу, — говорить Господь, — а не Бог і віддалік?","Чи може людина сховатися у потаємне місце, де Я не бачив би її? — говорить Господь. Чи не наповнюю Я небо і землю? — говорить Господь.","Я чув, що говорять пророки, Моїм ім’ям пророкують неправду. Вони говорять: «мені снилося, мені снилося».","Чи довго це буде у серці пророків, які пророкують неправду, пророкують обман свого серця?","Чи думають вони довести народ Мій до забуття імені Мого за допомогою снів своїх, які вони переказують один одному, як батьки їхні забули ім’я Моє через Ваала?","Пророк, який бачив сон, нехай і розповідає його як сон; а в якого Моє слово, той нехай говорить слово Моє вірно. Що спільного у полови з чистим зерном? — говорить Господь.","Слово Моє чи не подібне до вогню, — говорить Господь, — і чи не подібне до молота, який розбиває скелю?","Тому, ось Я — на пророків, — говорить Господь, — які крадуть слова Мої один в одного.","Ось, Я — на пророків, — говорить Господь, — які діють своїм язиком, а говорять: «Він сказав».","Ось, Я — на пророків неправдивих снів, — говорить Господь, — які розповідають їх і вводять народ Мій в оману своїми обманами і звабою, тоді як Я не посилав їх і не повелівав їм, і вони ніякої користи не приносять народу цьому, — говорить Господь.","Якщо запитає у тебе народ цей, або пророк, або священик: «який тягар від Господа?», то скажи їм: «який тягар? Я покину вас, — говорить Господь».","Якщо пророк, або священик, або народ скаже: «тягар від Господа», Я покараю ту людину і дім її.","Так говоріть одне одному і брат братові: «що відповів Господь?» або: «що сказав Господь?»","А цього слова: «тягар від Господа», надалі не вживайте: бо тягарем буде такій людині слово її, тому що ви спотворюєте слова живого Бога, Господа Саваофа Бога нашого.","Так говори пророку: «що відповів тобі Господь?» або: «що сказав Господь?»","А якщо ви ще будете говорити: «тягар від Господа», то так говорить Господь: за те, що ви кажете слово це: «тягар від Господа», тоді як Я послав сказати вам: «не говоріть: тягар від Господа», —","за те, ось, Я забуду вас зовсім і залишу вас, і місто це, яке Я дав вам і батькам вашим, відкину від лиця Мого","і покладу на вас ганьбу вічну й неславу вічну, які не забудуться."],"x":{"1":"36.34.3","3":"4.30.3|32.29.14|52.1.54","4":"25.22.1|31.40.11|31.45.13|32.3.15|36.34.12","5":"31.4.2|32.33.15|37.9.24|48.3.8|48.6.12|53.1.45","6":"4.33.28|32.33.16","7":"32.16.14","10":"32.5.7|32.9.2|32.12.4","11":"32.8.10","12":"32.13.16","14":"32.5.30|31.1.9|31.28.15|36.13.22","15":"32.9.15","16":"32.27.9","17":"32.6.14|36.13.10|48.10.2","18":"24.15.8|31.40.13","19":"32.30.23","20":"32.30.24","21":"32.14.14|32.27.15|32.29.9","22":"31.55.11","24":"24.34.21|25.138.7-9|30.23.27|40.9.2","25":"32.5.31|32.14.14","27":"6.3.7","28":"56.4.11","29":"30.48.1|52.24.32|76.11.5","30":"4.18.20|32.14.15","31":"36.13.6|36.22.28","32":"36.14.9|46.3.4","33":"36.12.9","40":"32.20.11"}},{"v":["Господь показав мені: і ось, два кошики зі смоквами поставлені перед храмом Господнім, після того, як Навуходоносор, цар Вавилонський, вивів з Єрусалима полоненими Ієхонію, сина Іоакимового, царя Юдейського, і князів юдейських з теслями і ковалями і привів їх у Вавилон:","один кошик був зі смоквами дуже добрими, якими бувають смокви ранні, а другий кошик — зі смоквами дуже поганими, які за непридатністю їх не можна їсти.","І сказав мені Господь: що бачиш ти, Єреміє? Я сказав: смокви, смокви добрі — дуже добрі, а погані — дуже погані, так що їх не можна їсти, тому що вони дуже недобрі.","І було до мене слово Господнє:","так говорить Господь, Бог Ізраїлів: подібно до цих смокв добрих Я ви́знаю добрими переселенців юдейських, яких Я послав з цього місця у землю Халдейську;","і зверну на них очі Мої на благо їм і поверну їх у землю цю, і влаштую їх, а не розорю, і насажду їх, а не викоріню;","і дам їм серце, щоб знати Мене, що Я Господь, і вони будуть Моїм народом, а Я буду їхнім Богом; бо вони навернуться до Мене усім серцем своїм.","А про погані смокви, яких і їсти не можна за непридатністю їх, так говорить Господь: таким Я зроблю Седекію, царя Юдейського, і князів його та інших єрусалимлян, які залишаються у землі цій і живуть у землі Єгипетській;","і віддам їх на озлоблення і на злостраждання в усіх царствах земних, на наругу, на притчу, на посміяння і прокляття в усіх місцях, куди Я вижену їх.","І пошлю на них меч, голод і моровицю, доки не знищу їх із землі, яку Я дав їм і батькам їхнім."],"x":{"1":"11.24.12:14","6":"32.42.10","7":"4.30.6|32.30.22|32.32.39|36.11.19|75.8.10","8":"32.29.17","9":"4.28.25|25.43.14|32.15.4","10":"32.14.21"}},{"v":["Слово, яке було до Єремії про весь народ юдейський, у четвертий рік Іоакима, сина Іосії, царя Юдейського, — це був перший рік Навуходоносора, царя Вавилонського, —","і яке пророк Єремія промовив до всього народу юдейського і до всіх жителів Єрусалима і сказав:","від тринадцятого року Іосії, сина Амонового, царя Юдейського, до цього дня, ось уже двадцять три роки, було до мене слово Господнє, і я з раннього ранку говорив вам, — і ви не слухали.","Господь посилав до вас усіх рабів Своїх, пророків, з раннього ранку посилав, — і ви не слухали і не прихиляли вуха свого, щоб слухати.","Вам говорили: «наверніться кожен від злої путі своєї і від злих діл своїх і живіть на землі, яку Господь дав вам і батькам вашим із віку у вік;","і не ходіть слідом інших богів, щоб служити їм і поклонятися їм, і не прогнівляйте Мене ділами рук своїх, і не зроблю вам зла».","Але ви не слухали Мене, — говорить Господь, — прогнівляючи Мене ділами рук своїх, на зло собі.","Тому так говорить Господь Саваоф: за те, що ви не слухали слів Моїх,","ось, Я пошлю і візьму всі племена північні, — говорить Господь, — і пошлю до Навуходоносора, царя Вавилонського, раба Мого, і приведу їх на землю цю і на жителів її і на усі навколишні народи; і зовсім знищу їх і зроблю їх жахом і посміянням і вічним запустінням.","І припиню у них голос радости і голос веселощів, голос нареченого і голос нареченої, звук жорен і світло світильника.","І вся земля ця буде пустелею і жахом; і народи ці будуть служити цареві Вавилонському сімдесят років.","І буде: коли виповниться сімдесят років, покараю царя Вавилонського і той народ, — говорить Господь, — за їх нечестя, і землю Халдейську, і зроблю її вічною пустелею.","І звершу над тією землею усі слова Мої, які Я вимовив на неї, усе написане у цій книзі, яку Єремія по-пророцьки прорік на усі народи.","Бо і їх поневолять численні народи і царі великі; і Я віддам їм за їхніми вчинками і за ділами рук їхніх.","Бо так сказав мені Господь, Бог Ізраїлів: візьми з руки Моєї чашу цю з вином люті і напої з неї усі народи, до яких Я посилаю тебе.","І вони вип’ють, і будуть хитатися і збожеволіють, побачивши меч, який Я пошлю на них.","І взяв я чашу з руки Господньої і напоїв з неї всі народи, до яких послав мене Господь:","Єрусалим і міста юдейські, і царів його і князів його, щоб спустошити їх і зробити жахом, посміянням і прокляттям, як і видно нині,","фараона, царя Єгипетського, і слуг його, і князів його і весь народ його,","і весь змішаний народ, і всіх царів землі Уца, і всіх царів землі Филистимської, і Аскалон, і Газу, й Екрон, і залишки Азота,","Едома, і Моава, і синів Аммонових,","і всіх царів Тира, і всіх царів Сидона, і царів островів, які за морем,","Дедана, і Фему, і Буза, й усіх, хто стриже волосся на скронях,","і всіх царів Аравії, і всіх царів народів різноплемінних, які живуть у пустелі,","усіх царів Зимврії, і всіх царів Елама, і всіх царів Мідії,","і всіх царів півночі, близьких один до одного і далеких, і всі царства земні, які на лиці землі, а цар Сесаха вип’є після них.","І скажи їм: так говорить Господь Саваоф, Бог Ізраїлів: пийте і сп’янійте, і вивергніть і впадіть, і не вставайте, побачивши меч, який Я пошлю на вас.","Якщо ж вони будуть відмовлятися брати чашу з руки твоєї, щоб пити, то скажи їм: так говорить Господь Саваоф: ви неодмінно будете пити.","Бо ось на місто це, на якому наречене ім’я Моє, Я починаю наводити біди; і чи ви залишитеся непокараними? Ні, не залишитеся непокараними; бо Я закликаю меч на усіх, хто живе на землі, — говорить Господь Саваоф.","Тому проречи на них усі слова ці і скажи їм: Господь прогримить з висоти і з оселі святині Своєї подасть голос Свій; страшно прогримить на оселю Свою; як ті, що топчуть у точилі, викликне на усіх, хто живе на землі.","Шум дійде до країв землі, бо у Господа змагання з народами: Він буде судитися з усякою плоттю, нечестивих Він віддасть мечу, — говорить Господь.","Так говорить Господь Саваоф: ось, біда піде від народу до народу, і великий вихор здійметься від країв землі.","І будуть уражені Господом у той день від краю землі до краю землі, не будуть оплакані і не будуть прибрані і поховані, гноєм будуть на лиці землі.","Ридайте, пастирі, і стогніть, і посипайте себе порохом, вожді стада; бо виповнилися дні ваші для заколення і розсіяння вашого, і впадете, як дорогий сосуд.","І не буде притулку пастирям і спасіння вождям стада.","Чутно волання пастирів і ридання вождів стада, бо спустошив Господь пасовище їх.","Знищуються мирні селища від люті гніву Господнього.","Він залишив оселю Свою, як лев; і земля їхня зробилася пустелею від люті спустошувача і від полум’яного гніву Його."],"x":{"4":"32.7.25|32.29.19|32.44.4","5":"11.17.13|32.18.11|32.35.15|42.3.8","6":"4.8.19|4.11.28|32.7.6","9":"11.17.23|32.19.4:8","10":"31.24.8|32.7.34","12":"13.36.21-22|14.1.1|32.29.10|37.9.2","14":"32.27.7","15":"76.16.19","16":"44.3.11","18":"31.51.21|32.29.22|32.42.18","19":"32.46.2","21":"32.48.1","23":"2.19.27|32.9.26","25":"32.49.34","26":"32.51.41","27":"32.51.7|31.51.21","29":"56.4.17","30":"39.3.16|40.1.2","31":"39.3.2|46.3.8|76.19.15","33":"31.34.3|32.7.33|76.11.8","34":"31.65.12"}},{"v":["На початку царювання Іоакима, сина Іосії, царя Юдейського, було таке слово від Господа:","так говорить Господь: стань надворі дому Господнього і скажи до усіх міст Юдеї, які приходять на поклоніння у дім Господній, усі ті слова, які повелю тобі сказати їм; не відніми ні слова.","Можливо, вони послухають і навернуться кожен від злої путі своєї, і тоді Я відміню ту біду, яку думаю зробити їм за злі діяння їхні.","І скажи їм: так говорить Господь: якщо ви не послухаєтеся Мене у тім, щоб жити за законом Моїм, який Я дав вам,","щоб слухати слова рабів Моїх, пророків, яких Я посилаю до вас, посилаю з раннього ранку, і яких ви не слухаєте, —","то з домом цим Я зроблю те саме, що з Силомом, і місто це віддам на прокляття усім народам землі.","Священики і пророки і весь народ слухали Єремію, коли він говорив ці слова у домі Господньому.","І коли Єремія сказав усе, що Господь повелів йому сказати усьому народові, тоді схопили його священики і пророки і весь народ, і сказали: «ти повинен померти;","навіщо ти пророкуєш ім’ям Господа і говориш: дім цей буде як Силом, і місто це стане порожнім, залишиться без жителів?» І зібрався весь народ проти Єремії у домі Господньому.","Коли почули про це князі юдейські, то прийшли з дому царя до дому Господнього і сіли біля входу в нові ворота дому Господнього.","Тоді священики і пророки так сказали князям і всьому народові: «смертний вирок цьому чоловікові! тому що він пророкує проти міста цього, як ви чули своїми вухами».","І сказав Єремія усім князям і всьому народові: «Господь послав мене пророкувати проти дому цього і проти міста цього усі ті слова, які ви чули;","отже, виправте путі ваші і діяння ваші і послухайтеся гласу Господа Бога вашого, і Господь відмінить біду, яку прорік на вас;","а щодо мене, ось — я у ваших руках; робіть зі мною, що в очах ваших здасться добрим і справедливим;","тільки твердо знайте, що коли ви умертвите мене, то невинну кров покладете на себе і на місто це і на жителів його; бо істинно Господь послав мене до вас сказати усі ті слова у вуха ваші».","Тоді князі і весь народ сказали священикам і пророкам: «цей чоловік не підлягає смертному вироку, тому що він говорив нам ім’ям Господа Бога нашого».","І зі старійшин землі встали деякі і сказали усім народним зборам:","«Михей морасфитянин пророкував у дні Єзекії, царя Юдейського, і сказав усьому народові юдейському: так говорить Господь Саваоф: Сион буде виораний, як поле, і Єрусалим зробиться купою руїн, і гора дому цього — лісистим пагорбом.","Чи умертвили його за це Єзекія, цар Юдейський, і весь Іуда? Чи не убоявся він Господа і чи не благав Господа? і Господь відмінив біду, яку прорік на них; а ми хочемо зробити велике зло душам нашим?","Пророкував також ім’ям Господа такий собі Урія, син Шемаії, з Кириаф-Іарима, — і пророкував проти міста цього і проти землі цієї точно такими самими словами, як Єремія.","Коли почув слова його цар Іоаким і всі вельможі його і всі князі, то шукав цар умертвити його. Почувши про це, Урія убоявся й утік, і відійшов у Єгипет.","Але цар Іоаким і у Єгипет послав людей: Елнафана, сина Ахборового, й інших з ним.","І вивели Урію з Єгипту і привели його до царя Іоакима, і він умертвив його мечем і кинув труп його, де були простонародні гробниці.","Але рука Ахикама, сина Сафанового, була за Єремію, щоб не віддавати його у руки народу на вбивство»."],"x":{"2":"4.4.2|26.30.6","3":"32.18.8|39.2.13","5":"32.7.13","6":"32.7.14","9":"32.7.12","10":"32.36.10","11":"33.4.13","13":"32.7.3","15":"32.22.17|50.23.35","18":"43.1.1|43.3.12","19":"32.18.8|42.3.10","20":"6.18.12","23":"32.22.17","24":"11.22.12|32.39.14"}},{"v":["На початку царювання Іоакима (Седекії*), сина Іосії, царя Юдейського, було слово це до Єремії від Господа:","так сказав мені Господь: зроби собі пута і ярмо і поклади їх собі на шию;","і пошли такі самі до царя Ідумейського, і до царя Моавитського, і до царя синів Аммонових, і до царя Тира, і до царя Сидона, через послів, які прийшли в Єрусалим до Седекії, царя Юдейського;","і накажи їм сказати государям їх: так говорить Господь Саваоф, Бог Ізраїлів: так скажіть государям вашим:","Я створив землю, людину і тварин, які на лиці землі, великою могутністю Моєю і простягнутою правицею Моєю, і віддав її, кому Мені благоугодно було.","І нині Я віддаю усі землі ці у руки Навуходоносора, царя Вавилонського, раба Мого, і навіть звірів польових віддаю йому на служіння.","І всі народи будуть служити йому і синові його і синові сина його, доки не прийде час і його землі і йому самому; і будуть служити йому багато народів і царі великі.","І якщо який народ і царство не захоче служити йому, Навуходоносору, царю Вавилонському, і не схилить шиї своєї під ярмо царя Вавилонського, — цей народ Я покараю мечем, голодом і моровицею, — говорить Господь, — доки не знищу їх рукою його.","І ви не слухайте своїх пророків і своїх віщунів, і своїх сновидців, і своїх чаклунів, і своїх волхвів, які говорять вам: «не будете служити цареві Вавилонському».","Бо вони пророкують вам неправду, щоб виселити вас із землі вашої, і щоб Я вигнав вас і ви загинули.","Народ же, який схилить шию свою під ярмо царя Вавилонського і стане служити йому, Я залишу на землі своїй, — говорить Господь, — і він буде обробляти її і жити на ній.","І Седекії, царю Юдейському, я говорив усі ці слова і сказав: схиліть шию свою під ярмо царя Вавилонського і служіть йому і народу його, і будете живі.","Навіщо помирати тобі і народу твоєму від меча, голоду і моровиці, як прорік Господь про той народ, який не буде служити цареві Вавилонському?","І не слухайте слів пророків, які говорять вам: «не будете служити цареві Вавилонському»; бо вони пророкують вам неправду.","Я не посилав їх, — говорить Господь; і вони неправдиво пророкують ім’ям Моїм, щоб Я вигнав вас і щоб ви загинули, — ви і пророки ваші, які пророкують вам.","І священикам і всьому народові цьому я говорив: так говорить Господь: не слухайте слів пророків ваших, які пророкують вам і говорять: «ось, скоро повернуті будуть із Вавилона сосуди дому Господнього»; бо вони пророкують вам неправду.","Не слухайте їх, служіть цареві Вавилонському і живіть; навіщо доводити місто це до спустошення?","А якщо вони пророки, і якщо у них є слово Господнє, то нехай благають Господа Саваофа, щоб сосуди, які залишаються у домі Господньому й у домі царя Юдейського і у Єрусалимі, не перейшли у Вавилон.","Бо так говорить Господь Саваоф про стовпи і про мідне море і про підніжжя і про інші речі, які залишилися у цьому місті,","яких Навуходоносор, цар Вавилонський, не взяв, коли Ієхонію, сина Іоакима, царя Юдейського, й усіх знатних юдеїв і єрусалимлян вивів з Єрусалима у Вавилон,","бо так говорить Господь Саваоф, Бог Ізраїлів, про сосуди, які залишилися в домі Господньому й у домі царя Юдейського і в Єрусалимі:","вони будуть віднесені у Вавилон і там залишаться до того дня, коли Я відвідаю їх, — говорить Господь, — і виведу їх і поверну їх на місце це."],"x":{"2":"13.10.4|44.1.13","3":"32.48.1","5":"37.4.22","6":"32.25.9|32.28.14","7":"32.25.14","9":"32.23.16","13":"36.18.32","14":"35.2.24","15":"32.14.14|32.23.21","16":"32.28.3","19":"11.25.13|32.52.17","20":"11.24.12","22":"11.25.13|13.36.18:22"},"n":{"1":["Седекії."]}},{"v":["У той самий рік, на початку царювання Седекії, царя Юдейського, у четвертий рік, у п’ятий місяць, Ананія, син Азура, пророк із Гаваона, говорив мені у домі Господньому перед очима священиків і всього народу і сказав:","так говорить Господь Саваоф, Бог Ізраїлів: знищу ярмо царя Вавилонського;","через два роки Я поверну на місце це усі сосуди дому Господнього, які Навуходоносор, цар Вавилонський, узяв з цього місця і переніс їх у Вавилон;","й Ієхонію, сина Іоакима, царя Юдейського, і всіх полонених юдеїв, які прийшли у Вавилон, Я поверну на місце це, — говорить Господь; бо знищу ярмо царя Вавилонського.","І сказав Єремія пророк пророку Ананії перед очима священиків і перед очима усіх людей, які стояли у домі Господньому, —","і сказав Єремія пророк: нехай буде так, нехай сотворить це Господь! нехай виконає Господь слова твої, які ти промовив про повернення з Вавилона сосудів дому Господнього і всіх полонених на місце це!","Тільки вислухай слово це, яке я скажу вголос тобі і вголос усьому народу:","пророки, які здавна були раніше мене і раніше тебе, пророкували багатьом землям і великим царствам війну і біду і моровицю.","Якщо який пророк пророкував мир, то тоді тільки він визнаний був за пророка, якого істинно послав Господь, коли збувалося слово того пророка.","Тоді пророк Ананія узяв ярмо з шиї Єремії пророка і розбив його.","І сказав Ананія перед очима всього народу ці слова: так говорить Господь: так знищу ярмо Навуходоносора, царя Вавилонського, через два роки, знявши його з шиї усіх народів. І пішов Єремія своєю дорогою.","І було слово Господнє до Єремії після того, як пророк Ананія розбив ярмо з шиї пророка Єремії:","йди і скажи Ананії: так говорить Господь: ти скрушив ярмо дерев’яне, і зробиш замість нього ярмо залізне.","Бо так говорить Господь Саваоф, Бог Ізраїлів: залізне ярмо покладу на шию усіх цих народів, щоб вони працювали на Навуходоносора, царя Вавилонського, і вони будуть служити йому, і навіть звірів польових Я віддав йому.","І сказав пророк Єремія пророку Ананії: послухай, Ананіє, Господь тебе не посилав, і ти подаєш надію цьому народу неправдиво.","Тому так говорить Господь: ось, Я скину тебе з лиця землі; у цьому ж році ти помреш, тому що ти говорив усупереч Господу.","І помер пророк Ананія у тому самому році, у сьомому місяці."],"x":{"1":"5.21.17","2":"32.27.12","3":"32.27.16","9":"4.18.22","14":"32.27.6","16":"4.13.5"}},{"v":["І ось слова листа, який пророк Єремія послав з Єрусалима до залишку старійшин серед переселенців і до священиків, і до пророків, і до усього народу, яких Навуходоносор вивів з Єрусалима у Вавилон, —","після того, як вийшли з Єрусалима цар Ієхонія і цариця і євнухи, князі Юдеї і Єрусалима, і теслі і ковалі, —","через Елеасу, сина Сафанового, і Гемарію, сина Хелкіїного, яких Седекія, цар Юдейський, посилав у Вавилон до Навуходоносора, царя Вавилонського:","так говорить Господь Саваоф, Бог Ізраїлів, усім полоненим, яких Я переселив з Єрусалима у Вавилон:","будуйте доми і живіть у них, і розводьте сади і їжте плоди їх;","беріть дружин і народжуйте синів і дочок; і синам своїм беріть дружин і дочок своїх віддавайте заміж, щоб вони народжували синів і дочок, і розмножуйтеся там, а не зменшуйтеся;","і турбуйтеся про добробут міста, в яке Я переселив вас, і моліться за нього Господу; бо при добробуті його і вам буде мир.","Бо так говорить Господь Саваоф, Бог Ізраїлів: нехай не зваблюють вас пророки ваші, які серед вас, і ворожбити ваші; і не слухайте снів ваших, які вам сняться;","неправдиво пророкують вони вам ім’ям Моїм; Я не посилав їх, — говорить Господь.","Бо так говорить Господь: коли виповниться вам у Вавилоні сімдесят років, тоді Я відвідаю вас і виконаю добре слово Моє про вас, щоб повернути вас на місце це.","Бо тільки Я знаю наміри, які маю щодо вас, — говорить Господь, — наміри на благо, а не на зло, щоб дати вам майбуття і надію.","І взиватимете до Мене, і підете і помолитеся Мені, і Я почую вас;","і будете шукати Мене і знайдете, якщо будете шукати Мене усім серцем вашим.","І буду я знайдений вами, — говорить Господь, — і поверну вас з полону і зберу вас із усіх народів і з усіх місць, куди Я вигнав вас, — говорить Господь, — і поверну вас у те місце, звідки переселив вас.","Ви говорите: «Господь послав нам пророків і у Вавилоні».","Так говорить Господь про царя, що сидить на престолі Давидовому, і про весь народ, який живе у місті цьому, про братів ваших, які не відведені з вами у полон, —","так говорить про них Господь Саваоф: ось, Я пошлю на них меч, голод і моровицю, і зроблю їх такими, як негідні смокви, які не можна їсти через непридатність їх;","і буду переслідувати їх мечем, голодом і моровицею, і віддам їх на озлоблення усім царствам землі, на прокляття і жах, на посміяння і наругу між усіма народами, куди Я вижену їх,","за те, що вони не слухали слів Моїх, — говорить Господь, — з якими Я посилав до них рабів Моїх, пророків, посилав з раннього ранку, але вони не слухали, — говорить Господь.","А ви, усі переселенці, яких Я послав з Єрусалима у Вавилон, слухайте слово Господнє:","так говорить Господь Саваоф, Бог Ізраїлів, про Ахава, сина Колії, і про Седекію, сина Маасеї, які пророкують вам ім’ям Моїм неправду: ось, Я віддам їх до рук Навуходоносора, царя Вавилонського, і він умертвить їх перед вашими очима.","І прийнято буде від них усіма переселенцями юдейськими, які у Вавилоні, проклинати так: «нехай зробить тобі Господь те саме, що Седекії та Ахаву», яких цар Вавилонський засмажив на вогні","за те, що вони робили мерзоти в Ізраїлі: перелюбствували з дружинами ближніх своїх і ім’ям Моїм говорили неправду, чого Я не повелівав їм; Я знаю це, і Я свідок, — говорить Господь.","І Шемаії нехеламитянину скажи:","так говорить Господь Саваоф, Бог Ізраїлів: за те, що ти посилав листи від імені свого до усього народу, який у Єрусалимі, і до священика Софонії, сина Маасеї, і до усіх священиків, і писав:","«Господь поставив тебе священиком замість священика Іодая, щоб ти був між охоронцями у домі Господньому за всякою людиною, яка шаленіє і пророкує, і щоб ти саджав такого у в’язницю й у колоду:","чому ж ти не заборониш Єремії анафофському пророкувати у вас?","Бо він і до нас у Вавилон надіслав сказати: полон буде тривалим: будуйте доми і живіть у них; розводьте сади і їжте плоди їх».","Коли Софонія священик прочитав цей лист уголос пророку Єремії,","тоді було слово Господнє до Єремії:","пошли до усіх переселенців сказати: так говорить Господь про Шемаію нехеламитянина: за те, що Шемаія у вас пророкує, а Я не посилав його, і обнадіює вас неправдиво, —","за те, так говорить Господь: ось, Я покараю Шемаію нехеламитянина і плем’я його; не буде від нього людини, яка живе серед народу цього, і не побачить він того добра, яке Я зроблю народу Моєму, — говорить Господь; бо він говорив усупереч Господу."],"x":{"2":"11.24.12","7":"35.1.11","8":"32.14.14|32.23.21|32.27.15","9":"32.23.16|50.24.5","10":"32.25.12","12":"31.58.9","13":"50.7.7","14":"4.30.3","17":"32.24.8","18":"32.15.4","19":"32.25.4","21":"36.13.8","22":"31.65.15|32.44.12","28":"36.11.3","31":"32.28.15","32":"32.28.16"}},{"v":["Слово, яке було до Єремії від Господа:","так говорить Господь, Бог Ізраїлів: напиши собі всі слова, які Я говорив тобі, у книгу.","Бо ось, настають дні, — говорить Господь, — коли Я поверну з полону народ Мій, Ізраїля й Іуду, — говорить Господь; і приведу їх знову в ту землю, яку дав батькам їхнім, і вони будуть володіти нею.","І ось ті слова, які сказав Господь про Ізраїля й Іуду.","Так сказав Господь: голос сум’яття і жаху чуємо ми, а не миру.","Запитайте і розсудіть: чи народжує чоловік? Чому ж Я бачу у кожного чоловіка руки на стегнах його, як у жінки при пологах, і обличчя у всіх бліді?","О, горе! великий той день, не було подібного до нього; це — тяжкий час для Якова, але він буде спасений від нього.","І буде у той день, — говорить Господь Саваоф: розіб’ю ярмо його, яке на шиї твоїй, і кайдани твої розірву; і не будуть уже служити чужоземцям,","але будуть служити Господу Богу своєму і Давиду, царю своєму, якого Я відновлю їм.","І ти, рабе Мій Якове, не бійся, — говорить Господь, і не страшися, Ізраїлю; бо ось, Я спасу тебе з далекої країни і плем’я твоє із землі полону їх; і повернеться Яків і буде жити спокійно і мирно, і ніхто не буде страшити його,","бо Я з тобою, — говорить Господь, — щоб спасати тебе: Я зовсім знищу усі народи, серед яких розсіяв тебе, а тебе не знищу; Я буду карати тебе за мірою, але непокараним не залишу тебе.","Бо так говорить Господь: рана твоя незцілима, виразка твоя жорстока;","ніхто не піклується про діла твої, щоб загоїти рану твою; цілющого лікування немає для тебе;","усі друзі твої забули тебе, не шукають тебе; бо Я вразив тебе ударами ворожими, жорстоким покаранням за безліч беззаконь твоїх, тому що гріхи твої примножилися.","Чого волаєш ти про рани твої, про тяжкість хвороби твоєї? за безліч беззаконь твоїх Я зробив тобі це, тому що гріхи твої примножилися.","Але всі, що пожирають тебе, будуть пожерті; й усі вороги твої, усі самі підуть у полон, і спустошувачі твої будуть спустошені, й усіх грабіжників твоїх віддам на пограбування.","Я обкладу тебе пластирем і зцілю тебе від ран твоїх, — говорить Господь. Тебе називали відкинутим, говорячи: «ось Сион, про який ніхто не запитує»;","так говорить Господь: ось, поверну полон наметів Якова і селища його помилую; і місто знову буде побудоване на пагорбі своєму, і храм улаштується, як і раніше.","І вознесуться з них подяка і голос тих, що веселяться; і Я примножу їх, і не будуть зменшуватися, і прославлю їх, і не будуть принижені.","І сини його будуть, як раніше, і сонм його буде стояти переді Мною, і покараю усіх гнобителів його.","І буде вождь його з нього самого, і владика його вийде із середовища його; і Я наближу його, і він приступить до Мене; бо хто відважиться сам собою наблизитися до Мене? — говорить Господь.","І ви будете Моїм народом, і Я буду вам Богом.","Ось, лютий вихор іде від Господа, вихор грізний; він упаде на голову нечестивих.","Полум’яний гнів Господа не відвернеться, доки Він не звершить і не виконає намірів серця Свого. В останні дні зрозумієте це."],"x":{"2":"32.36.2","3":"32.25.12","6":"32.4.31","7":"39.2.11|40.5.18|46.1.14","9":"36.34.24","10":"31.44.2|32.46.27","11":"3.14.18|31.41.10|32.46.28","12":"32.8.22","14":"33.1.19|32.2.19","15":"32.13.22|32.15.18","16":"1.23.22|31.41.11","17":"32.33.6","18":"32.31.23","21":"43.5.2|25.39.8|53.4.34","22":"32.24.7","23":"32.23.19","24":"32.23.20"}},{"v":["У той час, — говорить Господь, — Я буду Богом усім племенам Ізраїлевим, а вони будуть Моїм народом.","Так говорить Господь: народ, який уцілів від меча, знайшов милість у пустелі; йду заспокоїти Ізраїля.","Здаля явився мені Господь і сказав: любов’ю вічною Я полюбив тебе і тому простяг до тебе благовоління.","Я знову влаштую тебе, і ти будеш улаштована, діво Ізраїлева, знову будеш прикрашатися тимпанами твоїми і виходити у хороводі тих, що веселяться;","знову розведеш виноградники на горах Самарії; виноградарі, які будуть розводити їх, самі будуть і користуватися ними.","Бо буде день, коли вартові на горі Єфремовій проголосять: «вставайте, і зійдемо на Сион до Господа Бога нашого».","Бо так говорить Господь: радісно співайте про Якова і викликуйте перед главою народів: проголошуйте, славте і говоріть: «спаси, Господи, народ Твій, залишок Ізраїля!»","Ось, Я приведу їх із країни північної і зберу їх із країв землі; сліпий і кульгавий, вагітна і породілля разом з ними, — великий сонм повернеться сюди.","Вони пішли зі сльозами, а Я поведу їх з утіхою; поведу їх біля потоків вод дорогою рівною, на якій не спіткнуться; бо Я — отець Ізраїля, і Єфрем — первісток Мій.","Слухайте слово Господнє, народи, і сповістіть островам віддаленим і скажіть: «Хто розсіяв Ізраїля, Той і збере його, і буде охороняти його, як пастир стадо своє»;","бо відкупить Господь Якова і визволить його від руки того, хто був сильнішим за нього.","І прийдуть вони, і будуть торжествувати на висотах Сиону; і зберуться до благосердя Господа, до пшениці і вина і єлею, до агнців і волів; і душа їх буде як напоєний водою сад, і вони не будуть уже більше знемагати.","Тоді дівчина буде веселитися у хороводі, і юнаки і старці разом; і зміню сум їх на радість і втішу їх, і звеселю їх після скорботи їх.","І насичу душу священиків жиром, і народ Мій насититься благами Моїми, — говорить Господь.","Так говорить Господь: голос чутно у Рамі, крик і гірке ридання; Рахиль плаче за дітьми своїми і не хоче втішитися за дітей своїх, бо їх немає.","Так говорить Господь: утримай голос твій від ридання і очі твої від сліз, бо є нагорода за труд твій, — говорить Господь, — і повернуться вони із землі ворожої.","І є надія для твого майбутнього, — говорить Господь, — і повернуться сини твої у наділи свої.","Чую Єфрема, який плаче: «Ти покарав мене, і я покараний, як телець неприборканий; наверни мене, і навернуся, бо Ти Господь Бог мій.","Коли я був навернений, я каявся, і коли був напоумлений, бив себе по стегнах; я був посоромлений, я був знічений, тому що ніс неславу юности моєї».","Чи не дорогий у Мене син Єфрем? чи не улюблене дитя? бо, як тільки заговорю про нього, завжди з любов’ю згадую про нього; нутро Моє обурюється за нього; змилосерджуся над ним, — говорить Господь.","Постав собі дороговкази, постав собі стовпи, поверни серце твоє на дорогу, на путь, якою ти йшла; повертайся, діво Ізраїлева, повертайся у ці міста твої.","Чи довго тобі блукати, відпала дочко? Бо Господь сотворить на землі щось нове: жона спасе чоловіка.","Так говорить Господь Саваоф, Бог Ізраїлів: надалі, коли Я поверну полон їх, будуть говорити на землі Іуди й у містах його це слово: «нехай благословить тебе Господь, оселя правди, гора свята!»","Й оселиться на ній Іуда й усі міста його разом, хлібороби і ті, що ходять зі стадами.","Бо Я напою душу стомлену і насичу всяку душу скорботну.","При цьому я прокинувся і подивився, і сон мій був приємний мені.","Ось, настають дні, — говорить Господь, — коли Я засію дім Ізраїлів і дім Іудин сіменем людини і сіменем худоби.","І як Я спостерігав за ними, викорінюючи і знищуючи, і руйнуючи і гублячи, й ушкоджуючи, так буду спостерігати за ними, творячи і насаджуючи, — говорить Господь.","У ті дні вже не будуть говорити: «батьки їли кислий виноград, а у дітей на зубах оскома»,","але кожен буде помирати за своє власне беззаконня; хто буде їсти кислий виноград, у того на зубах і оскома буде.","Ось настають дні, — говорить Господь, — коли Я укладу з домом Ізраїля і з домом Іуди новий завіт,","не такий завіт, який Я уклав з батьками їхніми у той день, коли узяв їх за руку, щоб вивести їх із землі Єгипетської; той завіт Мій вони порушили, хоч Я залишався у союзі з ними, — говорить Господь.","Але ось завіт, який Я укладу з домом Ізраїлевим після тих днів, — говорить Господь: вкладу закон Мій у нутрощі їх і на серцях їхніх напишу його, і буду їм Богом, а вони будуть Моїм народом.","І вже не будуть учити один одного, брат брата, і говорити: «пізнайте Господа», бо усі самі будуть знати Мене, від малого до великого, — говорить Господь, — тому що Я прощу беззаконня їхні і гріхів їхніх уже не пом’яну більше.","Так говорить Господь, Який дав сонце для освітлення вдень, устави місяцю і зіркам для освітлення вночі, Який збурює море, так що хвилі його ревуть; Господь Саваоф — ім’я Йому.","Якщо ці устави перестануть діяти переді Мною, — говорить Господь, — то і плем’я Ізраїлеве перестане бути народом переді Мною назавжди.","Так говорить Господь: якщо небо може бути виміряне вгорі, й основи землі досліджені внизу, то і Я відкину все плем’я Ізраїлеве за все те, що вони робили, — говорить Господь.","Ось, настають дні, — говорить Господь, — коли місто впорядковане буде на славу Господа від вежі Анамеїла до воріт наріжних,","і землемірний шнур піде далі прямо до пагорба Гарива й обійде Гоаф.","І вся долина трупів і попелу, і все поле до потоку Кедрона, до рогу кінських воріт на схід, буде святинею Господа; не зруйнується і не розпадеться повіки."],"x":{"1":"32.24.7","3":"52.1.54|53.6.44|53.13.1","4":"25.121.3|32.33.7","5":"31.65.21","6":"31.2.3","7":"31.2.2","8":"4.30.3","9":"64.6.18|1.4.22","10":"32.32.37|36.11.16","11":"52.11.22","12":"31.58.11","13":"25.148.12|31.65.18|53.16.20","14":"31.66.21","15":"50.2.18","18":"28.1.3|30.17.21|38.10.11|33.5.21","19":"62.2.4","20":"62.9.16","22":"31.43.19|64.5.17|76.21.5","23":"52.1.54|32.29.14|32.30.3|32.32.44","25":"31.40.29|50.11.28|75.12.12","28":"32.24.6|32.32.42|32.45.4","29":"36.18.2-3","31":"75.8.8","33":"75.8.10|32.24.7","34":"31.54.13|53.6.45|75.8.11|32.33.8|43.7.18|54.10.43","36":"0.1.16|25.135.8-9","37":"32.33.20-21","38":"17.3.1|13.26.9|48.14.10","40":"11.11.16|17.3.28"}},{"v":["Слово, яке було від Господа до Єремії у десятий рік Седекії, царя Юдейського; цей рік був вісімнадцятим роком Навуходоносора.","Тоді військо царя Вавилонського облягало Єрусалим, і Єремія пророк був ув’язнений у дворі сторожі, який був при домі царя Юдейського.","Седекія, цар Юдейський, ув’язнив його туди, сказавши: «навіщо ти пророкуєш і говориш: так говорить Господь: ось, Я віддаю місто це у руки царя Вавилонського, і він візьме його;","і Седекія, цар Юдейський, не уникне рук халдеїв, але неодмінно відданий буде у руки царя Вавилонського, і буде говорити з ним устами до вуст, і очі його побачать очі його;","і він відведе Седекію у Вавилон, де він і буде, доки не відвідаю його, — говорить Господь. Якщо ви будете воювати з халдеями, то не будете мати успіху?»","І сказав Єремія: таке було до мене слово Господнє:","ось Анамеїл, син Саллума, дядька твого, йде до тебе сказати: «купи собі поле моє, яке в Анафофі, тому що за правом родинним тобі слід купити його».","Й Анамеїл, син дядька мого, прийшов до мене, за словом Господнім, у двір сторо́жі і сказав мені: «купи поле моє, яке в Анафофі, у землі Веніаміновій, тому що право спадщини твоє і право викупу твоє; купи собі». Тоді я дізнався, що це було слово Господнє.","І купив я поле в Анамеїла, сина дядька мого, яке в Анафофі, і відважив йому сім сиклів срібла і десять срібників;","і записав у книгу і запечатав її, і запросив для цього свідків і відважив срібло на терезах.","І взяв я купчий запис, як запечатаний за законом і уставом, так і відкритий;","і віддав цей купчий запис Варуху, синові Нирії, сина Маасеї, на очах Анамеїла, сина дядька мого, і на очах свідків, які підписали цей купчий запис, на очах усіх юдеїв, які сиділи на дворі сторо́жі;","і заповів Варуху в присутності їх:","так говорить Господь Саваоф, Бог Ізраїлів: візьми ці записи, цей купчий запис, який запечатаний, і цей запис відкритий, і поклади їх у глиняну посудину, щоб вони залишалися там багато днів.","Бо так говорить Господь Саваоф, Бог Ізраїлів: доми і поля і виноградники будуть знову купуватися у землі цій.","І, передавши купчий запис Варуху, синові Нирії, я помолився Господу:","«о, Господи Боже! Ти створив небо і землю великою силою Твоєю і простягнутою правицею; для Тебе нічого немає неможливого;","Ти являєш милість тисячам і за беззаконня батьків відплачуєш у надро дітям їхнім після них: Боже великий, сильний, Якому ім’я Господь Саваоф!","Великий у раді і сильний у ділах, Якого очі відкриті на усі путі синів людських, щоб відплачувати кожному за путями його і за плодами діл його,","Який звершив чудеса і знамення у землі Єгипетській, і звершуєш до цього дня і в Ізраїлі і між усіма людьми, і сотворив Собі ім’я, як у цей день,","і вивів народ Твій Ізраїля із землі Єгипетської знаменнями і чудесами, і рукою сильною і правицею простягнутою, при великому жаху,","і дав їм землю цю, яку дати їм клятвено обіцяв батькам їхнім, землю, яка тече молоком і медом.","Вони ввійшли і заволоділи нею, але не стали слухати гласу Твого і не чинили за законом Твоїм, не стали робити того, що Ти заповів їм робити, і за те Ти навів на них усі ці біди.","Ось, насипи досягають міста, щоб узяти його; і місто від меча і голоду і моровиці віддається у руки халдеїв, які воюють проти нього; що Ти говорив, те і сповнюється, і ось, Ти бачиш це.","А Ти, Господи Боже, сказав мені: «купи собі поле за срібло і запроси свідків», тоді як місто віддається у руки халдеїв».","І було слово Господнє до Єремії:","ось, Я Господь, Бог усякої плоті; чи є щось неможливе для Мене?","Тому так говорить Господь: ось, Я віддаю місто це до рук халдеїв і до рук Навуходоносора, царя Вавилонського, і він візьме його,","і ввійдуть халдеї, які облягають це місто, запалять місто вогнем і спалять його і доми, на покрівлях яких підносилися куріння Ваалу і були узливання чужим богам, щоб прогнівляти Мене.","Бо сини Ізраїлеві й сини Іудині тільки зло робили перед очима Моїми від юности своєї; сини Ізраїлеві тільки прогнівляли Мене ділами рук своїх, — говорить Господь.","І ніби для гніву Мого і люті Моєї існувало місто це від самого дня побудови його до цього дня, щоб Я відкинув його від лиця Мого","за усе зло синів Ізраїля і синів Іуди, яке вони для прогнівлення Мене робили, вони, царі їхні, князі їхні, священики їхні й пророки їхні, й мужі Іуди і жителі Єрусалима.","Вони повернулися до Мене спиною, а не лицем; і коли Я навчав їх, з раннього ранку навчав, вони не хотіли прийняти настановлення,","і в домі, над яким наречене ім’я Моє, поставили мерзоти свої, осквернили його.","Влаштували капища Ваалу в долині синів Енномових, щоб проводити через вогонь синів своїх і дочок своїх на честь Молоха, чого Я не повелівав їм, і Мені на розум не спадало, щоб вони робили цю мерзоту, вводячи у гріх Іуду.","І однак же нині так говорить Господь, Бог Ізраїлів, про це місто, про яке ви говорите: «воно віддається у руки царя Вавилонського мечем і голодом і моровицею», —","ось, Я зберу їх з усіх країн, в які вигнав їх у гніві Моєму й у люті Моїй і у великому обуренні, і поверну їх на місце це і дам їм безпечне життя.","Вони будуть Моїм народом, а Я буду їм Богом.","І дам їм одне серце й одну путь, щоб боялися Мене в усі дні життя, для блага свого і блага дітей своїх після них.","І укладу з ними вічний завіт, за яким Я не відвернуся від них, щоб благодіяти їм, і страх Мій вкладу у серця їхні, щоб вони не відступали від Мене.","І буду радіти за них, благодіючи їм, і насаджу їх на землі цій твердо, від усього серця Мого і від усієї душі Моєї.","Бо так говорить Господь: як Я навів на народ цей усе це велике зло, так наведу на них усе благо, яке Я вирік про них.","І будуть купувати поля у землі цій, про яку ви говорите: «це пустеля, без людей і без худоби; вона віддана у руки халдеям»;","будуть купувати поля за срібло і вносити у записи, і запечатувати і запрошувати свідків — у землі Веніаміновій і в околицях Єрусалима, і в містах Іуди й у містах нагірних, і в містах низинних і у містах південних; бо поверну полон їх, — говорить Господь."],"x":{"2":"32.33.1","3":"32.21.7|32.27.6","4":"32.34.3","5":"36.17.12|32.52.11|31.24.19","7":"50.27.9|2.25.25","8":"32.1.1","12":"32.36.4","15":"32.32.44","17":"32.27.5|32.32.27","18":"1.34.7|4.5.10","19":"25.61.13|26.24.12|36.33.20|50.16.27|62.2.6|32.16.17","20":"1.4.6-7","21":"1.6.6|9.7.23","22":"0.12.7|1.13.5","27":"3.16.22","29":"32.11.17","30":"0.8.21","33":"32.2.27|32.18.17","34":"4.12.11|11.21.4|13.33.4-5","35":"2.18.21|11.21.6","37":"4.30.3|32.12.14-15","38":"32.24.7","39":"36.11.19|36.36.26","40":"32.31.31:33|62.11.27","41":"4.30.9|32.24.6|0.9.15","42":"32.31.28","43":"32.33.10","44":"32.17.26|32.29.14|32.30.3|32.31.23"}},{"v":["І було слово Господнє до Єремії вдруге, коли він ще утримувався у дворі сторо́жі:","Так говорить Господь, Який створив [землю], Господь, Який упорядкував і утвердив її, — Господь ім’я Йому:","взивай до Мене — і Я відповім тобі, покажу тобі велике і недоступне, чого ти не знаєш.","Бо так говорить Господь, Бог Ізраїлів, про доми міста цього і про доми царів юдейських, які руйнуються для завалів і для битви","тими, які прийшли воювати з халдеями, щоб наповнити доми трупами людей, яких Я уражу у гніві Моєму й у люті Моїй, і за всі беззаконня яких Я сховав лице Моє від міста цього.","Ось, Я прикладу йому пластир і цілющі засоби, і вилікую їх, і відкрию їм повноту миру й істини,","і поверну полон Іуди і полон Ізраїля і влаштую їх, як спочатку,","і очищу їх від усього нечестя їхнього, яким вони грішили переді Мною, і прощу всі беззаконня їхні, якими вони грішили переді Мною і відпали від Мене.","І буде для мене Єрусалим радісним ім’ям, похвалою і честю перед усіма народами землі, які почують про усі блага, які Я зроблю йому, і здивуються і затремтять від усіх благодіянь і всього благоденства, яке Я доставлю йому.","Так говорить Господь: на цьому місці, про яке ви говорите: «воно порожнє, без людей і без худоби», — у містах юдейських і на вулицях Єрусалима, які порожні, без людей, без жителів, без худоби,","знову буде чутно голос радости і голос веселощів, голос нареченого і голос нареченої, голос тих, що говорять: «славте Господа Саваофа, бо благий Господь, бо повік милість Його», і голос тих, що приносять жертву подяки в домі Господньому; бо Я поверну полонених цієї землі в попередній стан, — говорить Господь.","Так говорить Господь Саваоф: на цьому місці, яке порожнє, без людей, без худоби, й у всіх містах його знову будуть оселі пастухів, які будуть пасти стада.","У містах нагірних, у містах низинних і в містах південних, і в землі Веніаміновій, і в околицях Єрусалима, і в містах Іуди знову будуть проходити стада під рукою того, який рахує, — говорить Господь.","Ось, настануть дні, — говорить Господь, — коли Я виконаю те добре слово, яке вирік про дім Ізраїлів і про дім Іудин.","У ті дні й у той час вирощу Давиду Паросток праведний, і буде чинити суд і правду на землі.","У ті дні Іуда буде спасенний і Єрусалим буде жити безпечно, і наречуть ім’я Йому: «Господь виправдання наше!»","Бо так говорить Господь: не припиниться у Давида муж, який сидить на престолі дому Ізраїлевого,","й у священиків-левитів не буде нестачі у мужі перед лицем Моїм, який в усі дні возносить всепалення і спалює приношення і звершує жертви.","І було слово Господнє до Єремії:","так говорить Господь: якщо можете зруйнувати завіт Мій про день і завіт Мій про ніч, щоб день і ніч не приходили у свій час,","то може бути зруйнований і завіт Мій з рабом Моїм Давидом, так що не буде у нього сина, який царює на престолі його, і також з левитами-священиками, служителями Моїми.","Як незліченне небесне воїнство і невимірний пісок морський, так розмножу плем’я Давида, раба Мого, і левитів, які служать Мені.","І було слово Господнє до Єремії:","чи не бачиш, що народ цей говорить: «ті два племені, які обрав Господь, Він відкинув?» і через це вони зневажають народ Мій, ніби він уже не був народом у очах їх.","Так говорить Господь: якщо завіту Мого про день і ніч і уставів неба і землі Я не утвердив,","то і плем’я Якова і Давида, раба Мого, відкину, щоб не брати більше владик з його племені для племені Авраама, Ісаака та Якова; бо поверну їх із полону і помилую їх."],"x":{"1":"32.32.2","2":"1.15.3|25.82.19","4":"32.22.10","5":"4.31.17","6":"32.30.17","7":"32.29.14|32.30.3|32.31.4","8":"32.31.34","9":"4.26.19","10":"32.32.43","11":"25.135.1","14":"32.23.5","15":"31.11.1|32.23.5","16":"4.33.28|32.23.6","17":"31.11.1|52.1.32","18":"56.2.5|31.61.6|49.3.3","20":"32.31.37","22":"0.15.5|0.22.17|0.28.14","25":"32.31.36|32.33.20","26":"25.125.1|32.31.20|36.39.25"}},{"v":["Слово, яке було до Єремії від Господа, коли Навуходоносор, цар Вавилонський, і все військо його і всі царства землі, підвладні руці його, і всі народи воювали проти Єрусалима і проти усіх міст його:","так говорить Господь, Бог Ізраїлів: йди і скажи Седекії, царю Юдейському, і скажи йому: так говорить Господь: ось, Я віддаю місто це у руки царя Вавилонського, і він спалить його вогнем;","і ти не уникнеш руки його, але неодмінно будеш узятий і відданий у руки його, і очі твої побачать очі царя Вавилонського, і вуста його будуть говорити до твоїх вуст, і підеш у Вавилон.","Утім, слухай слово Господнє, Седекіє, царю Юдейський! так говорить Господь про тебе: ти не помреш від меча;","ти помреш у мирі, і як для батьків твоїх, попередніх царів, які були раніше тебе, спалювали при похованні пахощі, так спалять і для тебе й оплачуть тебе: «горе, государю!», бо Я вирік це слово, — говорить Господь.","Єремія пророк усі слова ці переказав Седекії, царю Юдейському, в Єрусалимі.","Тим часом військо царя Вавилонського воювало проти Єрусалима і проти усіх міст юдейських, які ще залишалися, проти Лахиса й Азеки; бо з міст юдейських тільки ці залишалися, як міста укріплені.","Слово, яке було до Єремії від Господа після того, як цар Седекія уклав завіт з усім народом, який був у Єрусалимі, щоб оголосити свободу,","щоб кожен відпустив на волю раба свого і рабиню свою, єврея та єврейку, щоб ніхто з них не тримав у рабстві юдея, брата свого.","І послухалися усі князі і весь народ, які вступили у завіт, щоб відпустити кожному раба свого і кожному рабиню свою на волю, щоб не тримати їх надалі у рабах, — і послухалися і відпустили;","але після того, роздумавши, стали брати назад рабів і рабинь, яких відпустили на волю, і примусили їх бути рабами і рабинями.","І було слово Господнє до Єремії від Господа:","так говорить Господь, Бог Ізраїлів: Я уклав завіт з батьками вашими, коли вивів їх із землі Єгипетської, з дому рабства, і сказав:","«наприкінці сьомого року відпускайте кожен брата свого, єврея, який продав себе тобі; нехай він працює на тебе шість років, а потім відпусти його від себе на волю»; але батьки ваші не послухали Мене і не прихилили вуха свого.","Ви нині навернулися і зробили справедливо перед очима Моїми, оголосивши кожен волю ближньому своєму, й уклали переді Мною завіт у домі, над яким наречене ім’я Моє;","але потім роздумали і знеславили ім’я Моє, і повернули до себе кожен раба свого і кожен рабиню свою, яких відпустили на волю, куди душі їх завгодно, і примушуєте їх бути у вас рабами і рабинями.","Тому так говорить Господь: ви не послухалися Мене у тому, щоб кожен оголосив волю братові своєму і ближньому своєму; за те ось Я, — говорить Господь, — проголошую вам свободу піддатися мечу, моровиці й голоду, і віддам вас на озлоблення в усі царства землі;","і віддам тих, що переступили завіт Мій і не устояли у словах завіту, який вони уклали перед лицем Моїм, розсікши тельця надвоє і пройшовши між розсіченими частинами його,","князів юдейських і князів єрусалимських, євнухів і священиків і увесь народ землі, який проходив між розсіченими частинами тельця, —","віддам їх до рук ворогів їхніх і до рук тих, що шукають душí їх, і трупи їхні будуть споживою птахам небесним і звірам земним.","І Седекію, царя Юдейського, і князів його віддам до рук ворогів їхніх і до рук тих, що шукають душí їх, і до рук війська царя Вавилонського, яке відступило від вас.","Ось, Я дам повеління, — говорить Господь, — і поверну їх до цього міста, і вони нападуть на нього, і візьмуть його, і спалять його вогнем, і міста Юдеї зроблю пустелею безлюдною."],"x":{"1":"11.25.1","2":"32.21.7","3":"32.32.4|36.17.16","5":"32.22.18","7":"43.1.13","9":"1.21.2|2.25.39|4.15.12","13":"1.21.2|4.15.12","14":"32.7.24|32.25.4|32.35.15","17":"4.28.64","18":"0.15.10","20":"32.7.33"}},{"v":["Слово, яке було до Єремії від Господа у дні Іоакима, сина Іосії, царя Юдейського:","йди у дім Рехавитів і поговори з ними, і приведи їх у дім Господній, в одну з кімнат, і дай їм пити вина.","Я взяв Іазанію, сина Єремії, сина Авацинії, і братів його, і всіх синів його і весь дім Рехавитів,","і привів їх у дім Господній, в кімнату синів Анана, сина Годолії, людини Божої, яка поряд з кімнатою князів, над кімнатою Маасеї, сина Селлумового, стража біля входу;","і поставив перед синами дому Рехавитів повні чаші вина і склянки і сказав їм: пийте вино.","Але вони сказали: ми вина не п’ємо; тому що Іонадав, син Рехава, батько наш, дав нам заповідь, сказавши: «не пийте вина ні ви, ні діти ваші, повіки;","і домів не будуйте, і насіння не сійте, і виноградників не розводьте, і не майте їх, але живіть у наметах в усі дні життя вашого, щоб вам довгий час прожити на тій землі, де ви подорожніми».","І ми послухалися голосу Іонадава, сина Рехавового, батька нашого, в усьому, що він заповів нам, щоб не пити вина в усі дні наші, — ми і дружини наші, і сини наші і дочки наші, —","і щоб не будувати домів для проживання нашого; і в нас немає ні виноградників, ні полів, ні посіву;","а живемо в наметах і в усьому слухаємося і робимо все, що заповів нам Іонадав, батько наш.","Коли ж Навуходоносор, цар Вавилонський, прийшов у землю цю, ми сказали: «вийдемо, підемо в Єрусалим від війська халдеїв і від війська арамеїв», і ось, ми живемо в Єрусалимі.","І було слово Господнє до Єремії:","так говорить Господь Саваоф, Бог Ізраїлів: іди і скажи мужам Іуди і жителям Єрусалима: невже ви не візьмете з цього настановлення для себе, щоб слухатися слів Моїх? — говорить Господь.","Слова Іонадава, сина Рехавового, який заповів синам своїм не пити вина, виконуються, і вони не п’ють до цього дня, тому що слухаються заповіту батька свого; а Я безперестанно говорив вам, говорив з раннього ранку, і ви не послухалися Мене.","Я посилав до вас усіх рабів Моїх, пророків, посилав з раннього ранку, і говорив: «наверніться кожен від злого шляху свого і виправте поведінку вашу, і не ходіть слідом інших богів, щоб служити їм; і будете жити на цій землі, яку Я дав вам і батькам вашим»; але ви не прихилили вуха свого і не послухалися Мене.","Оскільки сини Іонадава, сина Рехавового, виконують заповідь батька свого, яку він заповів їм, а народ цей не слухає Мене,","тому так говорить Господь Бог Саваоф, Бог Ізраїлів: ось, Я наведу на юдеїв і на усіх жителів Єрусалима усе те зло, яке Я вирік на них, тому що Я говорив їм, а вони не слухалися, кликав їх, а вони не відповідали.","А дому Рехавитів сказав Єремія: так говорить Господь Саваоф, Бог Ізраїлів: за те, що ви послухалися заповіту Іонадава, батька вашого, і зберігаєте усі заповіді його і в усьому чините, як він заповів вам, —","за те, так говорить Господь Саваоф, Бог Ізраїлів: не відніметься в Іонадава, сина Рехавового, муж, який стоїть перед лицем Моїм в усі дні."],"x":{"2":"12.2.55","4":"14.10.6","6":"11.10.15:23","14":"32.7.13","15":"32.7.3|32.18.11|42.3.8","17":"31.65.12|31.66.4","19":"32.33.17"}},{"v":["У четвертий рік Іоакима, сина Іосії, царя Юдейського, було таке слово до Єремії від Господа:","візьми собі книжковий сувій і напиши у ньому усі слова, які Я говорив тобі про Ізраїля і про Іуду і про усі народи з того дня, як Я почав говорити тобі, від днів Іосії до цього дня;","можливо, дім Іудин почує про усі біди, які Я думаю зробити їм, щоб вони навернулися кожен від злого шляху свого, щоб Я простив неправду їх і гріх їх.","І покликав Єремія Варуха, сина Нирії, і написав Варух у книжковий сувій з уст Єремії всі слова Господа, які Він говорив йому.","І наказав Єремія Варуху і сказав: я ув’язнений і не можу йти у дім Господній;","отже, йди ти і прочитай написані тобою в сувої з уст моїх слова Господні вголос народу у домі Господньому у день посту, також і вголос усім юдеям, які прийшли із міст своїх, прочитай їх;","можливо, вони піднесуть смиренне моління перед лице Господа і навернуться кожен від злого шляху свого; бо великий гнів і обурення, яке оголосив Господь на народ цей.","Варух, син Нирії, зробив усе, що наказав йому пророк Єремія, щоб слова Господні, написані у сувої, прочитати у домі Господньому.","У п’ятий рік Іоакима, сина Іосії, царя Юдейського, у дев’ятому місяці оголосили піст перед лицем Господа усьому народу в Єрусалимі і всьому народу, який прийшов до Єрусалима з міст юдейських.","І прочитав Варух написані у сувої слова Єремії у домі Господньому, в кімнаті Гемарії, сина Сафанового, писаря, на верхньому дворі, біля входу у нові ворота дому Господнього, вголос усьому народу.","Михей, син Гемарії, сина Сафанового, чув усі слова Господні, написані у сувої,","і зійшов у дім царя, у кімнату царського писаря, і ось, там сиділи усі князі: Елисам, царський писар, і Делаія, син Семаії, й Елнафан, син Ахбора, і Гемарія, син Сафана, і Седекія, син Ананії, і всі князі;","і переказав їм Михей усі слова, які він чув, коли Варух читав сувій уголос народу.","Тоді всі князі послали до Варуха Ієгудія, сина Нафанії, сина Селемії, сина Хусії, сказати йому: сувій, який ти читав уголос народу, візьми у руку твою і прийди. І взяв Варух, син Нирії, сувій у руку свою і прийшов до них.","Вони сказали йому: сядь, і прочитай нам уголос. І прочитав Варух уголос їм.","Коли вони вислухали усі слова, то з жахом подивилися один на одного і сказали Варуху: ми неодмінно перекажемо усі ці слова царю.","І запитали Варуха: скажи ж нам, як ти написав усі слова ці з уст його?","І сказав їм Варух: він промовляв мені вустами своїми усі ці слова, а я чорнилом писав їх у цей сувій.","Тоді сказали князі Варуху: піди, сховайся, ти і Єремія, щоб ніхто не знав, де ви.","І пішли вони до царя у палац, а сувій залишили у кімнаті Елисама, царського писаря, і переказали вголос царю всі слова ці.","Цар послав Ієгудія принести сувій, і він узяв його з кімнати Елисама, царського писаря; і читав його Ієгудій уголос царю і уголос усім князям, які стояли поруч царя.","Цар у той час, у дев’ятому місяці, сидів у зимовому домі, і перед ним горіла жаровня.","Коли Ієгудій прочитував три або чотири стовпці, цар відрізував їх писарським ножичком і кидав на вогонь у жаровню, доки не знищений був весь сувій у вогні, який був у жаровні.","І не убоялись, і не роздерли одяг свій ні цар, ні всі слуги його, які чули усі слова ці.","Хоч Елнафан і Делаія і Гемарія умовляли царя не спалювати сувій, але він не послухав їх.","І наказав цар Ієрамеїлу, синові царя, і Сераії, синові Азриїловому, і Селемії, синові Авдиїловому, взяти Варуха писаря і Єремію пророка; але Господь сховав їх.","І було слово Господнє до Єремії, після того як цар спалив сувій і слова, які Варух написав з уст Єремії, і сказано йому:","візьми собі знову інший сувій і напиши у ньому всі попередні слова, які були у першому сувої, які спалив Іоаким, цар Юдейський;","а царю Юдейському Іоакиму скажи: так говорить Господь: ти спалив сувій цей, сказавши: «навіщо ти написав у ньому: неодмінно прийде цар Вавилонський і розорить землю цю, і знищить на ній людей і худобу?»","за це, так говорить Господь про Іоакима, царя Юдейського: не буде від нього того, хто сидить на престолі Давидовому, і труп його буде кинутий на спеку денну і на холод нічний;","і відвідаю його і плем’я його і слуг його за неправду їх, і наведу на них і на жителів Єрусалима і на мужів Іуди усе зло, яке Я вирік на них, а вони не слухали.","І взяв Єремія інший сувій і віддав його Варуху писарю, синові Нирії, і він написав у ньому з уст Єремії усі слова того сувою, який спалив Іоаким, цар Юдейський, на вогні; і ще додано до них багато подібних до тих слів."],"x":{"2":"32.30.2|32.51.60","3":"32.26.3|36.12.3","4":"32.45.1","7":"35.1.5","10":"32.26.10","23":"13.36.16","29":"32.32.43|32.33.10","30":"32.22.19"}},{"v":["Замість Ієхонії, сина Іоакима, царював Седекія, син Іосії, якого Навуходоносор, цар Вавилонський, поставив царем у землі Юдейській.","Ні він, ні слуги його, ні народ країни не слухали слів Господа, які говорив Він через Єремію пророка.","Цар Седекія послав Ієгухала, сина Селемії, і Софонію, сина Маасеї, священика, до Єремії пророка сказати: помолися за нас Господу Богу нашому.","Єремія тоді ще вільно входив і виходив серед народу, тому що не ув’язнили його у дім в’язничний.","Тим часом військо фараонове виступило з Єгипту, і халдеї, які облягали Єрусалим, почувши звістку про те, відступили від Єрусалима.","І було слово Господнє до Єремії пророка:","так говорить Господь, Бог Ізраїлів: так скажіть цареві Юдейському, який послав вас до Мене запитати Мене: ось, військо фараонове, яке йшло до вас на допомогу, повернеться у землю свою, у Єгипет;","а халдеї знову прийдуть і будуть воювати проти міста цього, і візьмуть його і спалять його вогнем.","Так говорить Господь: не обманюйте себе, говорячи: «неодмінно відійдуть від нас халдеї», бо вони не відійдуть;","якби ви навіть розбили усе військо халдеїв, які воюють проти вас, і залишилися б у них тільки поранені, то і ті встали б, кожен з намету свого, і спалили б місто це вогнем.","У той час, як військо халдейське відступило від Єрусалима, з причини війська фараонового,","Єремія пішов з Єрусалима, щоб іти у землю Веніамінову, ховаючись там серед народу.","Але коли він був біля воріт Веніамінових, начальник сторожі, який був там, на ім’я Іреія, син Селемії, сина Ананієвого, затримав Єремію пророка, сказавши: ти хочеш перебігти до халдеїв?","Єремія сказав: це неправда; я не хочу перебігти до халдеїв. Але він не послухав його, і взяв Іреія Єремію і привів його до князів.","Князі озлобилися на Єремію і били його, і замкнули його у в’язницю, у дім Іонафана писаря, тому що зробили його в’язницею.","Коли Єремія увійшов у в’язницю і підвал, і пробув там Єремія багато днів, —","цар Седекія послав і взяв його. І запитував його цар у домі своєму таємно і сказав: чи немає слова від Господа? Єремія сказав: є; і сказав: ти будеш відданий до рук царя Вавилонського.","І сказав Єремія царю Седекії: чим я згрішив перед тобою і перед слугами твоїми, і перед народом цим, що ви посадили мене у в’язницю?","і де ваші пророки, які пророкували вам, говорячи: «цар Вавилонський не піде проти вас і проти землі цієї»?","І нині послухай, господарю мій царю, нехай упаде прохання моє перед лицем твоїм; не повертай мене у дім Іонафана писаря, щоб мені не померти там.","І дав повеління цар Седекія, щоб ув’язнили Єремію у дворі сторо́жі і давали йому по шматку хліба на день з вулиці хлібопекарів, доки не закінчився весь хліб у місті; і так залишався Єремія у дворі сторо́жі."],"x":{"1":"11.24.17|13.36.10","2":"13.36.12","3":"31.37.4","5":"32.34.21","7":"31.30.2|33.4.17","15":"32.20.2"}},{"v":["І почули Сафатія, син Матфана, і Годолія, син Пасхора, і Юхал, син Селемії, і Пасхор, син Малхії, слова, які Єремія промовив до всього народу, говорячи:","так говорить Господь: хто залишиться у цьому місті, помре від меча, голоду і моровиці; а хто вийде до халдеїв, буде живий, і душа його буде йому замість здобичі, і він залишиться живий.","Так говорить Господь: неодмінно віддане буде місто це в руки війська царя Вавилонського, і він візьме його.","Тоді князі сказали цареві: нехай буде цей чоловік відданий на смерть, тому що він ослаблює руки воїнів, які залишаються у цьому місті, і руки усього народу, говорячи до них такі слова; бо цей чоловік не благоденства бажає народу цьому, а біди.","І сказав цар Седекія: ось, він у ваших руках, тому що цар нічого не може зробити всупереч вам.","Тоді взяли Єремію і кинули його в яму Малхії, сина царя, що була у дворі сторо́жі, й опустили Єремію на мотузках; у ямі тій не було води, а тільки багно, і занурився Єремія у багно.","І почув Авдемелех ефіоплянин, один з євнухів, який знаходився у царському домі, що Єремію посадили в яму; а цар сидів тоді біля воріт Веніамінових.","І вийшов Авдемелех з дому царського і сказав цареві:","господарю мій царю! зле зробили ці люди, так учинивши з Єремією пророком, якого кинули в яму; він помре там від голоду, тому що немає більше хліба у місті.","Цар дав наказ Авдемелеху ефіоплянину, сказавши: візьми із собою звідси тридцять чоловік і витягни Єремію пророка з ями, доки він не помер.","Авдемелех узяв людей із собою і ввійшов у дім царський під комору, і взяв звідти старих негодящих ганчірок і старих негодящих клаптів і опустив їх на мотузках у яму до Єремії.","І сказав Авдемелех ефіоплянин Єремії: підклади ці старі кинуті ганчірки і клапті під пахви рук твоїх, під мотузки. І зробив так Єремія.","І потягли Єремію на мотузках і витягли його з ями; і залишався Єремія у дворі сторо́жі.","Тоді цар Седекія послав і покликав Єремію пророка до себе, при третьому вході у дім Господній, і сказав цар Єремії: я у тебе запитаю щось; не приховай від мене нічого.","І сказав Єремія Седекії: якщо я відкрию тобі, чи не віддаси ти мене на смерть? і якщо дам тобі пораду, ти не послухаєш мене.","І клявся цар Седекія Єремії таємно, говорячи: живий Господь, Який створив нам душу цю, не віддам тебе на смерть і не віддам до рук цих людей, які шукають душі твоєї.","Тоді Єремія сказав Седекії: так говорить Господь Бог Саваоф, Бог Ізраїлів: якщо ти вийдеш до князів царя Вавилонського, то жива буде душа твоя, і це місто не буде спалене вогнем, і ти будеш живий, і дім твій;","а якщо не вийдеш до князів царя Вавилонського, то це місто буде віддане до рук халдеїв, і вони спалять його вогнем, і ти не уникнеш рук їхніх.","І сказав цар Седекія Єремії: я боюся юдеїв, які перейшли до халдеїв, щоб халдеї не віддали мене у руки їх, і щоб ті не наглумилися з мене.","І сказав Єремія: не віддадуть; послухай гласу Господа у тім, що я говорю тобі, і добре тобі буде, і жива буде душа твоя.","А якщо ти не захочеш вийти, то ось слово, яке відкрив мені Господь:","ось, усі дружини, які залишилися у домі царя Юдейського, відведені будуть до князів царя Вавилонського, і скажуть вони: «тебе звабили і перемогли друзі твої; ноги твої занурилися у багно, і вони віддалилися від тебе».","І всіх дружин твоїх і дітей твоїх відведуть до халдеїв, і ти не уникнеш рук їхніх; але будеш узятий рукою царя Вавилонського, і зробиш те, що місто це буде спалене вогнем.","І сказав Седекія Єремії: ніхто не повинен знати цих слів, і тоді ти не помреш;","і якщо почують князі, що я розмовляв з тобою, і прийдуть до тебе, і скажуть тобі: «скажи нам, що говорив ти царю, не приховай від нас, і ми не віддамо тебе на смерть, — і також що говорив тобі цар»,","то скажи їм: «я склав перед лицем царя прохання моє, щоб не повертати мене у дім Іонафана, щоб не померти там».","І прийшли усі князі до Єремії і запитували його, і він сказав їм згідно з усіма словами, які цар повелів сказати, і вони мовчки залишили його, тому що не довідалися про те, що було сказано цареві.","І залишався Єремія у дворі сторо́жі до того дня, в який був узятий Єрусалим. І Єрусалим був узятий."],"x":{"2":"32.21.9|32.39.18|32.45.5","3":"13.36.12|32.34.2","4":"52.23.2|40.7.10","7":"32.39.16","18":"32.34.2","20":"13.36.12","22":"31.3.12","23":"11.25.6|32.32.4"}},{"v":["У дев’ятий рік Седекії, царя Юдейського, у десятий місяць, прийшов Навуходоносор, цар Вавилонський, з усім військом своїм до Єрусалима, і обложили його.","А в одинадцятий рік Седекії, у четвертий місяць, у дев’ятий день місяця місто було взяте.","І ввійшли у нього всі князі царя Вавилонського, і розташувалися в середніх воротах, Нергал-Шарецер, Самгар-Нево, Сарсехим, начальник євнухів, Нергал-Шарецер, начальник магів, і всі інші князі царя Вавилонського.","Коли Седекія, цар Юдейський, і всі військові люди побачили їх, — побігли, і вночі вийшли з міста через царський сад у ворота між двома стінами і пішли по дорозі рівнини.","Але військо халдейське погналося за ними; і наздогнали Седекію на рівнинах єрихонських; і взяли його і відвели до Навуходоносора, царя Вавилонського, у Ривлу, у землю Емаф, де він промовив суд над ним.","І заколов цар Вавилонський синів Седекії в Ривлі перед його очима, й усіх вельмож юдейських заколов цар Вавилонський;","а Седекії виколов очі і закував його у кайдани, щоб відвести його у Вавилон.","Дім царя і доми народу спалили халдеї вогнем, і стіни Єрусалима зруйнували.","А залишок народу, який залишався в місті, і перебіжчиків, які перейшли до нього, й інший народ, який залишився, Навузардан, начальник охоронців, переселив у Вавилон.","Бідних же з народу, які нічого не мали, Навузардан, начальник охоронців, залишив у Юдейській землі і дав їм тоді ж виноградники і поля.","А про Єремію Навуходоносор, цар Вавилонський, дав таке повеління Навузардану, начальникові охоронців:","візьми його і май його на увазі, і не роби йому нічого поганого, але чини з ним так, як він скаже тобі.","І послав Навузардан, начальник охоронців, і Навузазван, начальник євнухів, і Нергал-Шарецер, начальник магів, і всі князі царя Вавилонського","послали і взяли Єремію з двору сторо́жі, і доручили його Годолії, синові Ахикама, сина Сафанового, відвести його додому. І він залишився жити серед народу.","До Єремії, коли він ще утримувався у дворі в’язничному, було слово Господнє:","йди, скажи Авдемелеху ефіоплянину: так говорить Господь Саваоф, Бог Ізраїлів: ось, Я виконаю слова Мої про місто це на зло, а не на добро йому, і вони збудуться у той день перед очима твоїми;","але тебе Я визволю у той день, — говорить Господь, — і не будеш відданий до рук людей, яких ти боїшся.","Я визволю тебе, і ти не впадеш від меча, і душа твоя залишиться у тобі замість здобичі, тому що ти на Мене поклав уповання, — сказав Господь."],"x":{"1":"11.25.1|32.52.4","5":"32.32.4","6":"46.1.8","7":"11.25.7","8":"11.25.9|36.12.13","10":"11.25.12","14":"32.26.24","16":"32.38.7","18":"32.21.9|32.38.2"}},{"v":["Слово, яке було до Єремії від Господа, після того як Навузардан, начальник охоронців, відпустив його з Рами, де він узяв його скутого ланцюгами серед інших полонених єрусалимлян і юдеїв, яких переселяли у Вавилон.","Начальник охоронців узяв Єремію і сказав йому: Господь Бог твій прорік цю біду на місце це,","і навів його Господь і зробив те, що сказав; тому що ви згрішили перед Господом і не слухалися гласу Його, за те й спіткало вас це.","Отже, ось, я звільняю тебе сьогодні від ланцюгів, які на руках твоїх: якщо тобі угодно йти зі мною у Вавилон, іди, і я буду мати піклування про тебе; а якщо неугодно тобі йти зі мною у Вавилон, залишайся. Ось, уся земля перед тобою; куди тобі завгодно, і куди подобається йти, туди і йди.","Коли він ще не відійшов, сказав Навузардан: піди до Годолії, сина Ахикама, сина Сафанового, якого цар Вавилонський поставив начальником над містами юдейськими, і залишайся з ним серед народу; або йди, куди подобається тобі йти. І дав йому начальник охоронців продовольство і подарунок і відпустив його.","І прийшов Єремія до Годолії, сина Ахикама, у Массифу, і жив з ним серед народу, який залишався у країні.","Коли усі воєначальники, які були у полі, вони і люди їхні, почули, що цар Вавилонський поставив Годолію, сина Ахикама, начальником над країною і доручив йому чоловіків і жінок, і дітей, і тих із бідних країни, які не були переселені у Вавилон;","тоді прийшли до Годолії у Массифу й Ісмаїл, син Нафанії, й Іоанан та Іонафан, сини Карея, і Сераія, син Фанасмефа, і сини Офи із Нетофафи, й Ієзонія, син Махафи, вони і дружини їхні.","Годолія, син Ахикама, сина Сафанового, клявся їм і людям їхнім, говорячи: не бійтеся служити халдеям, залишайтеся на землі і служіть цареві Вавилонському, і буде вам добре;","а я залишуся у Массифі, щоб заступатися перед лицем халдеїв, які будуть приходити до нас; ви ж збирайте вино і літні плоди, й олію і забирайте у посудини ваші, і живіть у містах ваших, які зайняли.","Також усі юдеї, які знаходилися у землі Моавитській і між синами Аммона і в Ідумеї, і у всіх країнах, почули, що цар Вавилонський залишив частину юдеїв і поставив над ними Годолію, сина Ахикама, сина Сафанового;","і повернулися усі ці юдеї з усіх місць, куди були вигнані, і прийшли у землю Юдейську до Годолії в Массифу, і зібрали вина і літніх плодів дуже багато.","Тим часом Іоанан, син Карея, і всі військові начальники, які були у полі, прийшли до Годолії в Массифу","і сказали йому: чи знаєш ти, що Вааліс, цар синів Аммонових, надіслав Ісмаїла, сина Нафанії, щоб убити тебе? Але Годолія, син Ахикама, не повірив ім.","Тоді Іоанан, син Карея, сказав Годолії таємно у Массифі: дозволь мені, я піду й уб’ю Ісмаїла, сина Нафанії, і ніхто не довідається; навіщо допускати, щоб він убив тебе, і щоб усі юдеї, ті, які зібралися до тебе, розсіялися, і щоб загинув залишок Іуди?","Але Годолія, син Ахикама, сказав Іоанану, синові Карея: не роби цього, тому що ти неправду говориш про Ісмаїла."],"x":{"3":"32.50.7","5":"11.25.22","7":"11.25.22","9":"11.25.24","15":"9.16.9"}},{"v":["І було у сьомий місяць, Ісмаїл, син Нафанії, сина Елисама з племені царського, і вельможі царя і десять чоловік з ним прийшли до Годолії, сина Ахикама, у Массифу, і там вони їли разом хліб у Массифі.","І встав Ісмаїл, син Нафанії, і десять чоловік, які були з ним, й уразили Годолію, сина Ахикама, сина Сафанового, мечем і умертвили того, якого цар Вавилонський поставив начальником над країною.","Також убив Ісмаїл і всіх юдеїв, які були з ним, із Годолією, у Массифі, і халдеїв, які знаходилися там, людей військових.","На другий день після убивства Годолії, коли ніхто не знав про це,","прийшли із Сихема, Силома і Самарії вісімдесят чоловік з поголеними бородами й у розідраному одязі, і, зранивши себе, з дарами і ливаном у руках для приношення їх у дім Господній.","Ісмаїл, син Нафанії, вийшов з Массифи назустріч їм, ідучи і плачучи, і, зустрівшись з ними, сказав їм: ідіть до Годолії, сина Ахикама.","І як тільки вони увійшли всередину міста, Ісмаїл, син Нафанії, убив їх і кинув у рів, він і люди, які були з ним.","Але знайшлися між ними десять чоловік, які сказали Ісмаїлу: не умертвляй нас, бо у нас є в полі сховані комори з пшеницею і ячменем, і олією і медом. І він стримався і не умертвив їх з іншими братами їхніми.","Рів же, куди кинув Ісмаїл усі трупи людей, яких він убив через Годолію, був той самий, який зробив цар Аса, боячись Вааси, царя Ізраїльського; його наповнив Ісмаїл, син Нафанії, убитими.","І захопив Ісмаїл весь залишок народу, який був у Массифі, дочок царя і весь народ, що залишався у Массифі, який Навузардан, начальник охоронців, доручив Годолії, синові Ахикама, і захопив їх Ісмаїл, син Нафанії, і вирушив до синів Аммонових.","Але коли Іоанан, син Карея, і всі воєначальники, що були з ним, почули про усі злодіяння, які звершив Ісмаїл, син Нафанії,","узяли всіх людей і пішли воювати з Ісмаїлом, сином Нафанії, і наздогнали його біля великих вод, у Гаваоні.","І коли весь народ, який був у Ісмаїла, побачив Іоанана, сина Карея, і всіх воєначальників, що були з ним, зрадів;","і відвернувся весь народ, який Ісмаїл повів у полон з Массифи, і повернувся і пішов до Іоанана, сина Карея;","а Ісмаїл, син Нафанії, утік від Іоанана з вісьмома людьми і пішов до синів Аммонових.","Тоді Іоанан, син Карея, і всі воєначальники, що були з ним, узяли з Массифи весь народ, який залишився, який він визволив від Ісмаїла, сина Нафанії, після того як той убив Годолію, сина Ахикама, чоловіків, військових людей, і дружин, і дітей, і євнухів, яких він вивів з Гаваона;","і пішли, і зупинилися у селищі Химам, поблизу Вифлеєма, щоб відійти в Єгипет","від халдеїв, бо вони боялися їх, тому що Ісмаїл, син Нафанії, убив Годолію, сина Ахикама, якого цар Вавилонський поставив начальником над країною."],"x":{"2":"11.25.25","5":"2.19.27|4.14.1","7":"11.25.25","9":"10.15.22","17":"11.25.26"}},{"v":["І приступили усі воєначальники, й Іоанан, син Карея, й Ієзанія, син Гошаії, і весь народ від малого до великого,","і сказали Єремії пророку: нехай упаде перед лицем твоїм прохання наше, помолись за нас Господу Богу твоєму за весь цей залишок, бо з великого залишилося нас мало, як очі твої бачать нас,","щоб Господь, Бог твій, указав нам шлях, яким нам іти, і те, що нам робити.","І сказав їм Єремія пророк: чую, помолюся Господу Богу вашому за словами вашими, і все, що відповість вам Господь, оголошу вам, не приховаю від вас жодного слова.","Вони сказали Єремії: Господь нехай буде між нами свідком вірним та істинним у тім, що ми точно виконаємо усе те, з чим пошле тебе до нас Господь Бог Твій:","чи добре, чи погане те буде, але гласу Господа Бога нашого, до Якого посилаємо тебе, послухаємося, щоб нам було добре, коли будемо слухняні гласу Господа Бога нашого.","Коли минуло десять днів, було слово Господнє до Єремії.","Він покликав до себе Іоанана, сина Карея, й усіх воєначальників, що були з ним, і весь народ, від малого і до великого,","і сказав їм: так говорить Господь, Бог Ізраїлів, до Якого ви посилали мене, щоб скласти перед Ним моління ваше:","якщо залишитеся на землі цій, то Я влаштую вас і не розорю, насаджу вас і не викоріню, бо Я шкодую про ту біду, яку зробив вам.","Не бійтеся царя Вавилонського, якого ви боїтеся; не бійтеся його, — говорить Господь, — бо Я з вами, щоб спасати вас і визволяти вас від руки його.","І виявлю до вас милість, і він змилостивиться до вас і поверне вас у землю вашу.","Якщо ж ви скажете: «не хочемо жити у цій землі», і не послухаєтеся гласу Господа Бога вашого, говорячи:","«ні, ми підемо у землю Єгипетську, де війни не побачимо і трубного голосу не почуємо, і голодувати не будемо, і там будемо жити»;","то вислухайте нині слово Господнє, ви, залишок Іуди: так говорить Господь Саваоф, Бог Ізраїлів: якщо ви рішуче повернете лиця ваші, щоб іти в Єгипет, і підете, щоб жити там,","то меч, якого ви боїтеся, наздожене вас там, у землі Єгипетській, і голод, якого ви страхаєтеся, буде завжди йти за вами там, у Єгипті, і там помрете.","І всі, які повернуть лице своє, щоб іти в Єгипет і там жити, помруть від меча, голоду і моровиці, і жоден з них не залишиться і не уникне тієї біди, яку Я наведу на них.","Бо так говорить Господь Саваоф, Бог Ізраїлів: як вилився гнів Мій і лють Моя на жителів Єрусалима, так виллється лють Моя на вас, коли ввійдете в Єгипет, і ви будете прокляттям і жахом, і наругою і ганьбою, і не побачите більше місця цього.","До вас, залишок Іуди, вирік Господь: «не ходіть у Єгипет»; твердо знайте, що я нині застерігав вас,","бо ви згрішили проти себе самих: ви послали мене до Господа Бога нашого, сказавши: «помолися за нас Господу Богу нашому й усе, що скаже Господь Бог наш, оголоси нам, і ми зробимо».","Я оголосив вам нині; але ви не послухали гласу Господа Бога нашого і всього того, з чим Він послав мене до вас.","Отже, знайте, що ви помрете від меча, голоду і моровиці у тім місці, куди хочете йти, щоб жити там."],"x":{"2":"31.37.4|32.37.3","5":"1.19.8|5.24.24","10":"32.24.6","11":"31.41.10|31.43.5|32.30.10","16":"32.44.12|38.9.6","17":"36.6.12|36.14.21","18":"32.7.20|32.44.6|36.5.15"}},{"v":["Коли Єремія передав усьому народові всі слова Господа Бога їхнього, усі ті слова, з якими Господь, Бог їх, послав його до них,","тоді сказав Азарія, син Осаії, й Іоанан, син Карея, і всі зухвалі люди сказали Єремії: неправду ти говориш, не посилав тебе Господь Бог наш сказати: «не ходіть у Єгипет, щоб жити там»;","а Варух, син Нирії, збурює тебе проти нас, щоб віддати нас до рук халдеїв, щоб вони умертвили нас або відвели нас полоненими у Вавилон.","І не послухав Іоанан, син Карея, і всі воєначальники і весь народ гласу Господа, щоб залишитися у землі Юдейській.","І взяв Іоанан, син Карея, і всі воєначальники увесь залишок юдеїв, які повернулися з усіх народів, куди вони були вигнані, щоб жити у землі Юдейській,","чоловіків і дружин, і дітей, і дочок царя, і всіх тих, яких Навузардан, начальник охоронців, залишив з Годолією, сином Ахикама, сина Сафанового, і Єремію пророка, і Варуха, сина Нирії;","і пішли у землю Єгипетську, бо не послухали гласу Господнього, і дійшли до Тафниса.","І було слово Господнє до Єремії у Тафнисі:","візьми в руки свої великі камені і сховай їх у зім’ятій глині біля входу у дім фараона у Тафнисі, перед очима юдеїв,","і скажи їм: так говорить Господь Саваоф, Бог Ізраїлів: ось, Я пошлю і візьму Навуходоносора, царя Вавилонського, раба Мого, і поставлю престіл його на цих каменях, схованих Мною, і розкине він над ним чудовий намет свій","і прийде, й уразить землю Єгипетську: хто приречений на смерть, той відданий буде смерті; і хто у полон, піде в полон; і хто під меч, під меч.","І запалю вогонь у капищах богів єгиптян; і він спалить ті, а їх полонить, і одягнеться у землю Єгипетську, як пастух одягає на себе одяг свій, і вийде звідти спокійно,","і знищить статуї у Бефсамисі, що у землі Єгипетській, і капища богів єгипетських спалить вогнем."],"x":{"2":"11.25.23","4":"32.22.4","6":"11.25.26","7":"38.9.3|31.30.4","11":"32.15.2","12":"36.30.13|3.33.4|32.46.25"}},{"v":["Слово, яке було до Єремії про усіх юдеїв, що живуть у землі Єгипетській, які оселилися у Магдолі й Тафнисі, й у Нофі, й у землі Пафрос:","так говорить Господь Саваоф, Бог Ізраїлів: ви бачили усю біду, яку Я навів на Єрусалим і на весь рід юдейський; ось, вони тепер порожні, і ніхто не живе у них,","за нечестя їх, яке вони робили, прогнівляючи Мене, ходячи кадити і служити іншим богам, яких не знали ні вони, ні ви, ні батьки ваші.","Я посилав до вас усіх рабів Моїх, пророків, посилав з раннього ранку, щоб сказати: «не робіть це мерзенне діло, яке Я ненавиджу».","Але вони не слухали і не прихилили вуха свого, щоб навернутися від свого нечестя, не кадити іншим богам.","І вилилися лють Моя і гнів Мій і розгорілися у містах Юдеї і на вулицях Єрусалима; і вони зробилися руїнами і пустелею, як бачите нині.","І нині так говорить Господь Бог Саваоф, Бог Ізраїлів: навіщо ви робите це велике зло душам вашим, знищуючи у себе чоловіків і дружин, дорослих дітей і немовлят із середовища Юдеї, щоб не залишити у себе залишку,","прогнівляючи Мене творінням рук своїх, кадінням іншим богам у землі Єгипетській, куди ви прийшли жити, щоб погубити себе і зробитися прокляттям і ганьбою у всіх народів землі?","Хіба ви забули нечестя батьків ваших і нечестя царів юдейських, ваше власне нечестя і нечестя дружин ваших, яке вони робили у землі Юдейській і на вулицях Єрусалима?","Не смирилися вони і до цього дня, і не бояться і не роблять за законом Моїм і за уставами Моїми, які Я дав вам і батькам вашим.","Тому так говорить Господь Саваоф, Бог Ізраїлів: ось, Я поверну проти вас лице Моє на загибель і на знищення усієї Юдеї","і візьму юдеїв, які залишилися, які повернули лице своє, щоб іти у землю Єгипетську і жити там, і всі вони будуть знищені, впадуть у землі Єгипетській; мечем і голодом будуть знищені; від малого і до великого помруть від меча і голоду, і будуть прокляттям і жахом, наругою і ганьбою.","Відвідаю тих, що живуть у землі Єгипетській, як Я відвідав Єрусалим, мечем, голодом і моровицею,","і ніхто не уникне і не вціліє із залишку юдеїв, які прийшли у землю Єгипетську, щоб пожити там і потім повернутися у землю Юдейську, куди вони всією душею бажають повернутися, щоб жити там; ніхто не повернеться, крім тих, які втечуть звідти.","І відповідали Єремії усі чоловіки, які знали, що дружини їхні кадять іншим богам, і всі дружини, які стояли там у великій кількості, і весь народ, який жив у землі Єгипетській, у Пафосі, і сказали:","слово, яке ти говорив нам ім’ям Господа, ми не слухаємо від тебе;","але неодмінно будемо робити усе те, що вийшло з вуст наших, щоб кадити богині неба і виливати їй узливання, як ми робили, ми і батьки наші, царі наші і князі наші, у містах Юдеї і на вулицях Єрусалима, тому що тоді ми були ситі і щасливі і лиха не бачили.","А з того часу, як перестали ми кадити богині неба і виливати їй узливання, терпимо в усьому нестаток і гинемо від меча і голоду.","І коли ми кадили богині неба і виливали їй узливання, то хіба без відома чоловіків наших робили ми їй пиріжки з зображенням її і виливали їй узливання?","Тоді сказав Єремія всьому народові, чоловікам і дружинам, і всьому народові, який так відповідав йому:","чи не це кадіння, яке звершували ви у містах юдейських і на вулицях Єрусалима, ви і батьки ваші, царі ваші і князі ваші, і народ країни, згадав Господь? І чи не воно зійшло Йому на серце?","Господь не міг більше терпіти злих діл ваших і мерзот, які ви робили; тому і зробилася земля ваша пустелею і жахом, і прокляттям, без жителів, як бачите нині.","Оскільки ви, звершуючи те куріння, грішили перед Господом і не слухали гласу Господа, і не чинили за законом Його і за встановленнями Його, і за веліннями Його, то й осягла вас ця біда, як бачите нині.","І сказав Єремія усьому народові і всім жінкам: слухайте слово Господнє, всі юдеї, які у землі Єгипетській:","так говорить Господь Саваоф, Бог Ізраїлів: ви і дружини ваші, що вустами своїми говорили, те і руками своїми робили; ви говорите: «станемо виконувати обітниці наші, які ми обіцяли, щоб кадити богині неба і виливати їй узливання», — твердо тримайтеся обітниць ваших і у точності виконуйте обітниці ваші.","За те вислухайте слово Господнє, всі юдеї, які живуть у землі Єгипетській: ось, Я поклявся великим ім’ям Моїм, — говорить Господь, — що не буде вже на усій землі Єгипетській вимовлятися ім’я Моє вустами будь-якого юдея, який говорить: «живий Господь Бог!»","Ось, Я буду спостерігати над вами на погибель, а не на добро; й усі юдеї, які у землі Єгипетській, будуть гинути від меча і голоду, доки зовсім не знищаться.","Тільки невелика кількість тих, що уникли меча, повернеться із землі Єгипетської у землю Юдейську, і дізнаються всі юдеї, які залишилися, що прийшли в землю Єгипетську, щоб пожити там, чиє слово збудеться: Моє чи їх.","І ось вам знамення, — говорить Господь, — що Я відвідаю вас на цьому місці, щоб ви знали, що збудуться слова Мої про вас на погибель вам.","Так говорить Господь: ось, Я віддам фараона Вафрія, царя Єгипетського, до рук ворогів його і до рук тих, що шукають душі його, як віддав Седекію, царя Юдейського, до рук Навуходоносора, царя Вавилонського, ворога його і який шукав душі його."],"x":{"1":"32.46.14|36.29.14|36.30.14","3":"1.23.24","4":"32.25.4","5":"32.7.24|32.11.8","6":"32.42.18","11":"40.9.4","12":"32.44.27|3.5.21","13":"32.24.10|32.29.17|32.42.17","14":"32.44.11","15":"32.7.18","16":"32.6.16","17":"4.29.19|36.20.32|32.7.18","18":"11.6.25:33","19":"46.1.5|32.7.18","22":"32.26.6|32.44.12","26":"32.44.24","27":"32.31.28|37.9.14","30":"32.21.7|32.22.25|13.36.17:20"}},{"v":["Слово, яке пророк Єремія сказав Варуху, синові Нирії, коли він написав слова ці з уст Єремії у книгу, у четвертий рік Іоакима, сина Іосії, царя Юдейського:","так говорить Господь, Бог Ізраїлів, до тебе, Варух:","ти говориш: «горе мені! тому що Господь приклав скорботу до хвороби моєї; я знеміг від зітхань моїх, і не знаходжу спокою».","Так скажи йому: так говорить Господь: ось, що Я побудував, зруйную, і що насадив, викоріню, — усю цю землю.","А ти просиш собі великого: не проси; бо ось, Я наведу біду на всяку плоть, — говорить Господь, — а тобі замість здобичі залишу душу твою в усіх місцях, куди тільки підеш."],"x":{"1":"32.36.4","4":"32.24.6|40.9.11","5":"62.12.16|32.21.9"}},{"v":["Слово Господнє, яке було до Єремії пророка про народи язичницькі:","про Єгипет, про військо фараона Нехао, царя Єгипетського, яке було біля ріки Євфрату в Кархемисі, і яке уразив Навуходоносор, цар Вавилонський, у четвертий рік Іоакима, сина Іосії, царя Юдейського.","Готуйте щити і списи, і вступайте у бій;","сідлайте коней і сідайте, вершники, і станьте у шоломах; гостріть списи, вдягайтеся у броню.","Чому ж, бачу Я, вони злякалися і повернули назад? і сильні їх уражені, і біжать не оглядаючись; звідусюди жах, — говорить Господь.","Не втече прудконогий, і не спасеться сильний; на півночі, біля ріки Євфрату, вони спіткнуться і впадуть.","Хто це піднімається, як ріка, і, як потоки, хвилюються води його?","Єгипет піднімається, як ріка, і, як потоки, хвилюються води його, і говорить: «піднімуся і покрию землю, погублю місто і жителів його».","Сідайте на коней, і мчіть, колісниці, і виступайте, сильні ефіопляни і лівіяни, озброєні щитом, і лідяни, які тримають луки і натягують їх;","бо день цей у Господа Бога Саваофа є день помсти, щоб помститися ворогам Його; і меч буде пожирати, і насититься й уп’ється кров’ю їх; бо це Господу Богу Саваофу буде жертвоприношення у землі північній, біля ріки Євфрату.","Піди у Галаад і візьми бальзаму, діво, дочко Єгипту; даремно ти будеш примножувати лікування, немає для тебе зцілення.","Почули народи про посоромлення твоє, і волання твоє наповнило землю; бо сильний зіштовхнувся із сильним, і обоє разом упали.","Слово, яке сказав Господь пророку Єремії про нашестя Навуходоносора, царя Вавилонського, щоб уразити землю Єгипетську:","сповістіть у Єгипті і дайте знати у Магдолі, і дайте знати у Нофі і Тафнисі; скажіть: «ставай і готуйся, бо меч пожирає околиці твої».","Чому сильний твій повалений? — Не встояв, тому що Господь погнав його.","Він примножив тих, що падають, навіть падали одне на одного і говорили: «вставай і повернемося до народу нашого у рідну нашу землю від згубного меча».","А там кричать: «фараон, цар Єгипту, знітився; він пропустив домовлений час».","Живу Я, говорить Цар, Якого ім’я Господь Саваоф: як Фавор серед гір і як Кармил біля моря, так напевне прийде він.","Готуй собі потрібне для переселення, дочко — жителько Єгипту, бо Ноф буде спустошений, зруйнований, залишиться без жителя.","Єгипет — прекрасна телиця; але загибель від півночі йде, йде.","І найманці його серед нього, як вгодовані тельці, — і самі повернулися назад, побігли всі, не устояли, тому що прийшов на них день загибелі їх, час відвідування їх.","Голос його несеться, як зміїний; вони йдуть з військом, прийдуть на нього із сокирами, як дроворуби;","вирубають ліс його, — говорить Господь, — бо вони незліченні; їх більше, ніж сарани, і немає ліку їм.","Осоромлена дочка Єгипту, віддана до рук народу північного.","Господь Саваоф, Бог Ізраїлів, говорить: ось, Я відвідаю Аммона, який у Но, і фараона і Єгипет, і богів його і царів його, фараона і тих, що надіються на нього;","і віддам їх до рук тих, що шукають душі їхньої, і до рук Навуходоносора, царя Вавилонського, і до рук рабів його; але після того буде він населений, як у минулі дні, — говорить Господь.","Ти ж не бійся, рабе Мій Якове, і не страшися, Ізраїлю: бо ось, Я спасу тебе з далекої країни і сíм’я твоє із землі полону їх; і повернеться Яків, і буде жити спокійно і мирно, і ніхто не буде устрашати його.","Не бійся, рабе Мій Якове, — говорить Господь: бо Я з тобою; Я знищу всі народи, до яких Я вигнав тебе, а тебе не знищу, а тільки покараю тебе за мірою; непокараним же не залишу тебе."],"x":{"2":"13.35.20|32.25.19","3":"36.23.24","4":"32.51.11","5":"32.47.3","9":"36.27.10","10":"31.2.12|32.25.33","11":"32.8.22","14":"32.44.1","18":"10.18.19|40.9.3","21":"32.50.31","25":"36.30.15","27":"31.44.2-4|32.30.10","28":"0.26.24|31.27.8|31.41.10"}},{"v":["Слово Господа, яке було до пророка Єремії про филистимлян, перше ніж фараон уразив Газу.","Так говорить Господь: ось, піднімаються води з півночі і зробляться потоком, який наводнює, і потоплять землю й усе, що наповнює її, місто і тих, що живуть у ньому; тоді заволають люди, і заридають усі мешканці країни.","Від гучного тупоту копит сильних коней його, від стукоту колісниць його, від звуку коліс його, батьки не оглянуться на дітей своїх, тому що руки у них опустяться","від того дня, який прийде знищити усіх филистимлян, відняти у Тира і Сидона усіх інших помічників, бо Господь розорить филистимлян, залишок острова Кафтора.","Оплішивіла Газа, гине Аскалон, залишок долини їх.","Доки будеш сікти, о, меч Господній! доки ти не заспокоїшся? повернися у піхви твої, перестань і заспокойся.","Але як тобі заспокоїтися, коли Господь дав повеління проти Аскалона і проти берега морського? туди Він спрямував його."],"x":{"1":"36.25.15","2":"76.17.15","3":"76.9.9","4":"40.1.10|0.10.14|4.2.23"}},{"v":["Про Моав так говорить Господь Саваоф, Бог Ізраїлів: горе Нево́! він спустошений; Кариафаїм посоромлений і взятий; Мизгав посоромлений і знищений.","Немає вже слави Моава; у Есевоні задумують проти нього зло: «підемо, знищимо його із числа народів». І ти, Мадмено, загинеш; меч іде слідом за тобою.","Чутно волання від Оронаїма, спустошення і руйнування велике.","Знищений Моав; волання підняли діти його.","На підйомі у Лухит плач за плачем здіймається; і на спуску з Оронаїма ворог чує волання про руйнування.","Біжіть, рятуйте життя своє, і будьте подібні до оголеного дерева у пустелі.","Оскільки ти сподівався на діла твої і на скарби твої, тому і ти будеш узятий, і Хамос піде у полон разом зі своїми священиками і своїми князями.","І прийде спустошувач на всяке місто, і місто не уціліє; і загине долина, і спорожніє рівнина, як сказав Господь.","Дайте крила Моаву, щоб він міг полетіти; міста його будуть пустелею, тому що не буде кому жити у них.","Проклятий, хто діло Господнє робить недбало, і проклятий, хто утримує меч Його від крови!","Моав від юности своєї був у спокої, сидів на дріжджах своїх і не переливали його із посудини у посудину, і у полон не ходив; тому залишався у ньому смак його, і запах його не змінювався.","Тому ось, приходять дні, — говорить Господь, — коли Я пошлю до нього переливачів, які переллють його і спорожнять посудини його, і розіб’ють глечики його.","І посоромлений буде Моав заради Хамоса, як дім Ізраїлів посоромлений був заради Вефиля, надії своєї.","Чому ви говорите: «ми люди хоробрі і міцні для війни»?","Спустошений Моав, і міста його горять, і добірні юнаки його пішли на заколення, — говорить Цар, — Господь Саваоф ім’я Його.","Близька загибель Моава, і сильно поспішає біда його.","Пошкодуйте за ним, усі сусіди його й усі, хто знає ім’я його, скажіть: «як знищений жезл сили, посох слави!»","Зійди з висоти величі і сиди у спразі, дочко — жителько Дивона, бо спустошувач Моава прийде до тебе і знищить укріплення твої.","Стань при дорозі і дивися, жителько Ароера, запитуй того, хто біжить і спасається: «що трапилося?»","Посоромлений Моав, бо знищений; ридайте і волайте, оголосіть в Арноні, що спустошено Моав.","І суд прийшов на рівнини, на Халон і на Іаацу, і на Мофаф,","і на Дивон і на Нево́, і на Бет-Дивлафаїм,","і на Кариафаїм і на Бет-Гамул, і на Бет-Маон,","і на Кериоф і на Восор, і на всі міста землі Моавитської, далекі і близькі.","Відсічений ріг Моава, і правиця його знищена, — говорить Господь.","Напоїть його п’яним, бо він піднісся проти Господа; і нехай Моав валяється у блювотині своїй, і сам буде посміянням.","Чи не був осміяним у тебе Ізраїль? хіба він між злодіями був упійманий, що ти, бувало, лиш тільки заговориш про нього, хитаєш головою?","Залиште міста і живіть на скелях, жителі Моава, і будьте як голуби, які роблять гнізда при вході у печеру.","Чули ми про гордість Моава, гордість надмірну, про його зарозумілість і його гордовитість, і чванливість його і звеличування серця його.","Знаю Я зухвалість його, — говорить Господь, — але це ненадійно; порожні слова його: не так зроблять.","Тому буду ридати про Моав і волати за весь Моав; будуть зітхати за мужів Кирхареса.","Буду плакати за тебе, винограднику Севамський, плачем Іазера; паростки твої простягалися за море, досягали озера Іазера; спустошувач напав на літні плоди твої і на дозрілий виноград.","Радість і веселощі відняті від Кармила і від землі Моава. Я покладу кінець вину в точилах; не будуть більше топтати у них з піснями; крик битви буде, а не крик радости.","Від волання Есевона до Елеали і до Іааци вони піднімуть голос свій від Сигора до Оронаїма, до третьої Егли, бо і води Нимрима висохнуть.","Знищу в Моаві, — говорить Господь, — тих, що приносять жертви на висотах і кадять богам його.","Тому серце моє стогне за Моав, як сопілка; за жителів Кирхареса стогне серце моє, як сопілка, бо багатства, ними набуті, загинули:","у кожного голова го́ла й у кожного борода зменшена; у всіх на руках подряпини і на стегнах веретище.","На усіх покрівлях Моава і на вулицях його загальний плач, бо Я знищив Моав, як непотрібну посудину, — говорить Господь.","«Який знищений він!» — будуть говорити ридаючи; «як Моав покрився соромом, повернувши тил!». І буде Моав осміяним і жахом для усіх навколишніх його,","бо так говорить Господь: ось, як орел, налетить він і розкриє крила свої над Моавом.","Міста будуть узяті, й укріплення завойовані, й серце хоробрих моавитян буде у той день, як серце жінки, яка мучиться пологами.","І знищений буде Моав із числа народів, тому що він повстав проти Господа.","Жах і яма і петля — для тебе, жителю Моава, — сказав Господь.","Хто втече від жаху, впаде в яму; а хто вийде з ями, потрапить у зашморг, бо Я наведу на нього, на Моава, час відвідання їх, — говорить Господь.","Під тінню Есевона зупинилися ті, що біжать, знесилівши; але вогонь вийшов з Есевона і полум’я із середовища Сигона, і пожере бік Моава і тім’я синів непокірних.","Горе тобі, Моаве! загинув народ Хамоса, бо сини твої взяті у полон, і дочки твої — у полон.","Але в останні дні поверну полон Моава, — говорить Господь. До цього суд на Моаві."],"x":{"1":"36.25.8-9","2":"32.11.19","5":"31.15.5","7":"32.5.17|32.49.4|10.11.7","11":"46.1.12","13":"10.12.29","18":"31.47.1","20":"31.16.7","24":"40.2.2|31.63.1","25":"33.2.3|36.30.21","27":"32.2.26","29":"31.16.6","32":"31.16.8-9","33":"31.16.10","34":"32.25.25|31.15.4-6","36":"31.16.11|33.1.20","37":"31.15.2-3|36.7.18","38":"32.22.28|32.51.34","40":"45.1.8|37.7.4|38.8.1","41":"32.30.6","43":"31.24.17","44":"40.5.19","45":"3.21.28","46":"3.21.29","47":"32.49.39"}},{"v":["Про синів Аммонових так говорить Господь: хіба немає синів у Ізраїлю? хіба немає у нього спадкоємця? Чому ж Малхом заволодів Гадом, і народ його живе у містах його?","Тому ось, настають дні, — говорить Господь, — коли у Равві синів Аммонових чутно буде крик битви, і зробиться вона купою руїн, і міста її будуть спалені вогнем, і оволодіє Ізраїль тими, які володіли ним, — говорить Господь.","Ридай, Есевоне, бо спустошено Гай; кричіть, дочки Равви, опояшіться веретищем, плачте і блукайте по горо́дах, бо Малхом піде у полон разом зі священиками і князями своїми.","Чого хвалишся долинами? Потече долина твоя кров’ю, віроломна дочко, що сподіваєшся на скарби свої, що говориш: «хто прийде до мене?»","Ось, Я наведу на тебе жах з усіх околиць твоїх, — говорить Господь Бог Саваоф; розбіжитеся, хто куди, і ніхто не збере тих, що розбіглися.","Але після того Я поверну полон синів Аммонових, — говорить Господь.","Про Едом так говорить Господь Саваоф: хіба немає більше мудрости у Фемані? хіба не стало ради у розумних? хіба збідніла мудрість їх?","Біжіть, повернувши тил, ховайтеся у печерах, жителі Дедана, бо загибель Ісава Я наведу на нього, — час відвідування Мого.","Якби збирачі винограду прийшли до тебе, то, напевне, залишили б кілька незібраних ягід. І якби злодії прийшли уночі, то вони украли б, скільки їм потрібно.","А Я догола обберу Ісава, відкрию потаємні місця його, і сховатися він не може. Знищене буде плем’я його, і брати його і сусіди його; і не буде його.","Залиш сиріт твоїх, Я підтримаю життя їх, і удови твої нехай надіються на Мене.","Бо так говорить Господь: ось і ті, яким не призначено було пити чашу, неодмінно будуть пити її, і чи ти залишишся непокараним? Ні, не залишишся непокараним, але неодмінно будеш пити чашу.","Бо Мною клянуся, — говорить Господь, — що жахом, посміянням, пустелею і прокляттям буде Восор, і всі міста його зробляться вічними пустелями.","Я чув поголос від Господа, і посол посланий до народів сказати: зберіться і йдіть проти нього, і піднімайтеся на війну.","Бо ось, Я зроблю тебе малим між народами, знехтуваним між людьми.","Грізне становище твоє і гордовитість серця твого звабили тебе, що живеш у розщілинах скель і займаєш вершини пагорбів. Але, хоч би ти, як орел, високо звив гніздо твоє, і звідти скину тебе, — говорить Господь.","І буде Едом жахом; усякий, хто проходить мимо, здивується і посвистить, дивлячись на усі виразки його.","Як знищені Содом і Гоморра і сусідні міста їх, — говорить Господь, — так і там жодна людина не буде жити, і син людський не зупиниться у ньому.","Ось, виходить він, як лев, з узвишшя Йордану на укріплені житла; але Я змушу їх поспішно піти з Ідумеї, і хто обраний, того поставлю над нею. Бо хто подібний до Мене? і хто вимагатиме відповіді від Мене? і який пастир протистане Мені?","Отже, вислухайте визначення Господа, яке Він поставив про Едом, і наміри Його, які Він має щодо жителів Фемана: істинно, найменші зі стад поведуть їх і спустошать житла їх.","Від шуму падіння їх потрясеться земля, і відгомін крику їх чутно буде біля Червоного моря.","Ось, як орел підніметься він, і полетить, і розпустить крила свої над Восором; і серце хоробрих ідумеян буде у той день, як серце жінки під час пологів.","Про Дамаск. — Посоромлені Емаф і Арпад, бо, почувши скорботну звістку, вони впали у відчай; тривога на морі, заспокоїтися не можуть.","Злякався Дамаск і кинувся навтіки; страх оволодів ним; біль і муки схопили його, як жінку під час пологів.","Як не вціліло місто слави, місто радости моєї?","Отже, впадуть юнаки його на вулицях його, і всі воїни загинуть у той день, — говорить Господь Саваоф.","І запалю вогонь на стінах Дамаска, і знищить палаци Венадада.","Про Кидар і про царства Асорські, які уразив Навуходоносор, цар Вавилонський, так говорить Господь: вставайте, виступайте проти Кидара, і спустошуйте синів сходу!","Намети їхні і овець їхніх візьмуть собі, і покрови їхні і все начиння їхнє, і верблюдів їхніх візьмуть, і будуть кричати їм: «жах звідусюди!»","Біжіть, ідіть скоріше, сховайтеся у прірві, жителі Асора, — говорить Господь, бо Навуходоносор, цар Вавилонський, виніс рішення про вас і склав проти вас задум.","Вставайте, виступайте проти народу мирного, який живе безтурботно, — говорить Господь: ні дверей, ні запорів немає у нього, живуть поодинці.","Верблюди їхні віддані будуть у здобич, і безліч стад їхніх — на розкрадання; і розсію їх по усіх вітрах, цих, що стрижуть волосся на скронях, і з усіх боків їх наведу на них загибель, — говорить Господь.","І буде Асор житлом шакалів, вічною пустелею; людина не буде жити там, і син людський не буде зупинятися у ньому.","Слово Господа, яке було до Єремії пророка проти Елама, на початку царювання Седекії, царя Юдейського:","так говорить Господь Саваоф: ось, Я скрушу лук Елама, головну силу їх.","І наведу на Елам чотири вітри від чотирьох країв неба і розвію їх по усіх цих вітрах, і не буде народу, до якого не прийшли б вигнані еламити.","Й уражу еламитян страхом перед ворогами їх і перед тими, що шукають душí їх; і наведу на них біду, гнів Мій, — говорить Господь, — і пошлю услід їм меч, доки не знищу їх.","І поставлю престіл Мій у Еламі, і знищу там царя і князів, — говорить Господь.","Але в останні дні поверну полон Елама, — говорить Господь."],"x":{"1":"36.25.2-3","2":"40.1.14","3":"5.8.2","4":"32.21.13","6":"32.33.7","7":"36.25.12|31.29.14|41.1.8","8":"32.49.30|32.50.31","9":"41.1.5","12":"56.4.17","13":"32.18.16","14":"41.1.1","15":"41.1.2","16":"32.51.55|40.9.3","17":"32.50.13","18":"0.19.25|31.13.19-20|32.50.40","19":"32.50.44|24.41.1","21":"32.50.46","22":"32.48.40","23":"31.17.1|31.36.19|40.1.3","24":"32.4.31","26":"32.50.30","27":"40.1.4","28":"32.2.10|31.21.16","32":"36.5.10","34":"32.25.25","35":"31.22.6","39":"32.48.47"}},{"v":["Слово, що вирік Господь про Вавилон і про землю халдеїв через Єремію пророка:","сповістіть і розголосіть між народами, і підніміть знамено, оголосіть, не приховуйте, говоріть: «Вавилон узятий, Вил посоромлений, Меродах знищений, істукани його посоромлені, ідоли його знищені».","Бо від півночі піднявся проти нього народ, який зробить землю його пустелею, і ніхто не буде жити там, від людини до худоби, усі рушать і підуть.","У ті дні й у той час, — говорить Господь, — прийдуть сини Ізраїлеві, вони і сини Іудині разом, будуть ходити і плакати, і будуть шукати Господа Бога свого.","Будуть запитувати про путь до Сиону, і, звертаючи до нього лиця, будуть говорити: «йдіть і приєднайтеся до Господа союзом вічним, який не забудеться».","Народ Мій був, як загиблі вівці; пастирі їхні звабили їх з путі, розігнали їх по горах; блукали вони з гори на пагорб, забули постіль свою.","Усі, які знаходили їх, пожирали їх, і пригноблювачі їх говорили: «ми не винні, тому що вони згрішили перед Господом, перед оселею правди і перед Господом, надією батьків їхніх».","Біжіть із середовища Вавилона, і йдіть з Халдейської землі, і будьте, як козли попереду отари овець.","Бо ось, Я підніму і приведу на Вавилон збіговисько великих народів від землі північної, і розташуються проти нього, і він буде взятий; стріли у них, як у майстерного воїна, не повертаються марно.","І Халдея зробиться здобиччю їх; і спустошувачі її наситяться, — говорить Господь.","Бо ви веселилися, ви торжествували, розкрадачі спадщини Моєї; стрибали з радости, як телиця на траві, й іржали, як бойові коні.","У великому соромі буде мати ваша, почервоніє та, яка народила вас; ось майбуття тих народів — пустеля, суха земля і степ.","Від гніву Господа вона зробиться безлюдною, і вся вона буде порожня; усякий, хто буде проходити через Вавилон, здивується і посвистить, дивлячись на усі виразки його.","Вишикуйтеся у бойовий порядок навколо Вавилона; усі, що натягують лук, стріляйте у нього, не шкодуйте стріл, бо він згрішив проти Господа.","Здійміть крик проти нього з усіх боків; він подав руку свою; упали твердині його, зруйнувалися стіни його, бо це — відомста Господа; помщайтеся йому; як він чинив, так і чиніть з ним.","Знищіть у Вавилоні і того, хто сіє і діє серпом під час жнив; від страху згубного меча нехай кожен повернеться до народу свого, і кожен нехай біжить у землю свою.","Ізраїль — розсіяне стадо; леви розігнали його; раніше об’їдав його цар Ассирійський, а цей останній, Навуходоносор, цар Вавилонський, і кістки його розтрощив.","Тому так говорить Господь Саваоф, Бог Ізраїлів: ось, Я відвідаю царя Вавилонського і землю його, як відвідав царя Ассирійського.","І поверну Ізраїля на пасовище його, і буде він пастися на Кармилі і Васані, і душа його насититься на горі Єфремовій і у Галааді.","У ті дні й у той час, — говорить Господь, — будуть шукати неправди Ізраїлевої, і не буде її, і гріхів Іуди, і не знайдеться їх; бо прощу тих, яких залишу у живих.","Іди на неї, на землю обурливу, і покарай жителів її; спустошуй і знищуй усе за ними, — говорить Господь, — і зроби усе, що Я повелів тобі.","Шум битви на землі і велике руйнування!","Який розбитий і розтрощений молот усієї землі! Як Вавилон зробився жахом між народами!","Я розставив сіті для тебе, і ти пійманий, Вавилоне, не передбачаючи того; ти знайдений і схоплений, тому що повстав проти Господа.","Господь відкрив сховище Своє і взяв з нього сосуди гніву Свого, тому що у Господа Бога Саваофа є діло у землі Халдейській.","Ідіть на неї з усіх країв, відчиняйте житниці її, топчіть її як снопи, зовсім знищіть її, щоб нічого від неї не залишилося.","Убивайте усіх волів її, нехай ідуть на заколення; горе їм! бо прийшов день їх, час відвідання їх.","Чутний голос тих, що біжать і спасаються із землі Вавилонської, щоб сповістити на Сионі про помсту Господа Бога нашого, про помсту за храм Його.","Скличте проти Вавилона стрільців; усі, що натягують лук, розташуйтеся станом довкола нього, щоб ніхто не врятувався із нього; воздайте йому за ділами його; як він зробив, так робіть і з ним, бо він піднісся проти Господа, проти Святого Ізраїлевого.","За те упадуть юнаки його на вулицях його, й усі воїни його знищені будуть у той день, — говорить Господь.","Ось, Я — на тебе, гордине, — говорить Господь Бог Саваоф: бо прийшов день твій, час відвідання твого.","І спіткнеться гординя, й упаде, і ніхто не підніме його; і запалю вогонь у містах його, і пожере усе довкола його.","Так говорить Господь Саваоф: пригноблені сини Ізраїля, як і сини Іуди, і всі, хто полонив їх, міцно тримають їх і не хочуть відпустити їх.","Але Відкупитель їх сильний, Господь Саваоф ім’я Його; Він розгляне діло їх, щоб заспокоїти землю і привести у тремтіння жителів Вавилона.","Меч на халдеїв, — говорить Господь, і на жителів Вавилона, і на князів його, і на мудрих його;","меч на знахарів, і вони збожеволіють; меч на воїнів його, і вони устрашаться;","меч на коней його і на колісниці його і на усі різноплемінні народи серед нього, і вони будуть, як жінки; меч на скарби його, і вони будуть розкрадені;","засуха на води його, і вони висохнуть; бо це земля ідолів, і вони збожеволіють від ідольських страховиськ.","І оселяться там степові звірі з шакалами, і будуть жити на ній страуси, і не буде населена повіки і безлюдна у роди родів.","Як знищені Богом Содом і Гоморра і сусідні міста їх, — говорить Господь, — так і тут жодна людина не буде жити, і син людський не буде зупинятися.","Ось, іде народ від півночі, і народ великий, і багато царів піднімаються від країв землі;","тримають у руках лук і спис; вони жорстокі й немилосердні; голос їх гучний, як море; несуться на конях, вишикувалися як одна людина, щоб битися з тобою, дочко Вавилона.","Почув цар Вавилонський звістку про них, і руки у нього опустилися; скорбота огорнула його, муки, як жінку під час пологів.","Ось, піднімається він, як лев, з узвишшя Йордану на укріплені житла; але Я змушу їх поспішно піти з нього, і, хто обраний, тому доручу його. Бо хто подібний до Мене? і хто вимагатиме від Мене відповіді? І який пастир протистане Мені?","Отже, вислухайте визначення Господа, яке Він ухвалив про Вавилон, і наміри Його, які Він має щодо землі Халдейської: істинно, найменші зі стад поведуть їх; істинно, він спустошить житла їхні з ними.","Від шуму взяття Вавилона затремтить земля, і волання буде чутне між народами."],"x":{"1":"31.13.1|31.14.4","2":"31.46.1","3":"32.4.25|32.9.10","4":"31.55.6|38.3.5|38.6.1","6":"32.2.8|32.10.21|36.34.1-13","8":"31.48.20|32.51.6|76.18.4","11":"36.34.18:21","13":"32.18.16|32.49.17","15":"4.32.35|62.12.19","17":"11.15.19","18":"11.19.35|31.37.36","19":"10.18.19|4.32.14","20":"32.31.34|32.33.8|37.9.24","23":"31.13.19|31.14.4|76.18.17","25":"4.32.34|31.13.5|62.2.5","27":"32.46.21|11.25.9","29":"76.17.16|76.18.6","30":"32.49.26","31":"32.46.10|76.18.8","32":"32.11.16","37":"32.51.30","39":"31.13.21|76.18.2","40":"0.19.25|32.49.18","41":"32.6.22|43.5.5","43":"37.5.5-6","44":"32.49.19|24.41.1","45":"32.49.20:29","46":"32.49.21|32.51.29|76.18.15"}},{"v":["Так говорить Господь: ось, Я підніму на Вавилон і на тих, що живуть серед нього, супротивників Моїх.","І пошлю на Вавилон віяльників, і розвіють його, і спустошать землю його; бо у день біди нападуть на нього з усіх боків.","Нехай стрілець натягує лук проти того, хто натягує лук, і на того, хто величається бронею своєю; і не щадіть юнаків його, знищіть усе військо його.","Уражені нехай упадуть на землі Халдейській, і проколоті — на дорогах її.","Бо не овдовів Ізраїль та Іуда від Бога свого, Господа Саваофа; хоча земля їх повна гріхами перед Святим Ізраїлевим.","Біжіть із середовища Вавилона і спасайте кожен душу свою, щоб не загинути у беззаконні його, бо це час помсти у Господа, Він воздає йому відплату.","Вавилон був золотою чашею у руці Господа, яка п’янила усю землю; народи пили з неї вино і безумствували.","Раптово упав Вавилон і розбився; ридайте за ним, візьміть бальзаму для рани його: можливо, він зцілиться.","Лікували ми Вавилон, але не зцілився; залиште його, і підемо кожен у свою землю, тому що вирок про нього досяг небес і піднявся до хмар.","Господь вивів на світло правду нашу; підемо і звістимо на Сионі діло Господа Бога нашого.","Гостріть стріли, наповнюйте сагайдаки; Господь збудив дух царів мідійських, тому що у Нього є намір проти Вавилона, щоб знищити його, бо це є помста Господа, помста за храм Його.","Проти стін Вавилона підніміть знамено, посильте нагляд, розставте вартових, приготуйте засідки, бо, як Господь помислив, так і зробить, що вирік на жителів Вавилона.","О, ти, що живеш біля вод великих, багатий скарбами! прийшов кінець твій, міра жадібності твоїй.","Господь Саваоф поклявся Самим Собою: істинно говорю, що наповню тебе людьми, як сараною, і здіймуть крик проти тебе.","Він створив землю силою Своєю, утвердив вселенну мудрістю Своєю і розумом Своїм розпростер небеса.","За гласом Його шумлять води на небесах, і Він підносить хмари від країв землі, творить блискавки серед дощу і виводить вітер зі сховищ Своїх.","Безумствує усяка людина у своєму знанні, осоромлює себе всякий плавильник істуканом своїм, бо істукан його є неправда, і немає у ньому духу.","Це повна порожнеча, діло омани; під час відвідання їх вони зникнуть.","Не така, як їх, доля Якова, бо Бог його є Творець усього, й Ізраїль є жезл спадщини Його, ім’я Його — Господь Саваоф.","Ти у Мене — молот, зброя військова; тобою Я уражав народи і тобою розоряв царства;","тобою уражав коня і вершника його і тобою уражав колісницю і візника її;","тобою уражав чоловіка і дружину, тобою уражав старого і молодого, тобою уражав і юнака і дівчину;","і тобою уражав пастуха і стадо його, тобою уражав і землероба і робочу худобу його, тобою уражав і областеначальників і градоправителів.","І воздам Вавилону і усім жителям Халдеї за усе те зло, яке вони робили на Сионі в очах ваших, — говорить Господь.","Ось, Я — на тебе, горо згубна, що руйнуєш усю землю, — говорить Господь, — і простягну на тебе руку Мою, і скину тебе зі скель, і зроблю тебе горою обгорілою.","І не візьмуть з тебе наріжних каменів і каменю для основи, але вічно будеш запустінням, — говорить Господь.","Підніміть знамено на землі, сурміть трубою серед народів, озбройте проти нього народи, скличте на нього царства Араратські, Мінійські й Аскеназькі, поставте вождя проти нього, наведіть коней, як страшну сарану.","Озбройте проти нього народи, царів Мідії, областеначальників її і всіх градоправителів її, і усю землю, підвладну їй.","Трясеться земля і тріпоче, бо виповнюються над Вавилоном наміри Господа зробити землю Вавилонську пустелею, без жителів.","Перестали боротися сильні вавилонські, сидять в укріпленнях своїх; виснажилася сила їх, зробилися, як жінки, житла їхні спалені, засуви їхні розбиті.","Гонець біжить назустріч гінцеві, і вісник назустріч вісникові, щоб сповістити царя Вавилонського, що місто його узяте з усіх кінців,","і броди захоплені, й огорожі спалені вогнем, і воїни уражені страхом.","Бо так говорить Господь Саваоф, Бог Ізраїлів: дочка Вавилона подібна до току під час молотьби на ньому; ще трохи, і настане час жнив її.","Пожирав мене і гриз мене Навуходоносор, цар Вавилонський; зробив мене порожньою посудиною; поглинав мене, як дракон; наповнював утробу свою солодощами моїми, вивергав мене.","Образа моя і плоть моя — на Вавилоні, — скаже мешканка Сиону, і кров моя — на жителях Халдеї, — скаже Єрусалим.","Тому так говорить Господь: ось, Я вступлюся у твоє діло й помщуся за тебе, й осушу море його, і висушу канали його.","І Вавилон буде купою руїн, житлом шакалів, жахом і посміянням, без жителів.","Як леви, зарикають усі вони, і заревуть, як щенята лев’ячі.","Під час разпалення їх зроблю їм бенкет і напою їх, щоб вони повеселилися і поснули вічним сном, і не прокинулися, — говорить Господь.","Поведу їх, як ягнят на заколення, як баранів з козлами.","Як узятий Сесах, і завойована слава усієї землі! Як зробився Вавилон жахом між народами!","Кинулося на Вавилон море; він покрився безліччю хвиль його.","Міста його стали порожніми, землею сухою, степом, землею, де не живе жодна людина і де не проходить син людський.","І відвідаю Вила у Вавилоні, і вивергну з уст його проковтнуте ним, і народи не будуть уже стікатися до нього, навіть і стіни вавилонські упадуть.","Виходь із середовища його, народе Мій, і спасайте кожен душу свою від полум’яного гніву Господа.","Нехай не слабшає серце ваше, і не бійтеся поголосу, який буде чутно на землі; чутка прийде в один рік, і потім у другий рік, і на землі буде насильство, володар повстане на володаря.","Тому ось, приходять дні, коли Я відвідаю ідолів Вавилона, й уся земля його буде посоромлена, і всі уражені його впадуть серед нього.","І будуть торжествувати над Вавилоном небо і земля й усе, що на них; бо від півночі прийдуть до нього спустошувачі, — говорить Господь.","Як Вавилон повалював уражених ізраїльтян, так у Вавилоні будуть повалені уражені всієї країни.","Хто врятувався від меча, йдіть, не зупиняйтеся, згадайте здаля про Господа, і нехай зійде Єрусалим на серце ваше.","Соромно нам було, коли ми чули наругу: нечестя покривало лиця наші, коли чужоземці прийшли у святилище дому Господнього.","За те ось, приходять дні, — говорить Господь, — коли Я відвідаю ідолів його, і по всій землі його будуть стогнати поранені.","Хоч би Вавилон піднісся до небес, і хоч би він на висоті зміцнив твердиню свою; але від Мене прийдуть до нього спустошувачі, — говорить Господь.","Пронесеться гучний крик від Вавилона і велике руйнування — від землі Халдейської,","бо Господь спустошить Вавилон і покладе кінець гордовитого голосу в ньому. Зашумлять хвилі їх, як великі води, пролунає гучний голос їх.","Бо прийде на нього, на Вавилон, спустошувач, і взяті будуть ратоборці його, знищені будуть луки їхні; бо Господь, Бог відплати, воздасть відплату.","І напою доп’яна князів його і мудреців його, областеначальників його, і градоправителів його, і воїнів його, і заснуть сном вічним, і не прокинуться, — говорить Цар — Господь Саваоф ім’я Його.","Так говорить Господь Саваоф: товсті стіни Вавилона до основи будуть зруйновані, і високі ворота його будуть спалені вогнем; отже, дарма трудилися народи, і племена мучили себе для вогню.","Слово, яке пророк Єремія заповів Сераії, синові Нирії, синові Маасеї, коли він вирушав у Вавилон із Седекією, царем Юдейським, у четвертий рік його царювання; Сераія був головний постельничий.","Єремія вписав в одну книгу всі біди, які повинні прийти на Вавилон, усі ці слова, написані на Вавилон.","І сказав Єремія Сераії: коли ти прийдеш у Вавилон, то дивися, прочитай усі ці слова,","і скажи: «Господи! Ти вирік про місце це, що знищиш його так, що не залишиться у ньому ні людини, ні худоби, але воно буде вічною пустелею».","І коли закінчиш читання цієї книги, прив’яжи до неї камінь і кинь її на середину Євфрату,","і скажи: «так зануриться Вавилон і не постане від тієї біди, яку Я наведу на нього, і вони зовсім знеможуть». Досі слова Єремії."],"x":{"1":"31.13.1|32.4.11","2":"31.27.12","5":"53.14.18","6":"32.50.8","7":"32.25.27","8":"31.21.9|76.14.8|76.18.2:10","9":"76.16.19|76.18.5","10":"43.7.9","11":"32.46.4|32.50.28|31.13.17","13":"76.17.2","14":"40.6.8","15":"0.1.6|32.10.12","16":"25.134.7","17":"32.10.14|31.44.9","19":"32.10.16","20":"32.50.23","24":"32.30.16|32.50.29|70.1.6","25":"24.9.5|76.8.8","27":"32.6.4|0.8.4|31.37.38","30":"32.50.37","32":"32.50.38","33":"43.4.12|76.14.15","37":"32.50.13|76.18.2","38":"31.5.29","39":"31.29.10","41":"32.25.26","42":"31.8.7|36.26.3","45":"32.51.6","48":"76.18.20","52":"36.26.15","53":"25.138.8|40.9.2|41.1.4","56":"4.32.35|62.12.19|75.10.30","58":"31.2.15","60":"32.36.7","64":"76.18.21"}},{"v":["Седекія був двадцяти одного року, коли почав царювати, і царював у Єрусалимі одинадцять років; ім’я матері його — Хамуталь, дочка Єремії з Ливни.","І він робив лихе в очах Господа, усе те, що робив Іоаким;","тому гнів Господа був над Єрусалимом та Іудою до того, що Він відкинув їх від лиця Свого; і Седекія відійшов від царя Вавилонського.","І було, у дев’ятий рік його царювання, у десятий місяць, у десятий день місяця, прийшов Навуходоносор, цар Вавилонський, сам і все військо його, до Єрусалима, і обложили його, і збудували навколо нього насип.","І знаходилося місто в облозі до одинадцятого року царя Седекії.","У четвертому місяці, у дев’ятий день місяця, голод у місті посилився, і не було хліба у народу землі.","Зроблений був пролам у місто, і побігли усі військові, і вийшли з міста вночі воротами, що знаходяться між двома стінами, біля царського саду, і пішли дорогою степу; халдеї ж були навколо міста.","Військо халдейське погналося за царем, і наздогнали Седекію на рівнинах єрихонських, і все військо його розбіглося від нього.","І взяли царя, і привели його до царя Вавилонського, у Ривлу, у землю Емаф, де він промовив над ним суд.","І заколов цар Вавилонський синів Седекії перед очима його, і всіх князів юдейських заколов у Ривлі.","А Седекії виколов очі і повелів закувати його мідними ланцюгами; і відвів його цар Вавилонський у Вавилон і посадив його у дім сторо́жі до дня смерти його.","У п’ятий місяць, у десятий день місяця, — це був дев’ятнадцятий рік царя Навуходоносора, царя Вавилонського, — прийшов Навузардан, начальник охоронців, який стояв перед царем Вавилонським, у Єрусалим","і спалив дім Господній, і дім царя, і всі доми в Єрусалимі, і всі доми великі спалив вогнем.","І все військо халдейське, яке було з начальником охоронців, зруйнувало усі стіни навколо Єрусалима.","Бідних з народу та інший народ, який залишався у місті, і перебіжчиків, які перейшли до царя Вавилонського, і взагалі залишок простого народу Навузардан, начальник охоронців, виселив.","Тільки трохи з бідного народу землі Навузардан, начальник охоронців, залишив для виноградників і землеробства.","І стовпи мідні, які були у домі Господньому, і підстави, і мідне море, що в домі Господньому, зламали халдеї й віднесли усю мідь їх у Вавилон.","І тази, і лопатки, і ножі, і чаші, і ложки, і всі мідні сосуди, які вживалися при богослужінні, взяли;","і блюда, і щипці, і чаші, і казани, і лампади, і фіміамники, і кру́жки, що було золоте — золоте, і що було срібне — срібне, узяв начальник охоронців;","також два стовпи, одне море і дванадцять мідних волів, що служили підставами, які цар Соломон зробив у домі Господньому, — міді в усіх цих речах неможливо було зважити.","Стовпи ці були кожен стовп у вісімнадцять ліктів висоти, і шнурок у дванадцять ліктів обіймав його, а товщина стінок його, всередині порожнього, у чотири пальці.","І вінець на ньому мідний, а висота вінця п’ять ліктів; і сітка і гранатові яблука навколо були усі мідні; те саме і на іншому стовпі з гранатовими яблуками.","Гранатових яблук було по усіх боках дев’яносто шість; усіх яблук навколо сітки сто.","Начальник охоронців узяв також Сераію первосвященика і Цефанію, другого священика, і трьох сторожів порогу.","І з міста узяв одного євнуха, який був начальником над військовими людьми, і сім чоловік, які стояли перед лицем царя, які знаходилися у місті, і головного писаря у війську, який записував у військо народ землі, і шістдесят чоловік з народу країни, знайдених у місті.","І взяв їх Навузардан, начальник охоронців, і відвів їх до царя Вавилонського у Ривлу.","І уразив їх цар Вавилонський і умертвив їх у Ривлі, у землі Емаф; і виселений був Іуда із землі своєї.","Ось народ, який виселив Навуходоносор: у сьомий рік три тисячі двадцять три юдеї;","у вісімнадцятий рік Навуходоносора з Єрусалима виселено вісімсот тридцять дві душі;","у двадцять третій рік Навуходоносора Навузардан, начальник охоронців, виселив юдеїв сімсот сорок п’ять душ: усього чотири тисячі шістсот душ.","У тридцять сьомий рік після переселення Іоакима*, царя Юдейського, у дванадцятий місяць, у двадцять п’ятий день місяця, Евильмеродах, цар Вавилонський, у перший рік царювання свого, підніс Іоакима, царя Юдейського, і вивів його із в’язничного дому.","І розмовляв з ним дружньо, і поставив престіл його вище престолу царів, які були у нього у Вавилоні; 33 і перемінив в’язничний одяг його, і він завжди у нього обідав у всі дні життя свого.","Й утримання його, утримання постійне, видавалося йому від царя з дня у день до дня смерти його, у всі дні життя його."],"x":{"1":"11.24.18|13.36.11","3":"11.24.20","4":"11.25.1|32.39.1","6":"11.25.3","8":"11.25.5|33.4.19-20","9":"11.25.6","10":"32.39.6","11":"11.25.7|36.12.13|36.17.16","12":"11.25.8","13":"11.25.9|32.39.8","16":"11.25.12","17":"13.3.15|32.27.19","18":"11.25.14","19":"11.25.15","20":"10.7.23","21":"10.7.15|11.25.17","24":"11.25.18","27":"11.25.21","30":"14.2.64","31":"11.25.27"},"n":{"31":["Ієхонії."]}}];
